css:
.dnp-appeal {
  width: 100%;
  height: var(--dnp-appeal-h, 680px);
  container-type: inline-size;
  container-name: dnp-appeal;
  position: relative;
  isolation: isolate;
  overflow: hidden;
  background: var(--dnp-appeal-bg);
  color: var(--dnp-appeal-ink);
  font: 13px/1.45 var(--dnp-appeal-sans);
  accent-color: var(--dnp-appeal-accent);
  -webkit-font-smoothing: antialiased;
  & *, & *::before, & *::after { box-sizing: border-box; }
  & :where(h1, h2, h3, h4, p, ol, ul, dl, dd, figure) { margin: 0; padding: 0; }
  & :where(ol, ul) { list-style: none; }
  & :where(h1, h2, h3, h4) { text-wrap: balance; font-weight: 650; }
  & :where(p) { text-wrap: pretty; }
  & :where(button, input, select) { font: inherit; color: inherit; letter-spacing: inherit; }
  & :where(button) { background: none; border: 0; padding: 0; cursor: pointer; -webkit-tap-highlight-color: transparent; }
  & :where(button:disabled, [aria-disabled="true"]) { cursor: not-allowed; }
  & :where(svg) { display: block; overflow: visible; }
  & :where(table) { border-collapse: collapse; width: 100%; }
  & :focus-visible { outline: 2px solid var(--dnp-appeal-focus, var(--dnp-appeal-accent)); outline-offset: 2px; }
  & [hidden] { display: none !important; }
  & .dnp-appeal__i { width: 18px; height: 18px; flex: none; fill: none; stroke: currentColor; stroke-width: 1.75; stroke-linecap: round; stroke-linejoin: round; }
  & .dnp-appeal__sr { position: absolute; width: 1px; height: 1px; overflow: hidden; clip-path: inset(50%); white-space: nowrap; }
}
.dnp-appeal__scroll {
  overflow: auto;
  overscroll-behavior: contain;
  scrollbar-width: thin;
  scrollbar-color: color-mix(in oklch, var(--dnp-appeal-ink) 22%, transparent) transparent;
  &::-webkit-scrollbar { width: 8px; height: 8px; }
  &::-webkit-scrollbar-thumb { background: color-mix(in oklch, var(--dnp-appeal-ink) 20%, transparent); border-radius: 8px; border: 2px solid transparent; background-clip: padding-box; }
}
.dnp-appeal__tip {
  position: absolute; left: 0; top: 0; z-index: 40;
  pointer-events: none;
  min-width: 128px; max-width: 260px;
  padding: 8px 10px;
  border-radius: 10px;
  background: var(--dnp-appeal-tipbg, color-mix(in oklch, var(--dnp-appeal-ink) 94%, var(--dnp-appeal-bg)));
  color: var(--dnp-appeal-tipink, var(--dnp-appeal-bg));
  font-size: 12px; line-height: 1.4;
  font-variant-numeric: tabular-nums;
  box-shadow: 0 10px 28px -10px oklch(0 0 0 / .45);
  opacity: 0; scale: .96;
  transition: opacity .14s, scale .2s cubic-bezier(.22, 1, .36, 1);
  &.is-on { opacity: 1; scale: 1; }
  & b { font-weight: 650; }
  & .dnp-appeal__tt { display: block; font-size: 11px; letter-spacing: .04em; text-transform: uppercase; opacity: .7; margin-bottom: 3px; }
  & .dnp-appeal__trow { display: flex; justify-content: space-between; gap: 14px; align-items: baseline; }
  & .dnp-appeal__trow i { display: inline-block; width: 8px; height: 8px; border-radius: 2px; margin-right: 6px; background: var(--c); }
}
.dnp-appeal__toast {
  position: absolute; left: 50%; bottom: 18px; z-index: 50;
  max-width: min(440px, calc(100% - 32px));
  padding: 10px 16px;
  border-radius: 12px;
  background: var(--dnp-appeal-tipbg, color-mix(in oklch, var(--dnp-appeal-ink) 94%, var(--dnp-appeal-bg)));
  color: var(--dnp-appeal-tipink, var(--dnp-appeal-bg));
  font-size: 12.5px; font-weight: 550;
  box-shadow: 0 16px 40px -14px oklch(0 0 0 / .5);
  pointer-events: none;
  translate: -50% 16px; opacity: 0;
  transition: translate .45s cubic-bezier(.22, 1, .36, 1), opacity .25s;
  &.is-on { translate: -50% 0; opacity: 1; }
}

@property --dnp-appeal-fill { syntax: "<number>"; inherits: true; initial-value: 0; }
@property --dnp-appeal-glow { syntax: "<percentage>"; inherits: false; initial-value: 0%; }

.dnp-appeal {
  /* re-theme with these four */
  --dnp-appeal-bg: oklch(0.972 0.014 80);
  --dnp-appeal-ink: oklch(0.27 0.035 42);
  --dnp-appeal-accent: oklch(0.6 0.19 31);
  --dnp-appeal-gold: oklch(0.79 0.14 78);
  /* derived */
  --dnp-appeal-card: color-mix(in oklch, var(--dnp-appeal-bg), white 62%);
  --dnp-appeal-side: color-mix(in oklch, var(--dnp-appeal-bg), var(--dnp-appeal-ink) 4%);
  --dnp-appeal-line: color-mix(in oklch, var(--dnp-appeal-ink) 13%, transparent);
  --dnp-appeal-hair: color-mix(in oklch, var(--dnp-appeal-ink) 7%, transparent);
  --dnp-appeal-mute: color-mix(in oklch, var(--dnp-appeal-ink) 64%, var(--dnp-appeal-bg));
  --dnp-appeal-faint: color-mix(in oklch, var(--dnp-appeal-ink) 44%, var(--dnp-appeal-bg));
  --dnp-appeal-good: oklch(0.56 0.12 150);
  --dnp-appeal-c0: var(--dnp-appeal-accent);
  --dnp-appeal-c1: var(--dnp-appeal-gold);
  --dnp-appeal-c2: oklch(0.47 0.07 45);
  --dnp-appeal-c3: oklch(0.6 0.09 195);
  --dnp-appeal-sans: system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  --dnp-appeal-mono: ui-monospace, "SF Mono", Menlo, Consolas, monospace;
  --dnp-appeal-out: cubic-bezier(.22, 1, .36, 1);
  --dnp-appeal-spring: linear(0, .06 2.4%, .24 6%, .55 11%, .86 17%, 1.03 23%, 1.08 28%, 1.06 34%, 1.01 44%, .995 58%, 1);
  color-scheme: light;
  border-radius: 18px;
  box-shadow: inset 0 0 0 1px var(--dnp-appeal-line);
}
.dnp-appeal__app {
  height: 100%;
  display: grid;
  grid-template-columns: 208px minmax(0, 1fr);
  grid-template-rows: auto minmax(0, 1fr);
  grid-template-areas: "nav top" "nav main";
}

/* ---------------------------------------------------------------- nav */
.dnp-appeal__nav {
  grid-area: nav; min-height: 0;
  display: flex; flex-direction: column; gap: 18px;
  padding: 18px 14px 16px;
  background: var(--dnp-appeal-side);
  border-right: 1px solid var(--dnp-appeal-line);
}
.dnp-appeal__brand {
  display: flex; align-items: center; gap: 10px; padding: 0 4px;
  & .dnp-appeal__logo { display: grid; place-items: center; width: 34px; height: 34px; border-radius: 10px; background: var(--dnp-appeal-ink); color: var(--dnp-appeal-gold); flex: none; }
  & .dnp-appeal__brandtx { display: grid; line-height: 1.15; min-width: 0; }
  & b { font-weight: 720; letter-spacing: -.02em; font-size: 14px; }
  & small { color: var(--dnp-appeal-faint); font-size: 11px; }
}
.dnp-appeal__navlist { display: grid; gap: 2px; }
.dnp-appeal__navbtn {
  position: relative; width: 100%;
  display: flex; align-items: center; gap: 10px;
  height: 36px; padding: 0 10px; border-radius: 10px;
  color: var(--dnp-appeal-mute); font-weight: 560;
  transition: background-color .18s, color .18s;
  & span { flex: 1; text-align: left; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
  & .dnp-appeal__navn { font-style: normal; font-size: 11px; font-family: var(--dnp-appeal-mono); color: var(--dnp-appeal-faint); font-variant-numeric: tabular-nums; }
  &:hover { background: color-mix(in oklch, var(--dnp-appeal-ink) 5%, transparent); color: var(--dnp-appeal-ink); }
  &[aria-current="page"] { background: var(--dnp-appeal-card); color: var(--dnp-appeal-ink); box-shadow: 0 1px 0 var(--dnp-appeal-line), 0 0 0 1px var(--dnp-appeal-hair); }
  &[aria-current="page"]::before { content: ""; position: absolute; left: -14px; top: 9px; bottom: 9px; width: 3px; border-radius: 0 3px 3px 0; background: var(--dnp-appeal-accent); }
}
.dnp-appeal__navfoot {
  margin-top: auto; padding: 12px; border-radius: 12px;
  background: color-mix(in oklch, var(--dnp-appeal-gold) 16%, var(--dnp-appeal-card));
  box-shadow: inset 0 0 0 1px color-mix(in oklch, var(--dnp-appeal-gold) 40%, transparent);
  font-size: 12px; color: var(--dnp-appeal-mute);
  & b { color: var(--dnp-appeal-ink); }
  & small { font-size: 11px; font-variant-numeric: tabular-nums; }
}
.dnp-appeal__daybar {
  height: 6px; margin: 8px 0 6px; border-radius: 6px; overflow: hidden;
  background: color-mix(in oklch, var(--dnp-appeal-ink) 10%, transparent);
  & i { display: block; height: 100%; width: 100%; border-radius: inherit; background: var(--dnp-appeal-ink); transform-origin: left; scale: var(--p, 0) 1; transition: scale 1.1s var(--dnp-appeal-out) .2s; @starting-style { scale: 0 1; } }
}

/* ---------------------------------------------------------------- top bar */
.dnp-appeal__top {
  grid-area: top;
  display: flex; align-items: end; justify-content: space-between; gap: 12px 20px; flex-wrap: wrap;
  padding: 18px 22px 12px;
}
.dnp-appeal__eyebrow { font-size: 11px; font-weight: 650; letter-spacing: .08em; text-transform: uppercase; color: var(--dnp-appeal-accent); }
.dnp-appeal__title h2 { font-size: clamp(20px, 2.3cqi, 27px); font-weight: 760; letter-spacing: -.03em; line-height: 1.1; margin-top: 3px; }
.dnp-appeal__controls { display: flex; flex-wrap: wrap; align-items: center; gap: 8px 10px; }
.dnp-appeal__chips {
  display: flex; flex-wrap: wrap; gap: 4px;
  & button {
    display: inline-flex; align-items: center; gap: 6px; height: 28px; padding: 0 10px 0 8px;
    border-radius: 999px; font-size: 12px; font-weight: 600; color: var(--dnp-appeal-mute);
    box-shadow: inset 0 0 0 1px var(--dnp-appeal-line);
    transition: background-color .18s, color .18s, box-shadow .18s;
  }
  & button i { width: 9px; height: 9px; border-radius: 3px; background: var(--c); scale: .7; opacity: .45; transition: scale .3s var(--dnp-appeal-spring), opacity .2s; }
  & button[aria-pressed="true"] { color: var(--dnp-appeal-ink); background: color-mix(in oklch, var(--c) 14%, var(--dnp-appeal-card)); box-shadow: inset 0 0 0 1px color-mix(in oklch, var(--c) 55%, transparent); }
  & button[aria-pressed="true"] i { scale: 1; opacity: 1; }
  & button:hover { color: var(--dnp-appeal-ink); }
  & button[aria-disabled="true"] { cursor: not-allowed; }
}
.dnp-appeal__seg {
  display: inline-flex; padding: 3px; gap: 2px; border-radius: 10px;
  background: color-mix(in oklch, var(--dnp-appeal-ink) 6%, transparent);
  & button { height: 26px; padding: 0 10px; border-radius: 7px; font-size: 12px; font-weight: 620; color: var(--dnp-appeal-mute); font-variant-numeric: tabular-nums; transition: background-color .18s, color .18s, box-shadow .18s; }
  & button:hover { color: var(--dnp-appeal-ink); }
  & button[aria-checked="true"] { background: var(--dnp-appeal-card); color: var(--dnp-appeal-ink); box-shadow: 0 1px 2px color-mix(in oklch, var(--dnp-appeal-ink) 18%, transparent); }
}
.dnp-appeal__seg--sm button { height: 24px; padding: 0 9px; font-size: 11.5px; }

/* ---------------------------------------------------------------- main + views */
.dnp-appeal__main { grid-area: main; min-height: 0; padding: 0 22px 18px; }
.dnp-appeal__view {
  height: 100%;
  opacity: 1; translate: 0 0;
  transition: opacity .35s, translate .5s var(--dnp-appeal-out);
  @starting-style { opacity: 0; translate: 0 10px; }
}
.dnp-appeal__panel {
  min-height: 0; min-width: 0;
  display: flex; flex-direction: column;
  border-radius: 14px;
  background: var(--dnp-appeal-card);
  box-shadow: 0 0 0 1px var(--dnp-appeal-line), 0 1px 0 var(--dnp-appeal-hair);
}
.dnp-appeal__ph {
  display: flex; align-items: center; gap: 8px 10px; flex-wrap: wrap;
  padding: 12px 14px 8px;
  & h3 { font-size: 13px; font-weight: 700; letter-spacing: -.01em; margin-right: auto; }
}
.dnp-appeal__btn {
  display: inline-flex; align-items: center; gap: 6px; height: 28px; padding: 0 11px 0 8px;
  border-radius: 8px; font-size: 12px; font-weight: 650;
  background: var(--dnp-appeal-ink); color: var(--dnp-appeal-bg);
  transition: translate .2s var(--dnp-appeal-out), background-color .2s;
  & .dnp-appeal__i { width: 15px; height: 15px; }
  &:hover { background: color-mix(in oklch, var(--dnp-appeal-ink), var(--dnp-appeal-accent) 35%); }
  &:active { translate: 0 1px; }
  &:disabled { opacity: .5; }
}
.dnp-appeal__ov {
  display: grid; gap: 12px;
  grid-template-columns: 250px minmax(0, 1.25fr) minmax(0, 1fr);
  grid-template-rows: auto minmax(0, 1.2fr) minmax(0, 1fr);
  grid-template-areas: "thermo kpis kpis" "thermo chart chart" "thermo feed pyr";
}

/* ---------------------------------------------------------------- thermometer */
.dnp-appeal__thermo { grid-area: thermo; overflow: hidden; }
.dnp-appeal__goal { font: 600 11.5px var(--dnp-appeal-mono); color: var(--dnp-appeal-faint); }
.dnp-appeal__gauge {
  --tube: 26px;
  position: relative; flex: 1; min-height: 260px;
  margin: 22px 12px 46px 14px;
  display: grid; grid-template-columns: minmax(0, 1fr) var(--tube) 70px;
  & > * { grid-row: 1; }
}
.dnp-appeal__ticks {
  grid-column: 3; position: relative;
  & li { position: absolute; left: 8px; bottom: calc(var(--m) * 100%); translate: 0 50%; font: 500 10px var(--dnp-appeal-mono); color: var(--dnp-appeal-faint); font-variant-numeric: tabular-nums; }
  & li::before { content: ""; position: absolute; left: -8px; top: 50%; width: 5px; height: 1px; background: var(--dnp-appeal-line); }
}
.dnp-appeal__tube {
  grid-column: 2; position: relative; overflow: hidden;
  border-radius: calc(var(--tube) / 2) calc(var(--tube) / 2) 0 0;
  background:
    repeating-linear-gradient(to top, transparent 0 calc(100% / 12 - 1px), color-mix(in oklch, var(--dnp-appeal-ink) 10%, transparent) calc(100% / 12 - 1px) calc(100% / 12)),
    color-mix(in oklch, var(--dnp-appeal-ink) 5%, var(--dnp-appeal-card));
  box-shadow: inset 0 0 0 1.5px var(--dnp-appeal-line), inset 3px 0 6px -3px color-mix(in oklch, var(--dnp-appeal-ink) 15%, transparent);
}
.dnp-appeal__merc {
  position: absolute; inset: 0 5px 0;
  border-radius: 9px 9px 0 0;
  transform-origin: bottom;
  transform: scaleY(var(--dnp-appeal-fill));
  background: linear-gradient(to right, color-mix(in oklch, var(--dnp-appeal-accent), white 18%), var(--dnp-appeal-accent) 45%, color-mix(in oklch, var(--dnp-appeal-accent), black 18%));
}
.dnp-appeal__gauge { --dnp-appeal-fill: 0; transition: --dnp-appeal-fill 1.5s var(--dnp-appeal-spring); }
.dnp-appeal__bulb {
  position: absolute; right: calc(70px + var(--tube) / 2); bottom: -38px; translate: 50% 0;
  width: 46px; height: 46px; border-radius: 50%;
  background: radial-gradient(circle at 35% 32%, color-mix(in oklch, var(--dnp-appeal-accent), white 40%) 0 10%, var(--dnp-appeal-accent) 46%, color-mix(in oklch, var(--dnp-appeal-accent), black 22%));
  box-shadow: 0 0 0 4px var(--dnp-appeal-card), 0 0 0 5.5px var(--dnp-appeal-line), 0 10px 24px -8px color-mix(in oklch, var(--dnp-appeal-accent) 70%, transparent);
}
.dnp-appeal__rider {
  grid-column: 3; position: relative; pointer-events: none; z-index: 2;
  transform: translateY(calc((1 - var(--dnp-appeal-fill)) * 100%));
}
.dnp-appeal__pill {
  position: absolute; left: 7px; top: 0; translate: 0 -50%; z-index: 2;
  display: grid; justify-items: start;
  padding: 4px 7px 5px; border-radius: 8px; line-height: 1.15;
  background: var(--dnp-appeal-ink); color: var(--dnp-appeal-bg);
  font-variant-numeric: tabular-nums; white-space: nowrap;
  box-shadow: 0 6px 16px -8px color-mix(in oklch, var(--dnp-appeal-ink) 80%, transparent);
  & b { font-size: 12.5px; font-weight: 720; letter-spacing: -.015em; }
  & small { font-size: 10.5px; opacity: .72; }
  &::before { content: ""; position: absolute; left: -5px; top: 50%; translate: 0 -50%; border: 5px solid transparent; border-left: 0; border-right-color: var(--dnp-appeal-ink); }
}
.dnp-appeal__miles {
  grid-column: 1; position: relative;
  & li {
    position: absolute; left: 0; right: 12px; top: calc((1 - var(--m)) * 100%); translate: 0 -8px;
    display: grid; grid-template-columns: minmax(0, 1fr) 16px; column-gap: 6px; align-items: start; text-align: right;
    font-size: 11.5px; line-height: 1.3; color: var(--dnp-appeal-faint);
    transition: color .4s, opacity .4s;
  }
  & li::after { content: ""; position: absolute; right: -12px; top: 8px; width: 9px; height: 1px; background: currentColor; opacity: .6; }
  & li > b, & li > span:not(.dnp-appeal__mdot) { grid-column: 1; grid-row: auto; }
  & .dnp-appeal__mdot { grid-column: 2; grid-row: 1 / span 2; }
  & .dnp-appeal__mdot { width: 16px; height: 16px; border-radius: 50%; display: grid; place-items: center; box-shadow: inset 0 0 0 1.5px currentColor; transition: background-color .4s, box-shadow .4s; }
  & .dnp-appeal__mdot svg { width: 10px; height: 10px; fill: none; stroke: var(--dnp-appeal-card); stroke-width: 3; stroke-linecap: round; stroke-linejoin: round; opacity: 0; scale: .4; transition: opacity .3s, scale .45s var(--dnp-appeal-spring); }
  & b { font-weight: 700; font-variant-numeric: tabular-nums; }
  & li[data-state="passed"] { color: var(--dnp-appeal-ink); }
  & li[data-state="passed"] .dnp-appeal__mdot { background: var(--dnp-appeal-good); box-shadow: none; }
  & li[data-state="passed"] .dnp-appeal__mdot svg { opacity: 1; scale: 1; }
  & li[data-state="next"] { color: var(--dnp-appeal-ink); }
  & li[data-state="next"] .dnp-appeal__mdot { box-shadow: inset 0 0 0 1.5px var(--dnp-appeal-accent); animation: dnp-appeal-ping 2.4s var(--dnp-appeal-out) 3; }
  & li.is-pop .dnp-appeal__mdot { animation: dnp-appeal-pop .7s var(--dnp-appeal-spring); }
}
@keyframes dnp-appeal-ping { 0% { box-shadow: inset 0 0 0 1.5px var(--dnp-appeal-accent), 0 0 0 0 color-mix(in oklch, var(--dnp-appeal-accent) 45%, transparent); } 70%, 100% { box-shadow: inset 0 0 0 1.5px var(--dnp-appeal-accent), 0 0 0 9px transparent; } }
@keyframes dnp-appeal-pop { 0% { scale: .4; } 60% { scale: 1.35; } 100% { scale: 1; } }
.dnp-appeal__togo {
  margin: 0 14px 14px; padding-top: 10px; border-top: 1px dashed var(--dnp-appeal-line);
  display: grid; font-size: 11.5px; color: var(--dnp-appeal-mute);
  & > b { font-size: 20px; font-weight: 760; letter-spacing: -.02em; color: var(--dnp-appeal-ink); font-variant-numeric: tabular-nums; }
  & span b { color: var(--dnp-appeal-ink); font-variant-numeric: tabular-nums; }
}

/* ---------------------------------------------------------------- kpis */
.dnp-appeal__kpis { grid-area: kpis; display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); gap: 12px; }
.dnp-appeal__kpi {
  display: grid; align-content: start; gap: 2px;
  padding: 11px 14px 12px; border-radius: 14px;
  background: var(--dnp-appeal-card); box-shadow: 0 0 0 1px var(--dnp-appeal-line);
  min-width: 0;
}
.dnp-appeal__kl { font-size: 11px; font-weight: 600; letter-spacing: .04em; text-transform: uppercase; color: var(--dnp-appeal-faint); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.dnp-appeal__kr { font-style: normal; text-transform: none; letter-spacing: 0; color: var(--dnp-appeal-faint); font-weight: 500; }
.dnp-appeal__kv { font-size: clamp(18px, 2.15cqi, 25px); font-weight: 760; letter-spacing: -.035em; line-height: 1.15; font-variant-numeric: tabular-nums; }
.dnp-appeal__ks { font-size: 11.5px; color: var(--dnp-appeal-mute); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; font-variant-numeric: tabular-nums; }
.dnp-appeal__ks em { font-style: normal; font-weight: 650; }
.dnp-appeal__ks .is-up { color: var(--dnp-appeal-good); }
.dnp-appeal__ks .is-down { color: var(--dnp-appeal-accent); }
.dnp-appeal__kpi--pace { position: relative; background: color-mix(in oklch, var(--dnp-appeal-gold) 13%, var(--dnp-appeal-card)); }


/* ---------------------------------------------------------------- chart */
.dnp-appeal__chartp { grid-area: chart; }
.dnp-appeal__legend {
  display: flex; flex-wrap: wrap; gap: 4px 14px; padding: 0 14px 2px; font-size: 11.5px; color: var(--dnp-appeal-mute);
  & li { display: inline-flex; align-items: center; gap: 6px; }
  & i { width: 10px; height: 10px; border-radius: 3px; background: var(--c); }
  & i.is-line { height: 0; border-top: 2px dashed var(--c); border-radius: 0; background: none; }
}
.dnp-appeal__plot { position: relative; flex: 1; min-height: 120px; margin: 0 6px 6px; }
.dnp-appeal__svg {
  position: absolute; inset: 0; width: 100%; height: 100%; cursor: crosshair; border-radius: 8px;
  & text { font: 10.5px var(--dnp-appeal-sans); fill: var(--dnp-appeal-faint); font-variant-numeric: tabular-nums; }
  & .dnp-appeal__grid line { stroke: var(--dnp-appeal-hair); }
  & .dnp-appeal__grid line.is-zero { stroke: var(--dnp-appeal-line); }
  & .dnp-appeal__bar { transform-box: fill-box; transform-origin: bottom; }
  & .dnp-appeal__bars.is-intro .dnp-appeal__bar { animation: dnp-appeal-grow .7s var(--dnp-appeal-out) both; animation-delay: calc(var(--i) * 14ms); }
  & .dnp-appeal__col { fill: color-mix(in oklch, var(--dnp-appeal-ink) 6%, transparent); opacity: 0; transition: opacity .12s; }
  & .dnp-appeal__col.is-on { opacity: 1; }
  & .dnp-appeal__area { fill: color-mix(in oklch, var(--dnp-appeal-accent) 16%, transparent); }
