    dot.setAttribute('cx', X); dot.setAttribute('cy', Y); dot.classList.add('is-on');
    const pv = s.pace(s.a + i), diff = s.cum[i] - pv;
    tip('<span class="dnp-appeal__tt">' + dlabel(s.a + i) + '</span><span class="dnp-appeal__trow"><span>Running total</span><b>' + gbp(s.cum[i]) + '</b></span>' +
      (s.all4 ? '<span class="dnp-appeal__trow"><span>Pace line</span><b>' + gbp(pv) + '</b></span><span class="dnp-appeal__trow"><span>' + (diff >= 0 ? 'Ahead by' : 'Behind by') + '</span><b>' + gbp(Math.abs(diff)) + '</b></span>' : '<span class="dnp-appeal__trow"><span>Selected channels only</span></span>'),
      cx ?? box.left + X, cy ?? box.top + Y);
  }
};
const hideHover = () => { hoverIdx = -1; untip(); $$('.dnp-appeal__col.is-on, .dnp-appeal__xh.is-on, .dnp-appeal__dot.is-on', svg).forEach(e => e.classList.remove('is-on')); };
svg.addEventListener('pointermove', e => {
  const s = chartState; if (!s) return;
  const r = svg.getBoundingClientRect(), px = e.clientX - r.left;
  const i = s.kind === 'daily' ? Math.floor((px - s.m.l) / s.band) : Math.round((px - s.m.l) / s.step);
  if (px < s.m.l - 4) { hideHover(); return; }
  showHover(i, e.clientX, e.clientY);
});
svg.addEventListener('pointerleave', hideHover);
svg.addEventListener('blur', hideHover);
svg.addEventListener('keydown', e => {
  const s = chartState; if (!s) return;
  const last = s.kind === 'daily' ? s.n - 1 : s.cum.length - 1;
  let i = hoverIdx < 0 ? last : hoverIdx;
  if (e.key === 'ArrowLeft') i--; else if (e.key === 'ArrowRight') i++; else if (e.key === 'Home') i = 0; else if (e.key === 'End') i = last; else if (e.key === 'Escape') { hideHover(); return; } else return;
  e.preventDefault(); showHover(clamp(i, 0, last));
});
onResize(plot, () => drawChart(false));

/* ================================================================ feed */
const feed = $('.dnp-appeal__feed');
const feedItem = g => {
  const c = CH[g.ci];
  return '<li data-g="' + g.id + '"><span class="dnp-appeal__av" style="--c:var(--dnp-appeal-c' + g.ci + ')">' + (g.donor.org ? '<svg class="dnp-appeal__i" viewBox="0 0 24 24" style="width:15px;height:15px">' + c.ic + '</svg>' : esc(initials(g.donor.name))) + '</span>' +
    '<span class="dnp-appeal__fn">' + esc(g.donor.name) + '</span><span class="dnp-appeal__fm">' + esc(c.n) + (g.donor.town ? ' · ' + esc(g.donor.town) : '') + ' · ' + when(g) + '</span>' +
    '<span class="dnp-appeal__fa">' + gbp(g.amt) + (g.ga ? '<small>+' + gbp2(g.amt * .25) + ' Gift Aid</small>' : '') + '</span></li>';
};
const renderFeed = () => {
  const list = gifts.filter(g => S.on.has(g.ci)).slice(-12).reverse();
  feed.innerHTML = list.length ? list.map(feedItem).join('') : '<li class="dnp-appeal__empty">No gifts in the selected channels yet.</li>';
};
$('[data-act=sim]').addEventListener('click', () => {
  clock += 2 + Math.floor(R() * 5);
  const pool = [...S.on], ci = pool[Math.floor(R() * pool.length)];
  const g = makeGift(TODAY, ci, clock); g.sim = true;
  gifts.push(g);
  const olds = $$('li', feed);
  flip(olds, () => {
    feed.insertAdjacentHTML('afterbegin', feedItem(g));
    const extra = $$('li', feed); if (extra.length > 12) extra[extra.length - 1].remove();
  }, { duration: 460 });
  const li = feed.firstElementChild; li.classList.add('is-new');
  if (!RM) li.animate([{ opacity: 0, transform: 'translateY(-10px) scale(.98)' }, { opacity: 1, transform: 'none' }], { duration: 420, easing: EASE });
  feed.scrollTop = 0;
  const crossed = renderThermo(false); renderKpis(); drawChart(false); renderPyramid(false);
  toast(crossed > -1 ? 'Milestone reached: ' + MILES[crossed].t : gbp(g.amt) + ' from ' + g.donor.name + ' via ' + CH[ci].n.toLowerCase() + ' · ' + (totalRaised() / GOAL * 100).toFixed(1) + '% of goal');
});

/* ================================================================ pyramid */
const BANDS = [[1000, Infinity, '£1,000+'], [500, 999, '£500–999'], [250, 499, '£250–499'], [100, 249, '£100–249'], [50, 99, '£50–99'], [25, 49, '£25–49'], [1, 24, 'Under £25']];
const pyr = $('.dnp-appeal__pyr');
const renderPyramid = intro => {
  const v = visible(), n = v.length || 1, tot = sum(v.map(g => g.amt)) || 1;
  const rows = BANDS.map(([lo, hi, lab]) => { const gs = v.filter(g => g.amt >= lo && g.amt <= hi); return { lab, c: gs.length, s: sum(gs.map(g => g.amt)) }; });
  const mx = Math.max(...rows.map(r => Math.max(r.c / n, r.s / tot)), .01) / .8;
  pyr.classList.toggle('is-intro', !!intro);
  pyr.innerHTML = rows.map((r, i) => '<div class="dnp-appeal__band" style="--i:' + i + '" data-i="' + i + '"><div class="dnp-appeal__l" style="--w:' + (r.c / n / mx).toFixed(4) + '"><i></i><em>' + (r.c / n * 100).toFixed(r.c / n < .1 ? 1 : 0) + '%</em></div><span>' + r.lab + '</span><div class="dnp-appeal__r" style="--w:' + (r.s / tot / mx).toFixed(4) + '"><i></i><em>' + (r.s / tot * 100).toFixed(r.s / tot < .1 ? 1 : 0) + '%</em></div></div>').join('');
  pyr._rows = rows; pyr._n = n; pyr._tot = tot;
};
pyr.addEventListener('pointermove', e => {
  const b = e.target.closest('.dnp-appeal__band'); if (!b) { untip(); return; }
  const r = pyr._rows[+b.dataset.i];
  tip('<span class="dnp-appeal__tt">' + r.lab + ' gifts</span><span class="dnp-appeal__trow"><span>Gifts</span><b>' + NF.format(r.c) + ' (' + (r.c / pyr._n * 100).toFixed(1) + '%)</b></span><span class="dnp-appeal__trow"><span>Value</span><b>' + gbp(r.s) + ' (' + (r.s / pyr._tot * 100).toFixed(1) + '%)</b></span>', e.clientX, e.clientY);
});
pyr.addEventListener('pointerleave', untip);

/* ================================================================ ledger */
const tbody = $('.dnp-appeal__table tbody'), detail = $('.dnp-appeal__detail');
const sorters = { when: g => g.d * 1e4 + g.t + (g.sim ? 5e3 : 0), amt: g => g.amt, name: g => g.donor.name.toLowerCase() };
const ledgerRows = () => {
  const q = S.q.trim().toLowerCase();
  let v = visible();
  if (q) v = v.filter(g => (g.donor.name + ' ' + g.donor.town).toLowerCase().includes(q));
  const f = sorters[S.sort.k];
  v = v.slice().sort((x, y) => { const a = f(x), b = f(y); return (a < b ? -1 : a > b ? 1 : x.id - y.id) * S.sort.dir; });
  return v;
};
const renderLedger = () => {
  const v = ledgerRows(), shown = v.slice(0, 150);
  $('.dnp-appeal__count').textContent = (v.length > shown.length ? 'First ' + shown.length + ' of ' : '') + NF.format(v.length) + ' gifts';
  if (S.sel != null && !v.some(g => g.id === S.sel)) S.sel = null;
  if (S.sel == null && shown.length) S.sel = shown[0].id;
  tbody.innerHTML = shown.map(g => '<tr data-g="' + g.id + '" tabindex="-1" aria-selected="' + (g.id === S.sel) + '"><td class="dnp-appeal__who">' + esc(g.donor.name) + (g.donor.town ? '<small>' + esc(g.donor.town) + '</small>' : '') + '</td><td class="dnp-appeal__hide-s"><span class="dnp-appeal__chn" style="--c:var(--dnp-appeal-c' + g.ci + ')"><i></i>' + esc(CH[g.ci].n) + '</span></td><td class="dnp-appeal__num">' + gbp(g.amt) + '</td><td class="dnp-appeal__hide-s">' + (g.ga ? '<span class="dnp-appeal__ga">+' + gbp2(g.amt * .25) + '</span>' : '<span class="dnp-appeal__when">—</span>') + '</td><td class="dnp-appeal__num dnp-appeal__when">' + when(g) + '</td></tr>').join('') || '<tr><td colspan="5" style="text-align:center;padding:24px;color:var(--dnp-appeal-faint)">No gifts match “' + esc(S.q) + '”.</td></tr>';
  const cur = tbody.querySelector('[aria-selected=true]'); if (cur) cur.tabIndex = 0; else { const f = tbody.querySelector('tr[data-g]'); if (f) f.tabIndex = 0; }
  $$('.dnp-appeal__table th[aria-sort]').forEach(th => th.setAttribute('aria-sort', th.querySelector('button').dataset.sort === S.sort.k ? (S.sort.dir > 0 ? 'ascending' : 'descending') : 'none'));
  renderDetail();
};
const renderDetail = () => {
  const g = gifts.find(x => x.id === S.sel);
  if (!g) { detail.innerHTML = '<p class="dnp-appeal__dl">No gift selected</p><p style="color:var(--dnp-appeal-faint)">Pick a row to see the donor’s giving in this appeal.</p>'; return; }
  const theirs = gifts.filter(x => x.donor.id === g.donor.id), tt = sum(theirs.map(x => x.amt));
  const done = S.thanked.has(g.donor.id);
  detail.innerHTML = '<p class="dnp-appeal__dl">' + when(g) + ' · ' + esc(CH[g.ci].n) + '</p><div class="dnp-appeal__damt">' + gbp(g.amt) + '</div>' + (g.ga ? '<div class="dnp-appeal__dga">+' + gbp2(g.amt * .25) + ' Gift Aid claimable</div>' : '') +
    '<div class="dnp-appeal__dwho"><span class="dnp-appeal__av" style="--c:var(--dnp-appeal-c' + g.ci + ')">' + esc(initials(g.donor.name) || '·') + '</span><span><b>' + esc(g.donor.name) + '</b><small>' + esc(g.donor.town || 'Community fundraising') + '</small></span></div>' +
    (g.msg ? '<blockquote>“' + esc(g.msg) + '”</blockquote>' : '') +
    '<dl><dt>Gifts this appeal</dt><dd>' + theirs.length + '</dd><dt>Total this appeal</dt><dd>' + gbp(tt) + '</dd><dt>Share of appeal</dt><dd>' + (tt / totalRaised() * 100).toFixed(3) + '%</dd></dl>' +
    '<button type="button" class="dnp-appeal__btn" data-act="thank"' + (done ? ' disabled title="A thank-you is already queued for this donor"' : '') + '>' + (done ? 'Thank-you queued' : 'Queue a thank-you') + '</button>';
};
detail.addEventListener('click', e => {
  const b = e.target.closest('[data-act=thank]'); if (!b || b.disabled) return;
  const g = gifts.find(x => x.id === S.sel); if (!g) return;
  S.thanked.add(g.donor.id); renderDetail();
  toast('Thank-you queued for ' + g.donor.name + ' · goes out with Friday’s post');
});
const selectRow = (tr, focus) => {
  if (!tr || !tr.dataset.g) return;
  S.sel = +tr.dataset.g;
  $$('tr[aria-selected]', tbody).forEach(r => { const on = r === tr; r.setAttribute('aria-selected', String(on)); r.tabIndex = on ? 0 : -1; });
  if (focus) tr.focus();
  renderDetail();
};
tbody.addEventListener('click', e => { const tr = e.target.closest('tr[data-g]'); if (tr && tr.getAttribute('aria-selected') !== 'true') selectRow(tr); });
tbody.addEventListener('keydown', e => {
  const tr = e.target.closest('tr[data-g]'); if (!tr) return;
  const sib = e.key === 'ArrowDown' ? tr.nextElementSibling : e.key === 'ArrowUp' ? tr.previousElementSibling : null;
  if (sib) { e.preventDefault(); selectRow(sib, true); }
  if (e.key === 'Enter' || e.key === ' ') { e.preventDefault(); selectRow(tr); }
});
$('.dnp-appeal__table thead').addEventListener('click', e => {
  const b = e.target.closest('[data-sort]'); if (!b) return;
  const k = b.dataset.sort;
  S.sort = S.sort.k === k ? { k, dir: -S.sort.dir } : { k, dir: k === 'name' ? 1 : -1 };
  renderLedger();
});
$('.dnp-appeal__search input').addEventListener('input', e => { S.q = e.target.value; renderLedger(); });

/* ================================================================ channel cards */
const cards = $('.dnp-appeal__cards');
radios($('.dnp-appeal__cvh .dnp-appeal__seg'), v => { S.cardSort = v; renderCards(false); });
const renderCards = intro => {
  const [a, b] = inRange();
  const all = gifts.filter(g => g.d >= a && g.d <= b), tot = sum(all.map(g => g.amt)) || 1;
  const stats = CH.map((c, i) => { const gs = all.filter(g => g.ci === i), s = sum(gs.map(g => g.amt)); const daily = []; for (let d = a; d <= b; d++) daily.push(0); gs.forEach(g => { daily[g.d - a] += g.amt; }); return { i, c, s, n: gs.length, avg: gs.length ? s / gs.length : 0, daily }; });
  const key = S.cardSort === 'raised' ? 's' : S.cardSort === 'gifts' ? 'n' : 'avg';
  const order = stats.slice().sort((x, y) => y[key] - x[key]);
  const existing = $$('li[data-ci]', cards);
  const build = () => {
    if (!existing.length) cards.innerHTML = order.map(st => '<li data-ci="' + st.i + '" style="--c:var(--dnp-appeal-c' + st.i + ')"></li>').join('');
    const lis = $$('li[data-ci]', cards);
    order.forEach((st, rank) => {
      const li = lis.find(x => +x.dataset.ci === st.i);
      li.classList.toggle('is-off', !S.on.has(st.i));
      li.innerHTML = '<span class="dnp-appeal__cico"><svg class="dnp-appeal__i" viewBox="0 0 24 24">' + st.c.ic + '</svg></span><span class="dnp-appeal__cname">' + esc(st.c.n) + '</span><span class="dnp-appeal__crank">#' + (rank + 1) + '</span>' +
        '<span class="dnp-appeal__cbig">' + gbp(st.s) + '<small>' + (st.s / tot * 100).toFixed(1) + '%</small></span><span class="dnp-appeal__cstat"><b>' + NF.format(st.n) + '</b> gifts<br>avg <b>' + gbp2(st.avg) + '</b></span>' +
        '<span class="dnp-appeal__share" style="--w:' + (st.s / tot).toFixed(4) + '"><i></i></span><div class="dnp-appeal__spark"><svg role="img" aria-label="' + esc(st.c.n) + ' raised per day"></svg></div>';
      cards.appendChild(li);
    });
  };
  if (existing.length && !intro) flip(existing, build, { duration: 560, easing: 'cubic-bezier(.3,1.3,.5,1)' }); else build();
  requestAnimationFrame(() => { if (!root.isConnected) return; $$('li[data-ci]', cards).forEach(li => drawSpark(li, stats[+li.dataset.ci], a)); });
  cards._stats = stats; cards._a = a;
};
const drawSpark = (li, st, a) => {
  const box = $('.dnp-appeal__spark', li), s = $('svg', box), [W, H] = measure(box);
  if (!W || !H) return;
  s.setAttribute('viewBox', '0 0 ' + W + ' ' + H);
  const B = H - 16, mx = Math.max(...st.daily, 1), n = st.daily.length, x = i => n === 1 ? W / 2 : 2 + i * (W - 4) / (n - 1), y = v => B - v / mx * (B - 16);
  const p = st.daily.map((v, i) => x(i).toFixed(1) + ',' + y(v).toFixed(1));
  const pk = st.daily.indexOf(Math.max(...st.daily)), px = x(pk), anchor = px > W - 90 ? 'end' : px < 90 ? 'start' : 'middle';
  s.innerHTML = '<line class="base" x1="0" x2="' + W + '" y1="' + B + '" y2="' + B + '"/><path class="a" d="M' + x(0) + ',' + B + 'L' + p.join('L') + 'L' + x(n - 1) + ',' + B + 'Z"/><path class="l" d="M' + p.join('L') + '"/>' +
    (st.daily[pk] > 0 ? '<circle class="pkd" r="3" cx="' + px + '" cy="' + y(st.daily[pk]) + '"/><text class="pk" x="' + px + '" y="' + (y(st.daily[pk]) - 7) + '" text-anchor="' + anchor + '">Peak ' + gbp(st.daily[pk]) + ' · ' + dlabel(a + pk) + '</text>' : '') +
    '<text x="0" y="' + (H - 2) + '">' + dlabel(a) + '</text><text x="' + W + '" y="' + (H - 2) + '" text-anchor="end">' + dlabel(a + n - 1) + '</text><line class="xh" y1="0" y2="' + B + '"/><circle class="dt" r="3.5"/>';
  s._p = { x, y, st, a, n };
};
cards.addEventListener('pointermove', e => {
  const s = e.target.closest('.dnp-appeal__spark svg'); if (!s || !s._p) { untip(); return; }
  const r = s.getBoundingClientRect(), P = s._p, i = clamp(Math.round((e.clientX - r.left - 2) / ((r.width - 4) / Math.max(1, P.n - 1))), 0, P.n - 1);
  const ln = $('line.xh', s), c = $('circle.dt', s);
  ln.setAttribute('x1', P.x(i)); ln.setAttribute('x2', P.x(i)); ln.classList.add('is-on');
  c.setAttribute('cx', P.x(i)); c.setAttribute('cy', P.y(P.st.daily[i])); c.classList.add('is-on');
  tip('<span class="dnp-appeal__tt">' + esc(P.st.c.n) + ' · ' + dlabel(P.a + i) + '</span><b>' + gbp(P.st.daily[i]) + '</b>', e.clientX, e.clientY);
});
cards.addEventListener('pointerout', e => { const s = e.target.closest('.dnp-appeal__spark svg'); if (s && !s.contains(e.relatedTarget)) { untip(); $$('.is-on', s).forEach(x => x.classList.remove('is-on')); } });

/* ================================================================ escape closes the tooltip from anywhere */
root.addEventListener('keydown', e => { if (e.key === 'Escape') untip(); });

/* ================================================================ refresh + mount */
const refresh = () => {
  renderKpis(); drawChart(false); renderFeed(); renderPyramid(false);
  if (!$('[data-view=gifts]').hidden) renderLedger();
  if (!$('[data-view=channels]').hidden) renderCards(false);
};
renderThermo(true);
renderKpis();
renderFeed();
renderPyramid(true);
requestAnimationFrame(() => { if (!root.isConnected) return; drawChart(true); });

css:
.dnp-retention {
  width: 100%;
  height: var(--dnp-retention-h, 680px);
  container-type: inline-size;
  container-name: dnp-retention;
  position: relative;
  isolation: isolate;
  overflow: hidden;
  background: var(--dnp-retention-bg);
  color: var(--dnp-retention-ink);
  font: 13px/1.45 var(--dnp-retention-sans);
  accent-color: var(--dnp-retention-accent);
  -webkit-font-smoothing: antialiased;
  & *, & *::before, & *::after { box-sizing: border-box; }
  & :where(h1, h2, h3, h4, p, ol, ul, dl, dd, figure) { margin: 0; padding: 0; }
  & :where(ol, ul) { list-style: none; }
  & :where(h1, h2, h3, h4) { text-wrap: balance; font-weight: 650; }
  & :where(p) { text-wrap: pretty; }
  & :where(button, input, select) { font: inherit; color: inherit; letter-spacing: inherit; }
  & :where(button) { background: none; border: 0; padding: 0; cursor: pointer; -webkit-tap-highlight-color: transparent; }
  & :where(button:disabled, [aria-disabled="true"]) { cursor: not-allowed; }
  & :where(svg) { display: block; overflow: visible; }
  & :where(table) { border-collapse: collapse; width: 100%; }
  & :focus-visible { outline: 2px solid var(--dnp-retention-focus, var(--dnp-retention-accent)); outline-offset: 2px; }
  & [hidden] { display: none !important; }
  & .dnp-retention__i { width: 18px; height: 18px; flex: none; fill: none; stroke: currentColor; stroke-width: 1.75; stroke-linecap: round; stroke-linejoin: round; }
  & .dnp-retention__sr { position: absolute; width: 1px; height: 1px; overflow: hidden; clip-path: inset(50%); white-space: nowrap; }
}
.dnp-retention__scroll {
  overflow: auto;
  overscroll-behavior: contain;
  scrollbar-width: thin;
  scrollbar-color: color-mix(in oklch, var(--dnp-retention-ink) 22%, transparent) transparent;
  &::-webkit-scrollbar { width: 8px; height: 8px; }
  &::-webkit-scrollbar-thumb { background: color-mix(in oklch, var(--dnp-retention-ink) 20%, transparent); border-radius: 8px; border: 2px solid transparent; background-clip: padding-box; }
}
.dnp-retention__tip {
  position: absolute; left: 0; top: 0; z-index: 40;
  pointer-events: none;
  min-width: 128px; max-width: 260px;
  padding: 8px 10px;
  border-radius: 10px;
  background: var(--dnp-retention-tipbg, color-mix(in oklch, var(--dnp-retention-ink) 94%, var(--dnp-retention-bg)));
  color: var(--dnp-retention-tipink, var(--dnp-retention-bg));
  font-size: 12px; line-height: 1.4;
  font-variant-numeric: tabular-nums;
  box-shadow: 0 10px 28px -10px oklch(0 0 0 / .45);
  opacity: 0; scale: .96;
  transition: opacity .14s, scale .2s cubic-bezier(.22, 1, .36, 1);
  &.is-on { opacity: 1; scale: 1; }
  & b { font-weight: 650; }
  & .dnp-retention__tt { display: block; font-size: 11px; letter-spacing: .04em; text-transform: uppercase; opacity: .7; margin-bottom: 3px; }
  & .dnp-retention__trow { display: flex; justify-content: space-between; gap: 14px; align-items: baseline; }
  & .dnp-retention__trow i { display: inline-block; width: 8px; height: 8px; border-radius: 2px; margin-right: 6px; background: var(--c); }
}
.dnp-retention__toast {
  position: absolute; left: 50%; bottom: 18px; z-index: 50;
  max-width: min(440px, calc(100% - 32px));
  padding: 10px 16px;
  border-radius: 12px;
  background: var(--dnp-retention-tipbg, color-mix(in oklch, var(--dnp-retention-ink) 94%, var(--dnp-retention-bg)));
  color: var(--dnp-retention-tipink, var(--dnp-retention-bg));
  font-size: 12.5px; font-weight: 550;
  box-shadow: 0 16px 40px -14px oklch(0 0 0 / .5);
  pointer-events: none;
  translate: -50% 16px; opacity: 0;
  transition: translate .45s cubic-bezier(.22, 1, .36, 1), opacity .25s;
  &.is-on { translate: -50% 0; opacity: 1; }
}

.dnp-retention {
  /* re-theme with these four */
  --dnp-retention-bg: oklch(0.205 0.022 208);
  --dnp-retention-ink: oklch(0.95 0.012 190);
  --dnp-retention-accent: oklch(0.83 0.145 76);
  --dnp-retention-cool: oklch(0.72 0.095 186);
  /* derived */
  --dnp-retention-card: color-mix(in oklch, var(--dnp-retention-bg), var(--dnp-retention-ink) 5%);
  --dnp-retention-raise: color-mix(in oklch, var(--dnp-retention-bg), var(--dnp-retention-ink) 9%);
  --dnp-retention-side: color-mix(in oklch, var(--dnp-retention-bg), black 22%);
  --dnp-retention-line: color-mix(in oklch, var(--dnp-retention-ink) 13%, transparent);
  --dnp-retention-hair: color-mix(in oklch, var(--dnp-retention-ink) 7%, transparent);
  --dnp-retention-mute: color-mix(in oklch, var(--dnp-retention-ink) 68%, var(--dnp-retention-bg));
  --dnp-retention-faint: color-mix(in oklch, var(--dnp-retention-ink) 46%, var(--dnp-retention-bg));
  --dnp-retention-heat0: color-mix(in oklch, var(--dnp-retention-bg), var(--dnp-retention-cool) 16%);
  --dnp-retention-bad: oklch(0.7 0.15 28);
  --dnp-retention-sans: system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  --dnp-retention-mono: ui-monospace, "SF Mono", Menlo, Consolas, monospace;
  --dnp-retention-out: cubic-bezier(.16, 1, .3, 1);
  --dnp-retention-tipbg: oklch(0.97 0.01 90);
  --dnp-retention-tipink: oklch(0.22 0.02 210);
  color-scheme: dark;
  border-radius: 16px;
  box-shadow: inset 0 0 0 1px var(--dnp-retention-line);
}
.dnp-retention__app {
  height: 100%;
  display: grid;
  grid-template-columns: 200px minmax(0, 1fr);
  grid-template-rows: auto minmax(0, 1fr);
  grid-template-areas: "nav top" "nav main";
}
/* nav */
.dnp-retention__nav {
  grid-area: nav; min-height: 0; display: flex; flex-direction: column; gap: 20px;
  padding: 18px 12px; background: var(--dnp-retention-side); border-right: 1px solid var(--dnp-retention-hair);
}
.dnp-retention__brand {
  display: flex; align-items: center; gap: 10px; padding: 0 6px;
  & .dnp-retention__logo { width: 32px; height: 32px; border-radius: 50%; display: grid; place-items: center; color: var(--dnp-retention-bg); background: var(--dnp-retention-accent); flex: none; }
  & .dnp-retention__brandtx { display: grid; line-height: 1.15; }
  & b { font-size: 14px; font-weight: 720; letter-spacing: -.01em; }
  & small { font-size: 11px; color: var(--dnp-retention-faint); }
}
.dnp-retention__navlist { display: grid; gap: 2px; }
.dnp-retention__navbtn {
  width: 100%; height: 36px; display: flex; align-items: center; gap: 10px; padding: 0 10px; border-radius: 9px;
  color: var(--dnp-retention-mute); font-weight: 560; transition: background-color .18s, color .18s;
  & span { flex: 1; text-align: left; white-space: nowrap; }
  & .dnp-retention__navn { font: normal 600 10.5px var(--dnp-retention-mono); padding: 1px 6px; border-radius: 99px; background: color-mix(in oklch, var(--dnp-retention-bad) 22%, transparent); color: var(--dnp-retention-bad); }
  &:hover { color: var(--dnp-retention-ink); background: var(--dnp-retention-hair); }
  &[aria-current="page"] { color: var(--dnp-retention-ink); background: color-mix(in oklch, var(--dnp-retention-accent) 13%, transparent); box-shadow: inset 2px 0 0 var(--dnp-retention-accent); }
  &[aria-current="page"] .dnp-retention__i { color: var(--dnp-retention-accent); }
}
.dnp-retention__navnote { margin-top: auto; padding: 0 6px; font-size: 11.5px; line-height: 1.5; color: var(--dnp-retention-faint); & b { color: var(--dnp-retention-mute); font-weight: 600; } }
/* top */
.dnp-retention__top {
  grid-area: top; display: flex; align-items: center; justify-content: space-between; gap: 10px 18px; flex-wrap: wrap;
  padding: 18px 22px 14px;
}
.dnp-retention__title h2 { font-size: clamp(19px, 2.2cqi, 25px); font-weight: 700; letter-spacing: -.025em; line-height: 1.1; }
.dnp-retention__sub { color: var(--dnp-retention-faint); font-size: 12.5px; margin-top: 3px; }
.dnp-retention__seg {
  display: inline-flex; padding: 3px; gap: 2px; border-radius: 10px; background: var(--dnp-retention-side); box-shadow: inset 0 0 0 1px var(--dnp-retention-hair);
  & button { height: 27px; padding: 0 11px; border-radius: 7px; font-size: 12px; font-weight: 600; color: var(--dnp-retention-mute); transition: background-color .2s, color .2s; white-space: nowrap; }
  & button:hover { color: var(--dnp-retention-ink); }
  & button[aria-checked="true"] { background: var(--dnp-retention-accent); color: var(--dnp-retention-bg); }
}
.dnp-retention__seg--sm button { height: 24px; padding: 0 9px; font-size: 11.5px; }
.dnp-retention__seg--sm button[aria-checked="true"] { background: var(--dnp-retention-raise); color: var(--dnp-retention-ink); box-shadow: inset 0 0 0 1px var(--dnp-retention-line); }
/* main */
.dnp-retention__main { grid-area: main; min-height: 0; padding: 0 22px 18px; }
.dnp-retention__view { height: 100%; transition: opacity .35s, translate .5s var(--dnp-retention-out); @starting-style { opacity: 0; translate: 0 8px; } }
.dnp-retention__panel { min-height: 0; min-width: 0; display: flex; flex-direction: column; border-radius: 14px; background: var(--dnp-retention-card); box-shadow: inset 0 0 0 1px var(--dnp-retention-hair); }
.dnp-retention__ph {
  display: flex; align-items: center; gap: 8px 10px; flex-wrap: wrap; padding: 12px 14px 8px;
  & h3 { font-size: 13px; font-weight: 650; margin-right: auto; }
  & h3 small { font-weight: 450; color: var(--dnp-retention-faint); margin-left: 6px; font-size: 12px; }
}
.dnp-retention__phnote { font-size: 11.5px; color: var(--dnp-retention-faint); }
.dnp-retention__cv {
  display: grid; gap: 12px;
  grid-template-columns: minmax(0, 1fr) 286px;
  grid-template-rows: auto minmax(0, 1fr);
  grid-template-areas: "kpis kpis" "heat side";
}
.dnp-retention__kpis { grid-area: kpis; display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); gap: 12px; }
.dnp-retention__kpi {
  display: grid; gap: 1px; padding: 11px 14px; border-radius: 12px; background: var(--dnp-retention-card); box-shadow: inset 0 0 0 1px var(--dnp-retention-hair); min-width: 0;
  & .dnp-retention__kl { font-size: 11px; color: var(--dnp-retention-faint); font-weight: 600; letter-spacing: .03em; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
  & .dnp-retention__kv { font-size: clamp(19px, 2.3cqi, 26px); font-weight: 700; letter-spacing: -.03em; font-variant-numeric: tabular-nums; line-height: 1.2; }
  & .dnp-retention__ks { font-size: 11.5px; color: var(--dnp-retention-mute); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; font-variant-numeric: tabular-nums; }
  & .dnp-retention__ks em { font-style: normal; font-weight: 650; color: var(--dnp-retention-accent); }
  & .dnp-retention__ks em.is-down { color: var(--dnp-retention-bad); }
}
/* heat */
.dnp-retention__heatp { grid-area: heat; }
.dnp-retention__heatwrap { flex: 1; min-height: 0; padding: 0 12px 4px; }
.dnp-retention__heat {
  border-collapse: separate; border-spacing: 3px; table-layout: fixed; font-variant-numeric: tabular-nums;
  & th { font-size: 10.5px; font-weight: 600; color: var(--dnp-retention-faint); text-align: center; padding: 2px 0 4px; letter-spacing: .04em; }
  & th.is-col { color: var(--dnp-retention-accent); }
  & th[scope="row"] { width: 92px; text-align: left; padding: 0 6px 0 0; letter-spacing: 0; }
  & thead th:first-child { width: 92px; }
  & .dnp-retention__rowb { width: 100%; display: grid; text-align: left; padding: 3px 6px; border-radius: 7px; line-height: 1.2; transition: background-color .15s; }
  & .dnp-retention__rowb b { font-size: 12.5px; font-weight: 650; color: var(--dnp-retention-ink); }
  & .dnp-retention__rowb small { font-size: 10.5px; color: var(--dnp-retention-faint); font-weight: 500; }
  & .dnp-retention__rowb:hover { background: var(--dnp-retention-hair); }
  & tr.is-sel .dnp-retention__rowb { background: color-mix(in oklch, var(--dnp-retention-accent) 16%, transparent); }
  & tr.is-sel .dnp-retention__rowb b { color: var(--dnp-retention-accent); }
  & td { height: 34px; padding: 0; border-radius: 6px; position: relative; }
  & td.dnp-retention__c {
    --v: 0;
    background: color-mix(in oklch, var(--dnp-retention-accent) calc(var(--v) * 100%), var(--dnp-retention-heat0));
    color: color-mix(in oklch, var(--dnp-retention-ink) calc((1 - var(--v)) * 100%), var(--dnp-retention-bg));
    text-align: center; font-size: 11.5px; font-weight: 600; cursor: pointer;
    transition: background-color .5s var(--dnp-retention-out), color .5s, box-shadow .15s, scale .2s var(--dnp-retention-out);
  }
  & td.dnp-retention__c.is-dark { color: var(--dnp-retention-bg); }
  & td.dnp-retention__c.is-base { background: var(--dnp-retention-raise); color: var(--dnp-retention-mute); box-shadow: inset 0 0 0 1px var(--dnp-retention-line); }
  & td.dnp-retention__c.is-base:hover { box-shadow: 0 0 0 2px var(--dnp-retention-ink); }
  & td.dnp-retention__c.is-base[aria-selected="true"] { box-shadow: 0 0 0 2px var(--dnp-retention-bg), 0 0 0 4px var(--dnp-retention-accent); }
  & td.dnp-retention__c.is-light { color: var(--dnp-retention-ink); }
  & td.dnp-retention__c:hover { box-shadow: 0 0 0 2px var(--dnp-retention-ink); z-index: 1; }
  & td.dnp-retention__c[aria-selected="true"] { box-shadow: 0 0 0 2px var(--dnp-retention-bg), 0 0 0 4px var(--dnp-retention-accent); z-index: 2; }
  & td.dnp-retention__c:focus-visible { outline: 2px solid var(--dnp-retention-ink); outline-offset: 2px; }
  & td.dnp-retention__e { background: repeating-linear-gradient(-45deg, transparent 0 5px, var(--dnp-retention-hair) 5px 6px); }
  & tr.is-avg th, & tr.is-avg td { border-top: 0; }
  & tr.is-avg td.dnp-retention__a { text-align: center; font-size: 11px; font-weight: 650; color: var(--dnp-retention-mute); background: none; box-shadow: inset 0 1px 0 var(--dnp-retention-line); border-radius: 0; }
  & tr.is-avg th { color: var(--dnp-retention-mute); font-size: 11px; padding-top: 6px; }
  &.is-intro td.dnp-retention__c { animation: dnp-retention-cell .55s var(--dnp-retention-out) both; animation-delay: calc(var(--i) * 38ms + 80ms); }
}
@keyframes dnp-retention-cell { from { opacity: 0; scale: .6; filter: blur(4px); } }
.dnp-retention__scale {
  display: flex; align-items: center; gap: 8px; padding: 6px 16px 12px; font-size: 10.5px; color: var(--dnp-retention-faint); font-variant-numeric: tabular-nums;
  & i { flex: 0 1 180px; height: 7px; border-radius: 4px; background: linear-gradient(to right in oklch, var(--dnp-retention-heat0), var(--dnp-retention-accent)); }
}
/* side */
.dnp-retention__side { grid-area: side; }
.dnp-retention__sidet { font-size: 14px !important; }
.dnp-retention__mini { position: relative; flex: 1; min-height: 150px; margin: 4px 8px 0; }
.dnp-retention__minisvg, .dnp-retention__svg {
  position: absolute; inset: 0; width: 100%; height: 100%; cursor: crosshair;
  & text { font: 10px var(--dnp-retention-sans); fill: var(--dnp-retention-faint); font-variant-numeric: tabular-nums; }
  & .dnp-retention__g line { stroke: var(--dnp-retention-hair); }
  & .dnp-retention__avg { fill: none; stroke: var(--dnp-retention-mute); stroke-width: 1.5; stroke-dasharray: 3 4; }
  & .dnp-retention__cur { fill: none; stroke: var(--dnp-retention-accent); stroke-width: 2.5; stroke-linejoin: round; stroke-linecap: round; }
  & .dnp-retention__curA { fill: color-mix(in oklch, var(--dnp-retention-accent) 14%, transparent); }
  & .dnp-retention__pt { fill: var(--dnp-retention-bg); stroke: var(--dnp-retention-accent); stroke-width: 2; }
  & .dnp-retention__pt.is-sel { fill: var(--dnp-retention-accent); }
  & .dnp-retention__xh { stroke: var(--dnp-retention-ink); stroke-opacity: .35; opacity: 0; }
  & .dnp-retention__xh.is-on { opacity: 1; }
  & .dnp-retention__ln { fill: none; stroke-width: 2; stroke-linejoin: round; stroke-linecap: round; transition: opacity .3s, stroke-width .2s; }
  & .dnp-retention__ln.is-dim { opacity: .18; }
  & .dnp-retention__ln.is-hot { stroke-width: 3.2; }
  & .dnp-retention__lnlab { font-weight: 650; font-size: 10.5px; }
  & .dnp-retention__hd { stroke: var(--dnp-retention-bg); stroke-width: 1.5; opacity: 0; }
  & .dnp-retention__hd.is-on { opacity: 1; }
  &.is-intro .dnp-retention__cur, &.is-intro .dnp-retention__ln { stroke-dasharray: 1; animation: dnp-retention-draw 1s var(--dnp-retention-out) both; animation-delay: calc(var(--i, 0) * 60ms); }
  &.is-intro .dnp-retention__curA { animation: dnp-retention-fade .8s .3s both; }
  &:focus-visible { outline-offset: -2px; border-radius: 8px; }
}
@keyframes dnp-retention-draw { from { stroke-dashoffset: 1; } to { stroke-dashoffset: 0; } }
@keyframes dnp-retention-fade { from { opacity: 0; } }
.dnp-retention__dl {
  display: grid; grid-template-columns: 1fr auto; gap: 7px 12px; padding: 12px 16px 16px; font-size: 12px; border-top: 1px solid var(--dnp-retention-hair); margin-top: 8px;
  & dt { color: var(--dnp-retention-faint); }
  & dd { text-align: right; font-weight: 650; font-variant-numeric: tabular-nums; }
  & dd em { font-style: normal; font-size: 11px; font-weight: 600; margin-left: 4px; color: var(--dnp-retention-accent); }
  & dd em.is-down { color: var(--dnp-retention-bad); }
}
.dnp-retention__minikey { display: flex; gap: 14px; padding: 0 14px; font-size: 11px; color: var(--dnp-retention-faint); & i { display: inline-block; width: 14px; height: 0; border-top: 2px solid var(--dnp-retention-accent); vertical-align: middle; margin-right: 5px; } & i.d { border-top: 2px dashed var(--dnp-retention-mute); } }
/* ltv view */
.dnp-retention__lv { display: grid; gap: 12px; grid-template-columns: minmax(0, 1.5fr) minmax(0, 1fr); }
.dnp-retention__legend {
  display: flex; flex-wrap: wrap; gap: 4px; padding: 0 14px 6px;
  & button { display: inline-flex; align-items: center; gap: 6px; height: 24px; padding: 0 9px 0 7px; border-radius: 99px; font-size: 11.5px; font-weight: 600; font-variant-numeric: tabular-nums; color: var(--dnp-retention-faint); box-shadow: inset 0 0 0 1px var(--dnp-retention-hair); transition: color .15s, background-color .15s; }
  & button i { width: 14px; height: 3px; border-radius: 2px; background: var(--c); opacity: .35; transition: opacity .2s; }
  & button[aria-pressed="true"] { color: var(--dnp-retention-ink); background: var(--dnp-retention-raise); }
  & button[aria-pressed="true"] i { opacity: 1; }
}
.dnp-retention__plot { position: relative; flex: 1; min-height: 180px; margin: 0 8px 8px; }
.dnp-retention__chkey { display: flex; gap: 14px; padding: 0 16px 8px; font-size: 11px; color: var(--dnp-retention-faint); & i { display: inline-block; width: 10px; height: 10px; border-radius: 3px; margin-right: 6px; vertical-align: -1px; } & i.a { background: var(--dnp-retention-cool); } & i.b { width: 2px; height: 12px; border-radius: 1px; background: var(--dnp-retention-accent); } }
.dnp-retention__chans {
  flex: 1; min-height: 0; overflow: auto; padding: 4px 16px 14px; display: grid; align-content: start; gap: 14px;
  & li { display: grid; grid-template-columns: minmax(0, 1fr) auto; gap: 4px 10px; cursor: default; }
  & .dnp-retention__chn { font-weight: 600; font-size: 12.5px; }
  & .dnp-retention__chn small { display: block; font-weight: 450; color: var(--dnp-retention-faint); font-size: 11px; font-variant-numeric: tabular-nums; }
  & .dnp-retention__roi { align-self: center; font: 700 15px var(--dnp-retention-sans); letter-spacing: -.02em; font-variant-numeric: tabular-nums; color: var(--dnp-retention-accent); text-align: right; }
  & .dnp-retention__roi small { display: block; font-size: 10.5px; font-weight: 500; color: var(--dnp-retention-faint); letter-spacing: 0; }
  & .dnp-retention__roi.is-low { color: var(--dnp-retention-bad); }
  & .dnp-retention__bar { grid-column: 1 / -1; position: relative; height: 12px; border-radius: 4px; background: var(--dnp-retention-hair); }
  & .dnp-retention__bar i { position: absolute; inset: 0 auto 0 0; width: calc(var(--w) * 100%); border-radius: 4px; background: var(--dnp-retention-cool); transform-origin: left; transition: width .6s var(--dnp-retention-out); }
  & .dnp-retention__bar b { position: absolute; top: -3px; bottom: -3px; left: calc(var(--c) * 100%); width: 2px; border-radius: 1px; background: var(--dnp-retention-accent); box-shadow: 0 0 0 2px var(--dnp-retention-card); transition: left .6s var(--dnp-retention-out); }
  &.is-intro .dnp-retention__bar i { animation: dnp-retention-bar .9s var(--dnp-retention-out) both; animation-delay: calc(var(--i) * 70ms + 100ms); }
}
@keyframes dnp-retention-bar { from { scale: 0 1; } }
/* lapsed */
.dnp-retention__xv { display: flex; flex-direction: column; }
.dnp-retention__lapp { flex: 1; }
.dnp-retention__lapsum { padding: 0 14px 10px; font-size: 12.5px; color: var(--dnp-retention-mute); font-variant-numeric: tabular-nums; max-width: 80ch; & b { color: var(--dnp-retention-ink); } }
.dnp-retention__btn {
  position: relative; overflow: hidden; height: 30px; padding: 0 13px; border-radius: 8px; font-size: 12px; font-weight: 650;
  background: var(--dnp-retention-accent); color: var(--dnp-retention-bg); transition: opacity .2s, filter .2s;
  & .dnp-retention__btnbar { position: absolute; inset: 0; background: color-mix(in oklch, var(--dnp-retention-ink) 45%, transparent); transform-origin: left; scale: 0 1; }
  & .dnp-retention__btnlab { position: relative; }
  &:hover:not(:disabled) { filter: brightness(1.08); }
  &:disabled { opacity: .42; }
  &.is-busy .dnp-retention__btnbar { animation: dnp-retention-busy .9s linear both; }
}
@keyframes dnp-retention-busy { to { scale: 1 1; } }
.dnp-retention__tw { flex: 1; min-height: 0; margin: 0 6px 6px; }
.dnp-retention__table {
  font-size: 12.5px; font-variant-numeric: tabular-nums;
  & th { position: sticky; top: 0; z-index: 1; background: var(--dnp-retention-card); text-align: left; font-size: 11px; font-weight: 600; color: var(--dnp-retention-faint); padding: 6px 10px; box-shadow: inset 0 -1px 0 var(--dnp-retention-line); white-space: nowrap; }
  & th button { color: inherit; font-weight: inherit; display: inline-flex; gap: 5px; align-items: center; }
  & th button::after { content: "↕"; font-size: 10px; opacity: .4; }
  & th[aria-sort="ascending"] button, & th[aria-sort="descending"] button { color: var(--dnp-retention-ink); }
  & th[aria-sort="ascending"] button::after { content: "↑"; opacity: 1; color: var(--dnp-retention-accent); }
  & th[aria-sort="descending"] button::after { content: "↓"; opacity: 1; color: var(--dnp-retention-accent); }
  & td { padding: 8px 10px; border-bottom: 1px solid var(--dnp-retention-hair); white-space: nowrap; }
  & .dnp-retention__num { text-align: right; }
  & th.dnp-retention__num button { flex-direction: row-reverse; }
  & .dnp-retention__ck { width: 34px; padding-right: 0; }
  & input[type="checkbox"] { width: 15px; height: 15px; margin: 0; cursor: pointer; }
  & tbody tr { transition: background-color .15s; }
  & tbody tr:hover { background: var(--dnp-retention-hair); }
  & tbody tr:has(input:checked) { background: color-mix(in oklch, var(--dnp-retention-accent) 10%, transparent); }
  & tbody tr.is-queued { color: var(--dnp-retention-faint); }
  & .dnp-retention__who b { font-weight: 600; display: block; color: var(--dnp-retention-ink); }
  & .dnp-retention__who small { color: var(--dnp-retention-faint); font-size: 11px; }
  & .dnp-retention__tag { display: inline-block; padding: 1px 7px; border-radius: 99px; font-size: 11px; font-weight: 600; background: var(--dnp-retention-hair); color: var(--dnp-retention-mute); }
  & .dnp-retention__tag.is-q { background: color-mix(in oklch, var(--dnp-retention-cool) 22%, transparent); color: var(--dnp-retention-cool); margin-left: 6px; }
  & .dnp-retention__lap { color: var(--dnp-retention-faint); font-size: 11px; display: block; }
}
@supports (animation-timeline: scroll()) {
  .dnp-retention__tw thead th { animation: dnp-retention-shade linear both; animation-timeline: scroll(nearest block); animation-range: 0 40px; }
  @keyframes dnp-retention-shade { to { box-shadow: inset 0 -1px 0 var(--dnp-retention-line), 0 8px 14px -10px oklch(0 0 0 / .6); } }
}
/* tooltip */
.dnp-retention__tip .dnp-retention__trow i { border-radius: 2px; }
/* rail */
@container dnp-retention (max-width: 960px) {
  .dnp-retention__app { grid-template-columns: 62px minmax(0, 1fr); }
  .dnp-retention__nav { padding: 16px 9px; align-items: center; }
  .dnp-retention__nav .dnp-retention__brand .dnp-retention__brandtx, .dnp-retention__nav .dnp-retention__navbtn span, .dnp-retention__nav .dnp-retention__navnote { display: none; }
  .dnp-retention__nav .dnp-retention__navbtn { width: 44px; padding: 0; justify-content: center; position: relative; }
  .dnp-retention__nav .dnp-retention__navbtn .dnp-retention__navn { position: absolute; top: -2px; right: -4px; font-size: 9px; padding: 0 4px; }
  .dnp-retention__main { overflow: auto; scrollbar-width: thin; }
  .dnp-retention__view { height: auto; }
