const sum = a => a.reduce((s, v) => s + v, 0);
const EASE = 'cubic-bezier(.22, 1, .36, 1)';
/* nice axis: a round step and top for 0..max */
const niceAxis = (max, count = 4) => {
  if (!(max > 0)) max = 1;
  const raw = max / count, p = Math.pow(10, Math.floor(Math.log10(raw))), f = raw / p;
  const step = (f <= 1 ? 1 : f <= 2 ? 2 : f <= 2.5 ? 2.5 : f <= 5 ? 5 : 10) * p;
  return { step, top: Math.ceil(max / step - 1e-9) * step };
};
/* tooltip, positioned in root coordinates from a client point */
const tipEl = $('.dnp-retention__tip');
const tip = (html, cx, cy) => {
  const r = root.getBoundingClientRect();
