  tipEl.classList.add('is-on');
  const w = tipEl.offsetWidth, h = tipEl.offsetHeight;
  let x = cx - r.left + 14, y = cy - r.top - h - 12;
  if (x + w > r.width - 8) x = cx - r.left - w - 14;
  if (x < 8) x = 8;
