};
const untip = () => tipEl.classList.remove('is-on');
/* toast */
let toastTimer = 0;
const toast = msg => {
  const t = $('.dnp-retention__toast');
  t.textContent = msg;
  t.classList.remove('is-on'); void t.offsetWidth; t.classList.add('is-on');
