  oneoff:  { n: 'One-off', size: [1610, 1744, 2310, 1980, 1866, 2050, 2124, 2236], y1: [.27, .27, .28, .29, .32, .34, .35, .36], r: .6, avg: 41, grow: 1.07, y0f: 1 },
  major:   { n: 'Major',   size: [14, 17, 21, 19, 24, 26, 29, 31], y1: [.64, .62, .66, .7, .68, .71, .73, .74], r: .78, avg: 1850, grow: 1.04, y0f: 1 }
