const KEYS = ['regular', 'oneoff', 'major'];
const M = {};
KEYS.forEach((k, si) => {
  const s = SEG[k];
  M[k] = YEARS.map((y, c) => {
    const act = [], rev = [];
    for (let j = 0; y + j <= LAST; j++) {
      let p = j === 0 ? 1 : s.y1[c] * Math.pow(s.r + (R() - .5) * .04, j - 1);
      let a = Math.round(s.size[c] * p);
