/* ================================================================ state */
const S = { seg: 'all', metric: 'donors', sel: { c: 3, j: 2 }, hidden: new Set(), sort: { k: 'value', dir: -1 }, picked: new Set(), queued: new Set() };
const data = () => seg(S.seg);
const value = (d, c, j) => {
  const r = d[c];
