};
const fmtV = v => S.metric === 'gift' ? gbp(v) : pct(v, v >= .995 && v <= 1.005 ? 0 : 1);

/* ================================================================ nav, segment, metric */
navInit(v => { if (v === 'ltv') renderLtv(true); if (v === 'lapsed') renderLapsed(); if (v === 'cohorts') requestAnimationFrame(() => { if (!root.isConnected) return; renderSide(false); }); });
