  const cur = r.kept / r.base, delta = (cur - prev) * 100;
  roll($('[data-k=overall]'), cur * 100, v => v.toFixed(1) + '%');
  $('[data-s=overall]').innerHTML = NF.format(r.kept) + ' of ' + NF.format(r.base) + ' · <em' + (delta < 0 ? ' class="is-down"' : '') + '>' + (delta >= 0 ? '+' : '−') + Math.abs(delta).toFixed(1) + ' pts</em>';
