    cur.forEach((v, k) => { o += '<circle class="dnp-retention__pt' + (k === j ? ' is-sel' : '') + '" r="' + (k === j ? 5 : 3.2) + '" cx="' + x(k) + '" cy="' + y(v) + '"/>'; });
