    '<dt>' + (YEARS[c] + j) + ' (year ' + j + ')</dt><dd>' + NF.format(r.act[j]) + ' · ' + pct(r.act[j] / r.act[0]) + '</dd>' +
    '<dt>Kept after year one</dt><dd>' + (y1 == null ? '<span style="color:var(--dnp-retention-faint)">from 2026</span>' : pct(y1) + '<em' + (y1 < avgY1 ? ' class="is-down"' : '') + '>' + (y1 >= avgY1 ? '+' : '−') + Math.abs((y1 - avgY1) * 100).toFixed(1) + '</em>') + '</dd>' +
    '<dt>Still giving in 2025</dt><dd>' + NF.format(last) + '</dd>' +
    '<dt>Income to date</dt><dd>' + gbp(total) + '</dd>' +
