};
const SEG_LABEL = () => S.seg === 'all' ? 'donors' : SEG[S.seg].n.toLowerCase() + ' donors';
mini.addEventListener('pointermove', e => {
  if (!miniState) return;
  const b = mini.getBoundingClientRect(), s = miniState, k = clamp(Math.round((e.clientX - b.left - s.m.l) / s.iw * (K - 1)), 0, K - 1);
  const xh = $('.dnp-retention__xh', mini); xh.setAttribute('x1', s.x(k)); xh.setAttribute('x2', s.x(k)); xh.classList.add('is-on');
  tip('<span class="dnp-retention__tt">Year ' + k + '</span>' + (k < s.cur.length ? '<span class="dnp-retention__trow"><span>' + YEARS[S.sel.c] + ' cohort</span><b>' + pct(s.cur[k]) + '</b></span>' : '<span class="dnp-retention__trow"><span>' + YEARS[S.sel.c] + ' cohort</span><b>not yet</b></span>') + '<span class="dnp-retention__trow"><span>All-cohort average</span><b>' + pct(s.avg[k]) + '</b></span>', e.clientX, e.clientY);
});
mini.addEventListener('pointerleave', () => { untip(); const xh = $('.dnp-retention__xh', mini); if (xh) xh.classList.remove('is-on'); });
onResize(miniBox, () => renderSide(false));

/* ================================================================ LTV curves */
const lsvg = $('.dnp-retention__svg'), lplot = $('.dnp-retention__plot'), legend = $('.dnp-retention__legend');
const cohortColor = c => 'color-mix(in oklch, var(--dnp-retention-accent) ' + Math.round(c / (YEARS.length - 1) * 100) + '%, var(--dnp-retention-cool))';
legend.innerHTML = YEARS.map((y, c) => '<button type="button" aria-pressed="true" data-c="' + c + '" style="--c:' + cohortColor(c) + '"><i></i>' + y + '</button>').join('');
const syncLegend = () => $$('button', legend).forEach(b => {
  const on = !S.hidden.has(+b.dataset.c), last = on && S.hidden.size === YEARS.length - 1;
  b.setAttribute('aria-pressed', String(on));
  if (last) { b.setAttribute('aria-disabled', 'true'); b.title = 'At least one cohort stays visible'; } else { b.removeAttribute('aria-disabled'); b.title = (on ? 'Hide ' : 'Show ') + b.textContent + ' cohort'; }
});
legend.addEventListener('click', e => {
  const b = e.target.closest('button'); if (!b || b.getAttribute('aria-disabled') === 'true') return;
  const c = +b.dataset.c; if (S.hidden.has(c)) S.hidden.delete(c); else S.hidden.add(c);
  syncLegend(); renderLtv(false);
});
let ltvState = null, ltvHover = -1;
const renderLtv = intro => {
  syncLegend();
  const d = data(), [W, H] = measure(lplot);
  if (!W || !H) return;
  lsvg.setAttribute('viewBox', '0 0 ' + W + ' ' + H);
  const curves = YEARS.map((y, c) => { let acc = 0; return d[c].rev.map(v => (acc += v) / d[c].act[0]); });
  const vis = YEARS.map((_, c) => c).filter(c => !S.hidden.has(c));
  const max = Math.max(...vis.map(c => Math.max(...curves[c])));
  const ax = niceAxis(max * 1.05, 5), m = { l: 48, r: 54, t: 12, b: 24 }, iw = W - m.l - m.r, ih = H - m.t - m.b;
  const x = k => m.l + k / (K - 1) * iw, y = v => m.t + ih - v / ax.top * ih;
  let o = '<g class="dnp-retention__g">';
  for (let v = 0; v <= ax.top + 1e-6; v += ax.step) o += '<line x1="' + m.l + '" x2="' + (W - m.r) + '" y1="' + y(v) + '" y2="' + y(v) + '"/><text x="' + (m.l - 7) + '" y="' + (y(v) + 3) + '" text-anchor="end">' + kgbp(v) + '</text>';
  for (let k = 0; k < K; k++) o += '<text x="' + x(k) + '" y="' + (H - 6) + '" text-anchor="middle">Y' + k + '</text>';
  o += '</g><line class="dnp-retention__xh" y1="' + m.t + '" y2="' + (m.t + ih) + '"/>';
  vis.forEach((c, i) => {
    const pts = curves[c].map((v, k) => x(k).toFixed(1) + ',' + y(v).toFixed(1));
    o += '<path class="dnp-retention__ln" data-c="' + c + '" pathLength="1" style="--i:' + i + ';stroke:' + cohortColor(c) + '" d="M' + pts.join('L') + '"/>';
    const lk = curves[c].length - 1;
    o += '<text class="dnp-retention__lnlab" data-c="' + c + '" x="' + (x(lk) + 7) + '" y="' + (y(curves[c][lk]) + 3.5) + '" style="fill:' + cohortColor(c) + '">' + YEARS[c] + '</text>';
  });
  o += vis.map(c => '<circle class="dnp-retention__hd" data-c="' + c + '" r="4" style="fill:' + cohortColor(c) + '"/>').join('');
  lsvg.innerHTML = o;
  lsvg.classList.toggle('is-intro', !!intro);
  ltvState = { x, y, curves, vis, m, iw };
  /* avoid overlapping end labels: nudge apart vertically */
  const labs = $$('.dnp-retention__lnlab', lsvg).sort((a, b) => +a.getAttribute('y') - +b.getAttribute('y'));
  for (let i = 1; i < labs.length; i++) { const p = +labs[i - 1].getAttribute('y'), q = +labs[i].getAttribute('y'); if (q - p < 12 && +labs[i].getAttribute('x') === +labs[i - 1].getAttribute('x')) labs[i].setAttribute('y', p + 12); }
  if (ltvHover > -1) ltvAt(ltvHover);
  renderChannels(intro);
};
const ltvAt = (k, cx, cy) => {
  const s = ltvState; if (!s) return;
  k = clamp(k, 0, K - 1); ltvHover = k;
  const xh = $('.dnp-retention__xh', lsvg); xh.setAttribute('x1', s.x(k)); xh.setAttribute('x2', s.x(k)); xh.classList.add('is-on');
  const rows = [];
  s.vis.forEach(c => {
    const dot = lsvg.querySelector('.dnp-retention__hd[data-c="' + c + '"]');
    if (k < s.curves[c].length) { dot.setAttribute('cx', s.x(k)); dot.setAttribute('cy', s.y(s.curves[c][k])); dot.classList.add('is-on'); rows.push([c, s.curves[c][k]]); }
    else dot.classList.remove('is-on');
  });
  rows.sort((a, b) => b[1] - a[1]);
  const box = lsvg.getBoundingClientRect();
  tip('<span class="dnp-retention__tt">Cumulative to Y' + k + ' · ' + (k + 1) + (k ? ' years' : ' year') + ' of giving</span>' + rows.map(([c, v]) => '<span class="dnp-retention__trow"><span><i style="--c:' + cohortColor(c) + '"></i>' + YEARS[c] + '</span><b>' + gbp(v) + '</b></span>').join('') || 'No cohort has reached this year',
    cx ?? box.left + s.x(k), cy ?? box.top + 40);
};
lsvg.addEventListener('pointermove', e => { const s = ltvState; if (!s) return; const b = lsvg.getBoundingClientRect(); ltvAt(Math.round((e.clientX - b.left - s.m.l) / s.iw * (K - 1)), e.clientX, e.clientY); });
const ltvOff = () => { ltvHover = -1; untip(); $$('.is-on', lsvg).forEach(x => x.classList.remove('is-on')); };
lsvg.addEventListener('pointerleave', ltvOff);
lsvg.addEventListener('blur', ltvOff);
lsvg.addEventListener('keydown', e => {
  let k = ltvHover < 0 ? 0 : ltvHover;
  if (e.key === 'ArrowRight') k++; else if (e.key === 'ArrowLeft') k--; else if (e.key === 'Escape') { ltvOff(); return; } else return;
