onResize(lplot, () => renderLtv(false));

/* channels: shares split the 2022-24 cohorts exactly, value multipliers keep the weighted mean equal to the cohort figure */
const CHANS = [
  { n: 'Online appeals', share: { regular: .3, oneoff: .46, major: .1 }, mult: .92, cpa: { regular: 62, oneoff: 18, major: 240 } },
  { n: 'Street fundraising', share: { regular: .44, oneoff: .02, major: 0 }, mult: .86, cpa: { regular: 168, oneoff: 40, major: 0 } },
  { n: 'Direct mail', share: { regular: .08, oneoff: .3, major: .22 }, mult: 1.06, cpa: { regular: 74, oneoff: 31, major: 210 } },
  { n: 'Hedgehog adoptions', share: { regular: .14, oneoff: .14, major: 0 }, mult: 1.24, cpa: { regular: 38, oneoff: 22, major: 0 } },
  { n: 'Events & open days', share: { regular: .04, oneoff: .08, major: .68 }, mult: 1.1, cpa: { regular: 90, oneoff: 35, major: 520 } }
];
const lr = (vals, total) => { const s = sum(vals) || 1, sc = vals.map(v => v / s * total), fl = sc.map(Math.floor); let left = total - sum(fl); sc.map((v, i) => [v - fl[i], i]).sort((a, b) => b[0] - a[0]).forEach(([, i]) => { if (left-- > 0) fl[i]++; }); return fl; };
const chans = $('.dnp-retention__chans');
const renderChannels = intro => {
  const keys = S.seg === 'all' ? KEYS : [S.seg];
  const rows = CHANS.map(ch => ({ n: ch.n, donors: 0, value: 0, cost: 0 }));
  keys.forEach(k => {
    const cs = [4, 5, 6].map(c => M[k][c]);
    const size = sum(cs.map(r => r.act[0]));
    const rev3 = sum(cs.map(r => sum(r.rev.slice(0, 3))));
    const split = lr(CHANS.map(ch => ch.share[k]), size);
    const wm = sum(split.map((n, i) => n * CHANS[i].mult)) / (size || 1);
    split.forEach((n, i) => { rows[i].donors += n; rows[i].value += n ? rev3 / size * CHANS[i].mult / wm * n : 0; rows[i].cost += n * CHANS[i].cpa[k]; });
  });
  const live = rows.filter(r => r.donors > 0);
  const mx = Math.max(...live.map(r => Math.max(r.value / r.donors, r.cost / r.donors))) * 1.08;
  chans.innerHTML = live.map((r, i) => {
    const per = r.value / r.donors, cpa = r.cost / r.donors, roi = per / cpa;
    return '<li style="--i:' + i + '" data-i="' + rows.indexOf(r) + '"><span class="dnp-retention__chn">' + esc(r.n) + '<small>' + NF.format(r.donors) + ' donors · ' + gbp(per) + ' each · ' + gbp(cpa) + ' to acquire</small></span><span class="dnp-retention__roi' + (roi < 1.5 ? ' is-low' : '') + '">' + roi.toFixed(1) + '×<small>return</small></span><span class="dnp-retention__bar" style="--w:' + (per / mx).toFixed(4) + ';--c:' + (cpa / mx).toFixed(4) + '"><i></i><b></b></span></li>';
  }).join('');
  chans.classList.toggle('is-intro', !!intro);
  chans._rows = rows;
};
chans.addEventListener('pointermove', e => {
  const li = e.target.closest('li'); if (!li) { untip(); return; }
  const r = chans._rows[+li.dataset.i], per = r.value / r.donors, cpa = r.cost / r.donors;
  tip('<span class="dnp-retention__tt">' + esc(r.n) + '</span><span class="dnp-retention__trow"><span>Donors acquired</span><b>' + NF.format(r.donors) + '</b></span><span class="dnp-retention__trow"><span>3-year income</span><b>' + gbp(r.value) + '</b></span><span class="dnp-retention__trow"><span>Acquisition cost</span><b>' + gbp(r.cost) + '</b></span><span class="dnp-retention__trow"><span>Net per donor</span><b>' + gbp(per - cpa) + '</b></span>', e.clientX, e.clientY);
});
chans.addEventListener('pointerleave', untip);

/* ================================================================ lapsed donors */
const FIRST = ['Agnes', 'Rory', 'Delphine', 'Hamid', 'Teresa', 'Gethin', 'Mirela', 'Duncan', 'Ines', 'Patrick', 'Yasmin', 'Corin', 'Bethan', 'Malik', 'Joan', 'Wilf', 'Saoirse', 'Tobias', 'Ngozi', 'Alastair', 'Hilde', 'Kwame', 'Rosalind', 'Elliot', 'Anouk', 'Brendan', 'Priti', 'Gwen', 'Lorcan', 'Esther'];
const LASTN = ['Ashby', 'Penrose', 'Quayle', 'Odell', 'Marchetti', 'Haldane', 'Okafor', 'Fairley', 'Lindqvist', 'Rowntree', 'Sheridan', 'Kaur', 'Whitlow', 'Brannigan', 'Esposito', 'Thorne', 'Mbeki', 'Calloway', 'Dunmore', 'Achterberg'];
const MONTHS = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];
const R2 = rng(77);
const lapsed = Array.from({ length: 64 }, (_, i) => {
  const r = R2(), segk = r < .12 ? 'major' : r < .42 ? 'regular' : 'oneoff', s = SEG[segk];
  const since = 2018 + Math.floor(R2() * 7), years = 2024 - since + 1;
  const gifts = segk === 'regular' ? Math.max(4, Math.round(years * 12 * (.55 + R2() * .4))) : Math.max(1, Math.round(years * (segk === 'major' ? 1.4 : 1.6) * (.5 + R2())));
  const val = segk === 'regular' ? gifts * (6 + Math.round(R2() * 6)) : Math.round(gifts * s.avg * (.6 + R2() * .9));
  const m = Math.floor(R2() * 12);
  return { id: i, name: FIRST[Math.floor(R2() * FIRST.length)] + ' ' + LASTN[Math.floor(R2() * LASTN.length)], seg: segk, since, gifts, value: val, last: 2024 * 12 + m };
});
const tb = $('.dnp-retention__table tbody'), qbtn = $('[data-act=queue]'), allBox = $('[data-all]');
const lapRows = () => {
  let v = lapsed.filter(p => S.seg === 'all' || p.seg === S.seg);
  const f = { name: p => p.name, gifts: p => p.gifts, value: p => p.value, last: p => p.last }[S.sort.k];
  return v.slice().sort((a, b) => { const x = f(a), y = f(b); return (x < y ? -1 : x > y ? 1 : a.id - b.id) * S.sort.dir; });
};
const renderLapsed = () => {
  const d = data(), r = retention(d), rows = lapRows();
  $('.dnp-retention__lapsum').innerHTML = '<b>' + NF.format(r.base - r.kept) + '</b> ' + SEG_LABEL() + ' gave in 2024 but not in 2025. The ' + rows.length + ' with the most lifetime giving are listed; <b>' + gbp(sum(rows.map(p => p.value))) + '</b> between them.';
  tb.innerHTML = rows.map(p => {
    const q = S.queued.has(p.id), ago = (2026 * 12 + 9) - p.last;
    return '<tr data-id="' + p.id + '" class="' + (q ? 'is-queued' : '') + '"><td class="dnp-retention__ck"><input type="checkbox" aria-label="Select ' + esc(p.name) + '"' + (S.picked.has(p.id) ? ' checked' : '') + (q ? ' disabled title="Already in the reactivation mailing"' : '') + '></td>' +
      '<td class="dnp-retention__who"><b>' + esc(p.name) + (q ? '<span class="dnp-retention__tag is-q">Queued</span>' : '') + '</b><small>Giving since ' + p.since + '</small></td><td class="dnp-retention__hide-s"><span class="dnp-retention__tag">' + SEG[p.seg].n + '</span></td>' +
      '<td class="dnp-retention__num dnp-retention__hide-s">' + NF.format(p.gifts) + '</td><td class="dnp-retention__num"><b>' + gbp(p.value) + '</b></td><td class="dnp-retention__num">' + MONTHS[p.last % 12] + ' ' + Math.floor(p.last / 12) + '<span class="dnp-retention__lap">' + ago + ' months ago</span></td></tr>';
  }).join('');
  $$('.dnp-retention__table th[aria-sort]').forEach(th => th.setAttribute('aria-sort', th.querySelector('button').dataset.sort === S.sort.k ? (S.sort.dir > 0 ? 'ascending' : 'descending') : 'none'));
  syncPick();
};
const syncPick = () => {
  const rows = lapRows().filter(p => !S.queued.has(p.id)), n = rows.filter(p => S.picked.has(p.id)).length;
  allBox.checked = n > 0 && n === rows.length; allBox.indeterminate = n > 0 && n < rows.length;
  allBox.disabled = !rows.length;
  qbtn.disabled = n === 0 || qbtn.classList.contains('is-busy');
  qbtn.title = n ? 'Add ' + n + ' donors to the November reactivation mailing' : 'Select donors first';
  $('.dnp-retention__btnlab', qbtn).textContent = n ? 'Add ' + n + ' to reactivation mailing' : 'Add to reactivation mailing';
};
tb.addEventListener('change', e => {
  const cb = e.target.closest('input[type=checkbox]'); if (!cb) return;
  const id = +cb.closest('tr').dataset.id;
  if (cb.checked) S.picked.add(id); else S.picked.delete(id);
  syncPick();
});
allBox.addEventListener('change', () => {
  const rows = lapRows().filter(p => !S.queued.has(p.id));
  rows.forEach(p => { if (allBox.checked) S.picked.add(p.id); else S.picked.delete(p.id); });
  $$('tr', tb).forEach(tr => { const cb = $('input', tr); if (!cb.disabled) cb.checked = allBox.checked; });
  syncPick();
});
$('.dnp-retention__table thead').addEventListener('click', e => {
  const b = e.target.closest('[data-sort]'); if (!b) return;
  const k = b.dataset.sort;
  S.sort = S.sort.k === k ? { k, dir: -S.sort.dir } : { k, dir: k === 'name' ? 1 : -1 };
  const before = $$('tr', tb), pos = new Map(before.map(tr => [tr.dataset.id, tr.getBoundingClientRect().top]));
  renderLapsed();
  if (!RM) $$('tr', tb).forEach(tr => { const t0 = pos.get(tr.dataset.id); if (t0 == null) return; const dy = t0 - tr.getBoundingClientRect().top; if (Math.abs(dy) > 1) tr.animate([{ transform: 'translateY(' + dy + 'px)' }, { transform: 'none' }], { duration: 480, easing: EASE }); });
});
qbtn.addEventListener('click', () => {
  if (qbtn.disabled) return;
  const ids = lapRows().filter(p => S.picked.has(p.id) && !S.queued.has(p.id)).map(p => p.id);
  if (!ids.length) return;
  qbtn.classList.add('is-busy'); qbtn.disabled = true; $('.dnp-retention__btnlab', qbtn).textContent = 'Adding ' + ids.length + '…';
  setTimeout(() => {
