renderAll(true);

css:
.dnp-grants {
  width: 100%;
  height: var(--dnp-grants-h, 680px);
  container-type: inline-size;
  container-name: dnp-grants;
  position: relative;
  isolation: isolate;
  overflow: hidden;
  background: var(--dnp-grants-bg);
  color: var(--dnp-grants-ink);
  font: 13px/1.45 var(--dnp-grants-sans);
  accent-color: var(--dnp-grants-accent);
  -webkit-font-smoothing: antialiased;
  & *, & *::before, & *::after { box-sizing: border-box; }
  & :where(h1, h2, h3, h4, p, ol, ul, dl, dd, figure) { margin: 0; padding: 0; }
  & :where(ol, ul) { list-style: none; }
  & :where(h1, h2, h3, h4) { text-wrap: balance; font-weight: 650; }
  & :where(p) { text-wrap: pretty; }
  & :where(button, input, select) { font: inherit; color: inherit; letter-spacing: inherit; }
  & :where(button) { background: none; border: 0; padding: 0; cursor: pointer; -webkit-tap-highlight-color: transparent; }
  & :where(button:disabled, [aria-disabled="true"]) { cursor: not-allowed; }
  & :where(svg) { display: block; overflow: visible; }
  & :where(table) { border-collapse: collapse; width: 100%; }
  & :focus-visible { outline: 2px solid var(--dnp-grants-focus, var(--dnp-grants-accent)); outline-offset: 2px; }
  & [hidden] { display: none !important; }
  & .dnp-grants__i { width: 18px; height: 18px; flex: none; fill: none; stroke: currentColor; stroke-width: 1.75; stroke-linecap: round; stroke-linejoin: round; }
  & .dnp-grants__sr { position: absolute; width: 1px; height: 1px; overflow: hidden; clip-path: inset(50%); white-space: nowrap; }
}
.dnp-grants__scroll {
  overflow: auto;
  overscroll-behavior: contain;
  scrollbar-width: thin;
  scrollbar-color: color-mix(in oklch, var(--dnp-grants-ink) 22%, transparent) transparent;
  &::-webkit-scrollbar { width: 8px; height: 8px; }
  &::-webkit-scrollbar-thumb { background: color-mix(in oklch, var(--dnp-grants-ink) 20%, transparent); border-radius: 8px; border: 2px solid transparent; background-clip: padding-box; }
}
.dnp-grants__tip {
  position: absolute; left: 0; top: 0; z-index: 40;
  pointer-events: none;
  min-width: 128px; max-width: 260px;
  padding: 8px 10px;
  border-radius: 10px;
  background: var(--dnp-grants-tipbg, color-mix(in oklch, var(--dnp-grants-ink) 94%, var(--dnp-grants-bg)));
  color: var(--dnp-grants-tipink, var(--dnp-grants-bg));
  font-size: 12px; line-height: 1.4;
