  & .dnp-grants__tt { display: block; font-size: 11px; letter-spacing: .04em; text-transform: uppercase; opacity: .7; margin-bottom: 3px; }
  & .dnp-grants__trow { display: flex; justify-content: space-between; gap: 14px; align-items: baseline; }
  & .dnp-grants__trow i { display: inline-block; width: 8px; height: 8px; border-radius: 2px; margin-right: 6px; background: var(--c); }
}
.dnp-grants__toast {
  position: absolute; left: 50%; bottom: 18px; z-index: 50;
  max-width: min(440px, calc(100% - 32px));
  padding: 10px 16px;
  border-radius: 12px;
  background: var(--dnp-grants-tipbg, color-mix(in oklch, var(--dnp-grants-ink) 94%, var(--dnp-grants-bg)));
  color: var(--dnp-grants-tipink, var(--dnp-grants-bg));
