@property --dnp-grants-p { syntax: "<number>"; inherits: true; initial-value: 0; }
.dnp-grants {
  /* re-theme with these four */
  --dnp-grants-bg: oklch(0.968 0.011 84);
  --dnp-grants-ink: oklch(0.25 0.018 262);
  --dnp-grants-accent: oklch(0.5 0.17 263);
  --dnp-grants-hot: oklch(0.6 0.2 33);
  /* derived */
  --dnp-grants-card: oklch(0.995 0.003 84);
  --dnp-grants-side: color-mix(in oklch, var(--dnp-grants-bg), var(--dnp-grants-ink) 3.5%);
  --dnp-grants-col: color-mix(in oklch, var(--dnp-grants-bg), var(--dnp-grants-ink) 4.5%);
  --dnp-grants-line: color-mix(in oklch, var(--dnp-grants-ink) 13%, transparent);
  --dnp-grants-hair: color-mix(in oklch, var(--dnp-grants-ink) 7%, transparent);
  --dnp-grants-mute: color-mix(in oklch, var(--dnp-grants-ink) 66%, var(--dnp-grants-bg));
  --dnp-grants-faint: color-mix(in oklch, var(--dnp-grants-ink) 45%, var(--dnp-grants-bg));
  --dnp-grants-warm: oklch(0.72 0.14 72);
  --dnp-grants-good: oklch(0.55 0.12 155);
  --dnp-grants-sans: system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  --dnp-grants-mono: ui-monospace, "SF Mono", Menlo, Consolas, monospace;
  --dnp-grants-out: cubic-bezier(.2, .9, .25, 1);
  --dnp-grants-spring: linear(0, .07 2.5%, .26 6.5%, .58 12%, .88 18%, 1.04 24%, 1.08 29%, 1.05 36%, 1.01 46%, .997 60%, 1);
  color-scheme: light;
  border-radius: 14px;
  box-shadow: inset 0 0 0 1px var(--dnp-grants-line);
}
.dnp-grants__app { height: 100%; display: grid; grid-template-columns: 196px minmax(0, 1fr); grid-template-rows: auto minmax(0, 1fr); grid-template-areas: "nav top" "nav main"; }
.dnp-grants__nav { grid-area: nav; min-height: 0; display: flex; flex-direction: column; gap: 18px; padding: 18px 12px 14px; background: var(--dnp-grants-side); border-right: 1px solid var(--dnp-grants-line); }
.dnp-grants__brand {
  display: flex; align-items: center; gap: 10px; padding: 0 4px;
  & .dnp-grants__logo { width: 32px; height: 32px; border-radius: 8px; display: grid; place-items: center; background: var(--dnp-grants-accent); color: var(--dnp-grants-card); flex: none; }
  & .dnp-grants__brandtx { display: grid; line-height: 1.15; }
  & b { font-size: 14px; font-weight: 750; letter-spacing: -.02em; }
  & small { font-size: 11px; color: var(--dnp-grants-faint); }
}
.dnp-grants__navlist { display: grid; gap: 2px; }
.dnp-grants__navbtn {
  position: relative; width: 100%; height: 36px; display: flex; align-items: center; gap: 10px; padding: 0 10px; border-radius: 8px;
  color: var(--dnp-grants-mute); font-weight: 560; transition: background-color .15s, color .15s;
  & span { flex: 1; text-align: left; white-space: nowrap; }
  & .dnp-grants__navn { font: normal 700 10.5px var(--dnp-grants-mono); color: var(--dnp-grants-card); background: var(--dnp-grants-hot); padding: 1px 6px; border-radius: 99px; }
  &:hover { color: var(--dnp-grants-ink); background: var(--dnp-grants-hair); }
  &[aria-current="page"] { color: var(--dnp-grants-ink); background: var(--dnp-grants-card); box-shadow: 0 0 0 1px var(--dnp-grants-line), 0 2px 6px -4px color-mix(in oklch, var(--dnp-grants-ink) 40%, transparent); }
  &[aria-current="page"] .dnp-grants__i { color: var(--dnp-grants-accent); }
}
.dnp-grants__navfoot {
  margin-top: auto; display: grid; gap: 3px; padding: 12px; border-radius: 10px; background: var(--dnp-grants-card); box-shadow: 0 0 0 1px var(--dnp-grants-line);
  & .dnp-grants__kl { font-size: 10.5px; }
  & b { font-size: 18px; font-weight: 760; letter-spacing: -.03em; font-variant-numeric: tabular-nums; }
  & small { font-size: 11px; color: var(--dnp-grants-mute); font-variant-numeric: tabular-nums; }
}
.dnp-grants__fybar { height: 6px; border-radius: 6px; background: var(--dnp-grants-hair); overflow: hidden; & i { display: block; height: 100%; border-radius: inherit; background: var(--dnp-grants-good); width: calc(var(--dnp-grants-p) * 100%); transition: --dnp-grants-p 1s var(--dnp-grants-out); } }
.dnp-grants__top { grid-area: top; display: flex; align-items: end; justify-content: space-between; flex-wrap: wrap; gap: 10px 18px; padding: 16px 20px 12px; }
.dnp-grants__eyebrow { font: 600 10.5px var(--dnp-grants-mono); letter-spacing: .06em; text-transform: uppercase; color: var(--dnp-grants-accent); }
.dnp-grants__title h2 { font-size: clamp(20px, 2.3cqi, 26px); font-weight: 780; letter-spacing: -.035em; line-height: 1.1; margin-top: 2px; }
.dnp-grants__chips {
  display: flex; flex-wrap: wrap; gap: 4px;
  & button { height: 28px; padding: 0 10px; border-radius: 6px; font-size: 12px; font-weight: 600; color: var(--dnp-grants-mute); box-shadow: inset 0 0 0 1px var(--dnp-grants-line); background: transparent; display: inline-flex; align-items: center; gap: 6px; transition: background-color .15s, color .15s, box-shadow .15s; }
  & .dnp-grants__ck { width: 13px; height: 13px; border-radius: 3.5px; box-shadow: inset 0 0 0 1.5px currentColor; fill: none; stroke: var(--dnp-grants-card); stroke-width: 1.9; stroke-linecap: round; stroke-linejoin: round; transition: background-color .15s, box-shadow .15s; }
  & .dnp-grants__ck path { stroke-dasharray: 10; stroke-dashoffset: 10; transition: stroke-dashoffset .3s var(--dnp-grants-out); }
  & button[aria-pressed="true"] { color: var(--dnp-grants-ink); background: var(--dnp-grants-card); }
  & button[aria-pressed="true"] .dnp-grants__ck { background: var(--dnp-grants-accent); box-shadow: none; }
  & button[aria-pressed="true"] .dnp-grants__ck path { stroke-dashoffset: 0; }
  & button:hover { color: var(--dnp-grants-ink); }
}
.dnp-grants__main { grid-area: main; min-height: 0; padding: 0 20px 16px; }
.dnp-grants__view { height: 100%; transition: opacity .3s, translate .45s var(--dnp-grants-out); @starting-style { opacity: 0; translate: 0 8px; } }
.dnp-grants__panel { min-height: 0; min-width: 0; display: flex; flex-direction: column; border-radius: 12px; background: var(--dnp-grants-card); box-shadow: 0 0 0 1px var(--dnp-grants-line); }
.dnp-grants__ph { display: flex; align-items: center; flex-wrap: wrap; gap: 8px 12px; padding: 12px 14px 8px; & h3 { font-size: 13px; font-weight: 700; margin-right: auto; } & h3 small { font-weight: 450; color: var(--dnp-grants-faint); margin-left: 6px; } }
.dnp-grants__kl { font: 600 10.5px var(--dnp-grants-sans); letter-spacing: .06em; text-transform: uppercase; color: var(--dnp-grants-faint); }
/* board */
.dnp-grants__bv { display: grid; grid-template-rows: auto minmax(0, 1fr); gap: 12px; }
.dnp-grants__kpis { display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); gap: 10px; }
.dnp-grants__kpi { display: grid; gap: 1px; padding: 10px 13px; border-radius: 10px; background: var(--dnp-grants-card); box-shadow: 0 0 0 1px var(--dnp-grants-line); min-width: 0; }
.dnp-grants__kv { font-size: clamp(17px, 2cqi, 22px); font-weight: 760; letter-spacing: -.03em; font-variant-numeric: tabular-nums; line-height: 1.2; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.dnp-grants__ks { font-size: 11.5px; color: var(--dnp-grants-mute); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; font-variant-numeric: tabular-nums; }
.dnp-grants__kpi--hot .dnp-grants__kv { color: var(--dnp-grants-hot); }
.dnp-grants__board { display: grid; grid-template-columns: repeat(5, minmax(158px, 1fr)); gap: 10px; min-height: 0; padding-bottom: 2px; }
.dnp-grants__col {
  display: flex; flex-direction: column; min-height: 0; border-radius: 12px; background: var(--dnp-grants-col);
  box-shadow: inset 0 0 0 1px var(--dnp-grants-hair);
}
.dnp-grants__colh {
  padding: 10px 11px 8px; display: grid; gap: 2px;
  & .dnp-grants__cn { display: flex; align-items: center; gap: 6px; font-size: 12px; font-weight: 700; }
  & .dnp-grants__cn i { width: 8px; height: 8px; border-radius: 50%; background: var(--c); }
  & .dnp-grants__cn em { margin-left: auto; font: normal 650 11px var(--dnp-grants-mono); color: var(--dnp-grants-mute); font-variant-numeric: tabular-nums; }
  & small { font-size: 11px; color: var(--dnp-grants-faint); font-variant-numeric: tabular-nums; }
}
.dnp-grants__cards { flex: 1; min-height: 0; overflow: auto; scrollbar-width: none; padding: 2px 8px 10px; display: flex; flex-direction: column; gap: 8px; & > * { flex: none; } }
.dnp-grants__card {
  position: relative; width: 100%; text-align: left; display: grid; grid-template-columns: minmax(0, 1fr); gap: 4px; padding: 10px 10px 9px;
  border-radius: 9px; background: var(--dnp-grants-card);
  box-shadow: 0 0 0 1px var(--dnp-grants-line), 0 1px 2px color-mix(in oklch, var(--dnp-grants-ink) 8%, transparent);
  transition: box-shadow .18s, translate .18s var(--dnp-grants-out);
  overflow: hidden;
  &:hover { box-shadow: 0 0 0 1px color-mix(in oklch, var(--dnp-grants-accent) 45%, transparent), 0 6px 14px -8px color-mix(in oklch, var(--dnp-grants-ink) 40%, transparent); translate: 0 -1px; }
  &[aria-expanded="true"] { box-shadow: 0 0 0 2px var(--dnp-grants-accent); }
  & .dnp-grants__cf { font-size: 12.5px; font-weight: 700; line-height: 1.25; letter-spacing: -.01em; padding-right: 22px; }
  & .dnp-grants__ct { font-size: 11.5px; color: var(--dnp-grants-mute); line-height: 1.3; }
  & .dnp-grants__cm { display: flex; align-items: center; gap: 6px; margin-top: 4px; min-width: 0; }
  & .dnp-grants__cm .dnp-grants__due { min-width: 0; overflow: hidden; text-overflow: ellipsis; }
  & .dnp-grants__amt { font: 650 12px var(--dnp-grants-mono); font-variant-numeric: tabular-nums; letter-spacing: -.02em; }
  & .dnp-grants__who { position: absolute; top: 9px; right: 9px; width: 20px; height: 20px; border-radius: 50%; display: grid; place-items: center; font-size: 9px; font-weight: 750; background: var(--dnp-grants-ink); color: var(--dnp-grants-card); }
  & .dnp-grants__ready { height: 3px; border-radius: 3px; background: var(--dnp-grants-hair); overflow: hidden; margin-top: 3px; }
  & .dnp-grants__ready i { display: block; height: 100%; width: calc(var(--r) * 100%); background: var(--dnp-grants-accent); border-radius: inherit; transition: width .5s var(--dnp-grants-out); }
  & .dnp-grants__stamp { margin-left: auto; rotate: -6deg; padding: 1px 6px; border: 1.5px solid currentColor; border-radius: 4px; font: 800 9px var(--dnp-grants-mono); letter-spacing: .14em; text-transform: uppercase; color: var(--dnp-grants-good); opacity: .85; }
  &.is-moved { animation: dnp-grants-land .9s var(--dnp-grants-out); }
}
@keyframes dnp-grants-land { 0% { box-shadow: 0 0 0 3px color-mix(in oklch, var(--dnp-grants-accent) 60%, transparent); } 100% { box-shadow: 0 0 0 1px var(--dnp-grants-line); } }
.dnp-grants__due {
  display: inline-flex; align-items: center; gap: 4px; height: 19px; padding: 0 6px; border-radius: 5px;
  font: 600 10.5px var(--dnp-grants-sans); font-variant-numeric: tabular-nums; white-space: nowrap;
  background: var(--dnp-grants-hair); color: var(--dnp-grants-mute);
  &.is-hot { background: color-mix(in oklch, var(--dnp-grants-hot) 13%, transparent); color: color-mix(in oklch, var(--dnp-grants-hot), var(--dnp-grants-ink) 20%); }
  &.is-warm { background: color-mix(in oklch, var(--dnp-grants-warm) 20%, transparent); color: color-mix(in oklch, var(--dnp-grants-warm), var(--dnp-grants-ink) 45%); }
  &.is-done { background: color-mix(in oklch, var(--dnp-grants-good) 13%, transparent); color: var(--dnp-grants-good); }
}
.dnp-grants__board.is-intro .dnp-grants__card { animation: dnp-grants-rise .55s var(--dnp-grants-out) both; animation-delay: calc(var(--i) * 40ms + 60ms); }
@keyframes dnp-grants-rise { from { opacity: 0; translate: 0 10px; } }
/* runway */
.dnp-grants__rv { display: flex; flex-direction: column; }
.dnp-grants__runp { flex: 1; }
.dnp-grants__seg {
  display: inline-flex; padding: 2px; gap: 2px; border-radius: 8px; background: var(--dnp-grants-side); box-shadow: inset 0 0 0 1px var(--dnp-grants-hair);
  & button { height: 24px; padding: 0 10px; border-radius: 6px; font-size: 11.5px; font-weight: 620; color: var(--dnp-grants-mute); transition: background-color .15s, color .15s; }
  & button[aria-checked="true"] { background: var(--dnp-grants-card); color: var(--dnp-grants-ink); box-shadow: 0 0 0 1px var(--dnp-grants-line); }
}
.dnp-grants__rkey { display: flex; flex-wrap: wrap; gap: 4px 16px; padding: 0 14px 8px; font-size: 11px; color: var(--dnp-grants-faint);
  & span { display: inline-flex; align-items: center; gap: 6px; }
  & i { display: inline-block; }
  & i.w { width: 18px; height: 8px; border-radius: 3px; background: color-mix(in oklch, var(--dnp-grants-accent) 22%, transparent); box-shadow: inset 0 0 0 1px color-mix(in oklch, var(--dnp-grants-accent) 45%, transparent); }
  & i.d { width: 9px; height: 9px; rotate: 45deg; background: var(--dnp-grants-accent); }
  & i.o { width: 9px; height: 9px; border-radius: 50%; box-shadow: inset 0 0 0 2px var(--dnp-grants-accent); }
  & i.r { width: 9px; height: 9px; border-radius: 2px; box-shadow: inset 0 0 0 2px var(--dnp-grants-good); }
}
.dnp-grants__runwrap { flex: 1; min-height: 0; margin: 0 4px 6px; }
.dnp-grants__run { position: relative; min-width: 640px; padding: 0 10px 8px; --lab: 196px; }
.dnp-grants__axis {
  position: sticky; top: 0; z-index: 3; height: 26px; margin-left: var(--lab); background: var(--dnp-grants-card); box-shadow: 0 1px 0 var(--dnp-grants-line);
  & span { position: absolute; top: 6px; left: calc(var(--x) * 100%); width: calc(var(--w) * 100%); height: 20px; padding-top: 3px; text-align: center; font: 600 10.5px var(--dnp-grants-mono); color: var(--dnp-grants-faint); text-transform: uppercase; letter-spacing: .04em; border-left: 1px solid var(--dnp-grants-line); }
}
.dnp-grants__grid { position: absolute; inset: 26px 10px 0 calc(var(--lab) + 10px); pointer-events: none;
  & i { position: absolute; top: 0; bottom: 0; left: calc(var(--x) * 100%); width: 1px; background: var(--dnp-grants-hair); }
  & b { position: absolute; top: -26px; bottom: 0; left: calc(var(--x) * 100%); width: 2px; translate: -1px 0; background: var(--dnp-grants-hot); z-index: 4; }
  & b::after { content: "Today"; position: absolute; top: 2px; left: 4px; font: 700 10px var(--dnp-grants-sans); color: var(--dnp-grants-hot); background: var(--dnp-grants-card); padding: 0 3px; }
}
.dnp-grants__rows { position: relative; display: grid; }
.dnp-grants__row {
  position: relative; display: grid; grid-template-columns: var(--lab) minmax(0, 1fr); align-items: center; height: 34px; width: 100%; text-align: left;
  border-radius: 7px; transition: background-color .12s;
  &:hover { background: color-mix(in oklch, var(--dnp-grants-accent) 6%, transparent); }
  & .dnp-grants__rl { display: grid; line-height: 1.2; padding: 0 10px 0 8px; min-width: 0; }
  & .dnp-grants__rl b { font-size: 12px; font-weight: 650; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
  & .dnp-grants__rl small { font-size: 10.5px; color: var(--dnp-grants-faint); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; font-variant-numeric: tabular-nums; }
  & .dnp-grants__track { position: relative; height: 100%; }
  & .dnp-grants__win { position: absolute; top: 11px; height: 12px; left: calc(var(--a) * 100%); width: calc((var(--b) - var(--a)) * 100%); border-radius: 4px; background: color-mix(in oklch, var(--c) 20%, transparent); box-shadow: inset 0 0 0 1px color-mix(in oklch, var(--c) 45%, transparent); transform-origin: left; }
  & .dnp-grants__dm { position: absolute; top: 12px; width: 10px; height: 10px; left: calc(var(--b) * 100%); translate: -5px 0; rotate: 45deg; background: var(--c); border-radius: 1.5px; }
  & .dnp-grants__dc { position: absolute; top: 12px; width: 10px; height: 10px; left: calc(var(--o) * 100%); translate: -5px 0; border-radius: 50%; box-shadow: inset 0 0 0 2px var(--c); background: var(--dnp-grants-card); }
  & .dnp-grants__dr { position: absolute; top: 12px; width: 10px; height: 10px; left: calc(var(--o) * 100%); translate: -5px 0; border-radius: 2px; box-shadow: inset 0 0 0 2px var(--dnp-grants-good); background: var(--dnp-grants-card); }
  & .dnp-grants__dl { position: absolute; top: 9px; left: calc(var(--b) * 100%); padding-left: 10px; font: 600 10.5px var(--dnp-grants-sans); color: var(--dnp-grants-mute); white-space: nowrap; font-variant-numeric: tabular-nums; }
}
.dnp-grants__rows.is-intro .dnp-grants__win { animation: dnp-grants-win .7s var(--dnp-grants-out) both; animation-delay: calc(var(--i) * 35ms + 100ms); }
@keyframes dnp-grants-win { from { scale: 0 1; } }
/* funders */
.dnp-grants__fv { display: grid; grid-template-columns: minmax(0, 1fr) 300px; gap: 12px; }
.dnp-grants__ftp { overflow: hidden; }
.dnp-grants__tw { flex: 1; min-height: 0; }
.dnp-grants__table {
  font-size: 12.5px; font-variant-numeric: tabular-nums;
  & th { position: sticky; top: 0; z-index: 1; background: var(--dnp-grants-card); text-align: left; padding: 10px 12px 8px; box-shadow: inset 0 -1px 0 var(--dnp-grants-line); font: 600 10.5px var(--dnp-grants-sans); letter-spacing: .06em; text-transform: uppercase; color: var(--dnp-grants-faint); white-space: nowrap; }
  & th button { display: inline-flex; align-items: center; gap: 5px; color: inherit; font: inherit; letter-spacing: inherit; text-transform: inherit; }
  & th button::after { content: ""; width: 7px; height: 7px; border-right: 1.5px solid currentColor; border-bottom: 1.5px solid currentColor; rotate: 45deg; translate: 0 -2px; opacity: .25; }
  & th[aria-sort="ascending"] button, & th[aria-sort="descending"] button { color: var(--dnp-grants-accent); }
  & th[aria-sort="descending"] button::after { opacity: 1; }
  & th[aria-sort="ascending"] button::after { opacity: 1; rotate: -135deg; translate: 0 2px; }
  & .dnp-grants__num { text-align: right; }
  & th.dnp-grants__num button { flex-direction: row-reverse; }
  & td { padding: 9px 12px; border-bottom: 1px solid var(--dnp-grants-hair); white-space: nowrap; }
  & tbody tr { cursor: pointer; transition: background-color .12s; }
  & tbody tr:hover { background: color-mix(in oklch, var(--dnp-grants-accent) 5%, transparent); }
  & tbody tr[aria-selected="true"] { background: color-mix(in oklch, var(--dnp-grants-accent) 10%, transparent); }
  & tbody tr[aria-selected="true"] td:first-child { box-shadow: inset 3px 0 0 var(--dnp-grants-accent); }
  & .dnp-grants__fn b { display: block; font-weight: 650; }
  & .dnp-grants__fn small { color: var(--dnp-grants-faint); font-size: 11px; }
  & .dnp-grants__rate { display: inline-flex; align-items: center; gap: 6px; }
  & .dnp-grants__rate i { width: 34px; height: 5px; border-radius: 3px; background: linear-gradient(to right, var(--dnp-grants-good) calc(var(--r) * 100%), var(--dnp-grants-hair) 0); }
