  $('[data-s=awarded]').textContent = S.on.size === 4 ? Math.round(awSum / TARGET * 100) + '% of ' + kgbp(TARGET) + ' target' : aw.length + ' awards in selected programmes';
  const next = open.filter(g => g.stage < 3).sort((a, b) => a.due - b.due)[0];
