};

/* ================================================================ board */
const board = $('.dnp-grants__board');
const cardHtml = (g, i) => '<button type="button" class="dnp-grants__card" data-id="' + g.id + '" aria-expanded="' + (S.open === g.id) + '" aria-haspopup="dialog" style="--i:' + i + '">' +
