  '<span class="dnp-grants__who" title="' + TEAM[g.who] + '">' + g.who + '</span><span class="dnp-grants__cm"><span class="dnp-grants__amt">' + kgbp(g.ask) + '</span>' + (g.stage === 4 ? '<span class="dnp-grants__stamp">Awarded</span>' : '<span class="dnp-grants__due ' + urgency(g) + '">' + dueLabel(g) + '</span>') + '</span>' +
