  board.innerHTML = STAGES.map((s, si) => {
    const cs = v.filter(g => g.stage === si).sort((a, b) => a.due - b.due), tot = sum(cs.map(g => g.ask));
    return '<section class="dnp-grants__col" role="listitem" aria-label="' + s.n + ', ' + cs.length + ' bids"><header class="dnp-grants__colh"><span class="dnp-grants__cn" style="--c:color-mix(in oklch, var(--dnp-grants-accent) ' + (25 + si * 18) + '%, var(--dnp-grants-bg))"><i></i>' + s.n + '<em>' + cs.length + '</em></span><small>' + kgbp(tot) + (si < 4 ? ' · ' + kgbp(tot * s.p) + ' weighted' : ' secured') + '</small></header>' +
      '<div class="dnp-grants__cards">' + cs.map((g, k) => cardHtml(g, si * 2 + k)).join('') + '</div></section>';
