      const isMoved = +c.dataset.id === moved;
      c.animate([{ transform: 'translate(' + dx + 'px,' + dy + 'px)' + (isMoved ? ' rotate(-2deg) scale(1.04)' : ''), zIndex: isMoved ? 5 : 1 }, { transform: 'none', zIndex: isMoved ? 5 : 1 }], { duration: isMoved ? 720 : 480, easing: isMoved ? 'cubic-bezier(.3,1.25,.4,1)' : EASE });
    });
  }
  if (moved != null) { const c = board.querySelector('[data-id="' + moved + '"]'); if (c) { c.classList.add('is-moved'); c.scrollIntoView({ block: 'nearest', inline: 'nearest' }); } }
};
board.addEventListener('click', e => { const c = e.target.closest('.dnp-grants__card'); if (c) openDrawer(+c.dataset.id, c); });

/* ================================================================ drawer */
const drawer = $('.dnp-grants__drawer'), scrim = $('.dnp-grants__scrim'), dbody = $('.dnp-grants__dbody');
const openDrawer = (id, trigger) => {
