    '<div class="dnp-grants__facts"><div class="dnp-grants__fact"><span>Ask</span><b>' + gbp(g.ask) + '</b></div><div class="dnp-grants__fact"><span>' + (g.stage === 4 ? 'Secured' : 'Weighted (' + Math.round(st.p * 100) + '%)') + '</span><b>' + gbp(g.ask * st.p) + '</b></div>' +
    '<div class="dnp-grants__fact"><span>' + (g.stage === 4 ? 'Report due' : g.stage === 3 ? 'Decision expected' : 'Deadline') + '</span><b>' + dstr(g.due) + '</b></div><div class="dnp-grants__fact"><span>' + (g.stage === 4 ? 'Awarded' : g.stage === 3 ? 'Submitted' : 'Decision by') + '</span><b>' + dstr(g.decide) + '</b></div></div>' +
    (g.stage < 3 ? '<h4><span>Requirements</span><span>' + ready + ' of 5</span></h4><div class="dnp-grants__checks">' + REQ.map((r, k) => '<label><input type="checkbox" data-k="' + k + '"' + (g.checks[k] ? ' checked' : '') + '><span>' + r + '</span></label>').join('') + '</div>' +
