root.addEventListener('keydown', e => {
  if (e.key === 'Escape') { if (!drawer.hidden) { e.preventDefault(); closeDrawer(); } untip(); return; }
  if (e.key === 'Tab' && !drawer.hidden) {
    const f = $$('button:not(:disabled), input:not(:disabled)', drawer).filter(x => x.offsetParent);
    if (!f.length) return;
