/* ================================================================ runway */
const run = $('.dnp-grants__run');
radios($('.dnp-grants__runp .dnp-grants__seg'), v => { S.runSort = v; renderRunway(false, true); });
const xf = off => clamp((TODAY + off * DAY - WIN0) / (WIN1 - WIN0), 0, 1);
const renderRunway = (intro, flipIt) => {
