    '<div class="dnp-grants__rows' + (intro ? ' is-intro' : '') + '">' + v.map((g, i) => {
      const c = g.stage === 4 ? 'var(--dnp-grants-good)' : urgency(g) === 'is-hot' ? 'var(--dnp-grants-hot)' : urgency(g) === 'is-warm' ? 'var(--dnp-grants-warm)' : 'var(--dnp-grants-accent)';
      let marks;
      if (g.stage === 4) marks = '<span class="dnp-grants__dr" style="--o:' + xf(g.due).toFixed(4) + '"></span><span class="dnp-grants__dl" style="--b:' + xf(g.due).toFixed(4) + '">Report ' + dstr(g.due) + '</span>';
      else if (g.stage === 3) marks = '<span class="dnp-grants__win" style="--a:' + xf(g.decide).toFixed(4) + ';--b:' + xf(g.due).toFixed(4) + '"></span><span class="dnp-grants__dc" style="--o:' + xf(g.due).toFixed(4) + '"></span><span class="dnp-grants__dl" style="--b:' + xf(g.due).toFixed(4) + '">Decision ' + dstr(g.due) + '</span>';
      else marks = '<span class="dnp-grants__win" style="--a:' + xf(g.due - PREP[g.stage]).toFixed(4) + ';--b:' + xf(g.due).toFixed(4) + '"></span><span class="dnp-grants__dm" style="--b:' + xf(g.due).toFixed(4) + '"></span><span class="dnp-grants__dc" style="--o:' + xf(g.decide).toFixed(4) + '"></span><span class="dnp-grants__dl" style="--b:' + xf(g.due).toFixed(4) + '">' + dstr(g.due) + ' · ' + g.due + 'd</span>';
      return '<button type="button" class="dnp-grants__row" data-id="' + g.id + '" style="--c:' + c + ';--i:' + i + '" aria-haspopup="dialog"><span class="dnp-grants__rl"><b>' + esc(g.funder) + '</b><small>' + kgbp(g.ask) + ' · ' + STAGES[g.stage].n + '</small></span><span class="dnp-grants__track">' + marks + '</span></button>';
    }).join('') + '</div>';
  if (before && !RM) $$('.dnp-grants__row', run).forEach(r => { const t0 = before.get(r.dataset.id); if (t0 == null) return; const dy = t0 - r.getBoundingClientRect().top; if (Math.abs(dy) > 1) r.animate([{ transform: 'translateY(' + dy + 'px)' }, { transform: 'none' }], { duration: 520, easing: EASE, delay: Math.min(200, Math.abs(dy) / 6) }); });
};
run.addEventListener('click', e => { const r = e.target.closest('.dnp-grants__row'); if (r) openDrawer(+r.dataset.id, r); });
run.addEventListener('pointermove', e => {
  const r = e.target.closest('.dnp-grants__row'); if (!r) { untip(); return; }
  const g = grants[+r.dataset.id], st = STAGES[g.stage];
  tip('<span class="dnp-grants__tt">' + esc(g.funder) + '</span><span class="dnp-grants__trow"><span>' + esc(g.title) + '</span></span><span class="dnp-grants__trow"><span>Ask</span><b>' + gbp(g.ask) + '</b></span><span class="dnp-grants__trow"><span>Stage</span><b>' + st.n + '</b></span><span class="dnp-grants__trow"><span>' + (g.stage === 4 ? 'Report due' : g.stage === 3 ? 'Decision' : 'Deadline') + '</span><b>' + dstr(g.due) + (g.stage < 4 ? ' (' + g.due + ' days)' : '') + '</b></span>', e.clientX, e.clientY);
});
run.addEventListener('pointerleave', untip);

/* ================================================================ funders */
const R = rng(906);
const FY = [2021, 2022, 2023, 2024, 2025, 2026];
const funders = [...new Set(grants.map(g => g.funder))].map((name, i) => {
  const mine = grants.filter(g => g.funder === name);
  const hist = FY.map((y, k) => k === 5 ? sum(mine.filter(g => g.stage === 4).map(g => g.ask)) : R() < .45 ? Math.round((4 + R() * 30)) * 1000 : 0);
  const won = hist.filter(Boolean).length, apps = won + Math.floor(R() * 3) + (won ? 0 : 1);
  return { i, name, hist, won, apps, lead: mine[0].who, since: 2014 + Math.floor(R() * 10) };
});
const fstats = f => { const mine = grants.filter(g => g.funder === f.name); return { total: sum(f.hist), rate: f.won / f.apps, open: sum(mine.filter(g => g.stage < 4).map(g => g.ask)), mine }; };
const ftb = $('.dnp-grants__table tbody'), fd = $('.dnp-grants__fd');
const renderFunders = intro => {
  const key = { name: f => f.name.replace(/^The /, ''), total: f => fstats(f).total, rate: f => fstats(f).rate, open: f => fstats(f).open }[S.fsort.k];
  const list = funders.filter(f => fstats(f).mine.some(g => S.on.has(g.prog))).sort((a, b) => { const x = key(a), y = key(b); return (x < y ? -1 : x > y ? 1 : a.i - b.i) * S.fsort.dir; });
  if (S.fsel == null || !list.some(f => f.i === S.fsel)) S.fsel = list.length ? list[0].i : null;
  ftb.innerHTML = list.map(f => { const s = fstats(f); return '<tr data-f="' + f.i + '" tabindex="' + (f.i === S.fsel ? 0 : -1) + '" aria-selected="' + (f.i === S.fsel) + '"><td class="dnp-grants__fn"><b>' + esc(f.name) + '</b><small>Funding us since ' + f.since + '</small></td><td class="dnp-grants__num"><b>' + gbp(s.total) + '</b></td><td class="dnp-grants__num dnp-grants__hide-s"><span class="dnp-grants__rate" style="--r:' + s.rate.toFixed(3) + '"><i></i>' + f.won + '/' + f.apps + '</span></td><td class="dnp-grants__num dnp-grants__hide-m">' + (s.open ? gbp(s.open) : '—') + '</td><td class="dnp-grants__hide-m"><span class="dnp-grants__lead" title="' + TEAM[f.lead] + '">' + f.lead + '</span></td></tr>'; }).join('');
  $$('.dnp-grants__table th[aria-sort]').forEach(th => th.setAttribute('aria-sort', th.querySelector('button').dataset.sort === S.fsort.k ? (S.fsort.dir > 0 ? 'ascending' : 'descending') : 'none'));
  renderFunder(intro);
