  const s = fstats(f);
  fd.innerHTML = '<p class="dnp-grants__kl">Funder history</p><h3>' + esc(f.name) + '</h3><p class="dnp-grants__fdk">' + f.won + ' awards from ' + f.apps + ' applications · lead ' + TEAM[f.lead] + '</p><div class="dnp-grants__hist' + (intro ? ' is-intro' : '') + '"><svg role="img" aria-label="Awards by year"></svg></div>' +
    '<dl><dt>Awarded since 2021</dt><dd>' + gbp(s.total) + '</dd><dt>Open asks</dt><dd>' + (s.open ? gbp(s.open) : '—') + '</dd><dt>Best year</dt><dd>' + (Math.max(...f.hist) ? FY[f.hist.indexOf(Math.max(...f.hist))] + ' · ' + gbp(Math.max(...f.hist)) : '—') + '</dd></dl>' +
    s.mine.map(g => '<p class="dnp-grants__note"><b>' + esc(g.title) + '</b> · ' + STAGES[g.stage].n + ' · ' + gbp(g.ask) + '</p>').join('');
  const box = $('.dnp-grants__hist', fd), svg = $('svg', box), [W, H] = measure(box);
