    f.hist.map((v, k) => '<g><rect class="b' + (k === 5 ? ' is-cur' : '') + '" style="--i:' + k + '" x="' + (5 + k * bw + bw * .2) + '" y="' + y(v) + '" width="' + bw * .6 + '" height="' + Math.max(0, H - 18 - y(v)) + '" rx="3" data-k="' + k + '"/>' + (v ? '<text class="v" x="' + (5 + k * bw + bw / 2) + '" y="' + (y(v) - 5) + '" text-anchor="middle">' + kgbp(v) + '</text>' : '') + '<text x="' + (5 + k * bw + bw / 2) + '" y="' + (H - 4) + '" text-anchor="middle">' + (k === 5 ? 'FY26' : 'FY' + String(FY[k]).slice(2)) + '</text></g>').join('');
