ftb.addEventListener('click', e => { const tr = e.target.closest('tr[data-f]'); if (tr && tr.getAttribute('aria-selected') !== 'true') selF(tr); });
const selF = (tr, focus) => { S.fsel = +tr.dataset.f; $$('tr', ftb).forEach(r => { const on = r === tr; r.setAttribute('aria-selected', String(on)); r.tabIndex = on ? 0 : -1; }); if (focus) tr.focus(); renderFunder(false); };
ftb.addEventListener('keydown', e => {
  const tr = e.target.closest('tr[data-f]'); if (!tr) return;
