});
$('.dnp-grants__table thead').addEventListener('click', e => {
  const b = e.target.closest('[data-sort]'); if (!b) return;
  const k = b.dataset.sort; S.fsort = S.fsort.k === k ? { k, dir: -S.fsort.dir } : { k, dir: k === 'name' ? 1 : -1 };
  const before = new Map($$('tr', ftb).map(r => [r.dataset.f, r.getBoundingClientRect().top]));
  renderFunders(false);
  if (!RM) $$('tr', ftb).forEach(r => { const t0 = before.get(r.dataset.f); if (t0 == null) return; const dy = t0 - r.getBoundingClientRect().top; if (Math.abs(dy) > 1) r.animate([{ transform: 'translateY(' + dy + 'px)' }, { transform: 'none' }], { duration: 460, easing: EASE }); });
});
fd.addEventListener('pointermove', e => {
  const b = e.target.closest('rect.b'); if (!b) { untip(); return; }
  const f = funders[S.fsel], k = +b.dataset.k;
  tip('<span class="dnp-grants__tt">' + esc(f.name) + ' · FY ' + FY[k] + '–' + String(FY[k] + 1).slice(2) + '</span><b>' + (f.hist[k] ? gbp(f.hist[k]) + ' awarded' : 'No award') + '</b>', e.clientX, e.clientY);
