  accent-color: var(--dnp-funds-accent);
  -webkit-font-smoothing: antialiased;
  & *, & *::before, & *::after { box-sizing: border-box; }
  & :where(h1, h2, h3, h4, p, ol, ul, dl, dd, figure) { margin: 0; padding: 0; }
  & :where(ol, ul) { list-style: none; }
  & :where(h1, h2, h3, h4) { text-wrap: balance; font-weight: 650; }
  & :where(p) { text-wrap: pretty; }
  & :where(button, input, select) { font: inherit; color: inherit; letter-spacing: inherit; }
  & :where(button) { background: none; border: 0; padding: 0; cursor: pointer; -webkit-tap-highlight-color: transparent; }
  & :where(button:disabled, [aria-disabled="true"]) { cursor: not-allowed; }
  & :where(svg) { display: block; overflow: visible; }
  & :where(table) { border-collapse: collapse; width: 100%; }
  & :focus-visible { outline: 2px solid var(--dnp-funds-focus, var(--dnp-funds-accent)); outline-offset: 2px; }
  & [hidden] { display: none !important; }
  & .dnp-funds__i { width: 18px; height: 18px; flex: none; fill: none; stroke: currentColor; stroke-width: 1.75; stroke-linecap: round; stroke-linejoin: round; }
  & .dnp-funds__sr { position: absolute; width: 1px; height: 1px; overflow: hidden; clip-path: inset(50%); white-space: nowrap; }
}
.dnp-funds__scroll {
  overflow: auto;
  overscroll-behavior: contain;
  scrollbar-width: thin;
  scrollbar-color: color-mix(in oklch, var(--dnp-funds-ink) 22%, transparent) transparent;
  &::-webkit-scrollbar { width: 8px; height: 8px; }
  &::-webkit-scrollbar-thumb { background: color-mix(in oklch, var(--dnp-funds-ink) 20%, transparent); border-radius: 8px; border: 2px solid transparent; background-clip: padding-box; }
}
.dnp-funds__tip {
  position: absolute; left: 0; top: 0; z-index: 40;
  pointer-events: none;
  min-width: 128px; max-width: 260px;
  padding: 8px 10px;
  border-radius: 10px;
  background: var(--dnp-funds-tipbg, color-mix(in oklch, var(--dnp-funds-ink) 94%, var(--dnp-funds-bg)));
  color: var(--dnp-funds-tipink, var(--dnp-funds-bg));
  font-size: 12px; line-height: 1.4;
  font-variant-numeric: tabular-nums;
  box-shadow: 0 10px 28px -10px oklch(0 0 0 / .45);
  opacity: 0; scale: .96;
  transition: opacity .14s, scale .2s cubic-bezier(.22, 1, .36, 1);
  &.is-on { opacity: 1; scale: 1; }
  & b { font-weight: 650; }
  & .dnp-funds__tt { display: block; font-size: 11px; letter-spacing: .04em; text-transform: uppercase; opacity: .7; margin-bottom: 3px; }
  & .dnp-funds__trow { display: flex; justify-content: space-between; gap: 14px; align-items: baseline; }
  & .dnp-funds__trow i { display: inline-block; width: 8px; height: 8px; border-radius: 2px; margin-right: 6px; background: var(--c); }
}
.dnp-funds__toast {
  position: absolute; left: 50%; bottom: 18px; z-index: 50;
  max-width: min(440px, calc(100% - 32px));
  padding: 10px 16px;
  border-radius: 12px;
  background: var(--dnp-funds-tipbg, color-mix(in oklch, var(--dnp-funds-ink) 94%, var(--dnp-funds-bg)));
  color: var(--dnp-funds-tipink, var(--dnp-funds-bg));
  font-size: 12.5px; font-weight: 550;
  box-shadow: 0 16px 40px -14px oklch(0 0 0 / .5);
  pointer-events: none;
  translate: -50% 16px; opacity: 0;
  transition: translate .45s cubic-bezier(.22, 1, .36, 1), opacity .25s;
  &.is-on { translate: -50% 0; opacity: 1; }
}

@property --dnp-funds-cov { syntax: "<number>"; inherits: true; initial-value: 0; }
.dnp-funds {
  /* re-theme with these four */
  --dnp-funds-bg: oklch(0.205 0.008 70);
  --dnp-funds-ink: oklch(0.94 0.01 80);
  --dnp-funds-accent: oklch(0.73 0.12 55);
  --dnp-funds-free: oklch(0.75 0.13 162);
  /* derived */
  --dnp-funds-cap: oklch(0.7 0.085 15);
  --dnp-funds-card: color-mix(in oklch, var(--dnp-funds-bg), var(--dnp-funds-ink) 4.5%);
  --dnp-funds-raise: color-mix(in oklch, var(--dnp-funds-bg), var(--dnp-funds-ink) 9%);
  --dnp-funds-side: color-mix(in oklch, var(--dnp-funds-bg), black 25%);
  --dnp-funds-line: color-mix(in oklch, var(--dnp-funds-ink) 13%, transparent);
  --dnp-funds-hair: color-mix(in oklch, var(--dnp-funds-ink) 7%, transparent);
  --dnp-funds-mute: color-mix(in oklch, var(--dnp-funds-ink) 68%, var(--dnp-funds-bg));
  --dnp-funds-faint: color-mix(in oklch, var(--dnp-funds-ink) 45%, var(--dnp-funds-bg));
  --dnp-funds-node: color-mix(in oklch, var(--dnp-funds-ink) 55%, var(--dnp-funds-bg));
  --dnp-funds-sans: system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  --dnp-funds-mono: ui-monospace, "SF Mono", Menlo, Consolas, monospace;
  --dnp-funds-out: cubic-bezier(.22, 1, .36, 1);
  --dnp-funds-tipbg: oklch(0.96 0.012 80);
  --dnp-funds-tipink: oklch(0.22 0.01 70);
  color-scheme: dark;
  border-radius: 16px;
  box-shadow: inset 0 0 0 1px var(--dnp-funds-line);
}
.dnp-funds__app { height: 100%; display: grid; grid-template-columns: 204px minmax(0, 1fr); grid-template-rows: auto minmax(0, 1fr); grid-template-areas: "nav top" "nav main"; }
.dnp-funds__nav { grid-area: nav; min-height: 0; display: flex; flex-direction: column; gap: 20px; padding: 18px 12px; background: var(--dnp-funds-side); border-right: 1px solid var(--dnp-funds-hair); }
.dnp-funds__brand {
  display: flex; align-items: center; gap: 10px; padding: 0 4px;
  & .dnp-funds__logo { width: 32px; height: 32px; border-radius: 9px; display: grid; place-items: center; background: var(--dnp-funds-accent); color: var(--dnp-funds-bg); flex: none; }
  & .dnp-funds__brandtx { display: grid; line-height: 1.15; min-width: 0; }
  & b { font-weight: 720; font-size: 14px; letter-spacing: -.01em; }
  & small { font-size: 11px; color: var(--dnp-funds-faint); white-space: nowrap; }
}
.dnp-funds__navlist { display: grid; gap: 2px; }
.dnp-funds__navbtn {
  width: 100%; height: 36px; display: flex; align-items: center; gap: 10px; padding: 0 10px; border-radius: 8px; color: var(--dnp-funds-mute); font-weight: 560; position: relative;
  transition: color .15s, background-color .15s;
  & span { flex: 1; text-align: left; white-space: nowrap; }
  & .dnp-funds__navn { font: normal 700 10px var(--dnp-funds-mono); padding: 1px 6px; border-radius: 99px; background: var(--dnp-funds-free); color: var(--dnp-funds-bg); }
  & .dnp-funds__navn:empty { display: none; }
  &:hover { color: var(--dnp-funds-ink); background: var(--dnp-funds-hair); }
  &[aria-current="page"] { color: var(--dnp-funds-ink); background: var(--dnp-funds-raise); }
  &[aria-current="page"] .dnp-funds__i { color: var(--dnp-funds-accent); }
}
.dnp-funds__navnote { margin-top: auto; padding: 0 4px; font-size: 11.5px; color: var(--dnp-funds-faint); line-height: 1.5; }
.dnp-funds__top { grid-area: top; display: flex; align-items: center; justify-content: space-between; gap: 10px 20px; flex-wrap: wrap; padding: 18px 22px 12px; }
.dnp-funds__title h2 { font-size: clamp(19px, 2.2cqi, 25px); font-weight: 680; letter-spacing: -.025em; line-height: 1.1; }
.dnp-funds__sub { color: var(--dnp-funds-faint); font-size: 12.5px; margin-top: 3px; }
.dnp-funds__seg {
  display: inline-flex; padding: 3px; gap: 2px; border-radius: 10px; background: var(--dnp-funds-side); box-shadow: inset 0 0 0 1px var(--dnp-funds-hair);
  & button { height: 27px; padding: 0 11px; border-radius: 7px; font-size: 12px; font-weight: 600; color: var(--dnp-funds-mute); white-space: nowrap; font-variant-numeric: tabular-nums; transition: color .15s, background-color .15s; }
  & button:hover { color: var(--dnp-funds-ink); }
  & button[aria-checked="true"] { background: var(--dnp-funds-raise); color: var(--dnp-funds-ink); box-shadow: inset 0 0 0 1px var(--dnp-funds-line), inset 0 -2px 0 var(--dnp-funds-accent); }
}
.dnp-funds__seg--sm button { height: 24px; padding: 0 9px; font-size: 11.5px; }
.dnp-funds__main { grid-area: main; min-height: 0; padding: 0 22px 18px; }
.dnp-funds__view { height: 100%; transition: opacity .35s, translate .5s var(--dnp-funds-out); @starting-style { opacity: 0; translate: 0 8px; } }
.dnp-funds__panel { min-height: 0; min-width: 0; display: flex; flex-direction: column; border-radius: 14px; background: var(--dnp-funds-card); box-shadow: inset 0 0 0 1px var(--dnp-funds-hair); }
.dnp-funds__ph { display: flex; align-items: center; flex-wrap: wrap; gap: 6px 12px; padding: 12px 14px 6px; & h3 { font-size: 13px; font-weight: 650; margin-right: auto; } & h3 small { font-weight: 450; color: var(--dnp-funds-faint); margin-left: 6px; font-size: 12px; } }
.dnp-funds__hint { font-size: 11px; color: var(--dnp-funds-faint); }
.dnp-funds__flv { display: grid; gap: 12px; grid-template-columns: minmax(0, 1fr) 248px; grid-template-rows: auto minmax(0, 1fr); grid-template-areas: "kpis kpis" "sk brk"; }
.dnp-funds__kpis { grid-area: kpis; display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); gap: 12px; }
.dnp-funds__kpi {
  display: grid; gap: 1px; padding: 11px 14px; border-radius: 12px; background: var(--dnp-funds-card); box-shadow: inset 0 0 0 1px var(--dnp-funds-hair); min-width: 0;
  & .dnp-funds__kl { font-size: 11px; color: var(--dnp-funds-faint); font-weight: 600; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
  & .dnp-funds__kv { font-size: clamp(18px, 2.2cqi, 25px); font-weight: 680; letter-spacing: -.03em; font-variant-numeric: tabular-nums; line-height: 1.2; }
  & .dnp-funds__ks { font-size: 11.5px; color: var(--dnp-funds-mute); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; font-variant-numeric: tabular-nums; }
  & .dnp-funds__ks i { display: inline-block; width: 8px; height: 8px; border-radius: 2px; margin-right: 5px; background: var(--c); }
}
.dnp-funds__sk { grid-area: sk; }
.dnp-funds__plot { position: relative; flex: 1; min-height: 200px; margin: 0 8px 8px; }
.dnp-funds__svg {
  position: absolute; inset: 0; width: 100%; height: 100%;
  & .dnp-funds__rib { fill: var(--c); fill-opacity: .42; transition: d .8s var(--dnp-funds-out), fill-opacity .2s; cursor: crosshair; }
  & .dnp-funds__rib.is-hot { fill-opacity: .82; }
  &.is-focus .dnp-funds__rib:not(.is-hot) { fill-opacity: .1; }
  & .dnp-funds__node { cursor: pointer; outline: none; }
  & .dnp-funds__nr { fill: var(--c, var(--dnp-funds-node)); rx: 3px; transition: y .8s var(--dnp-funds-out), height .8s var(--dnp-funds-out); }
  & .dnp-funds__node:hover .dnp-funds__nr, & .dnp-funds__node:focus-visible .dnp-funds__nr { filter: brightness(1.25); }
  & .dnp-funds__node[aria-pressed="true"] .dnp-funds__nr { stroke: var(--dnp-funds-ink); stroke-width: 2; }
  & .dnp-funds__node:focus-visible .dnp-funds__nr { stroke: var(--dnp-funds-ink); stroke-width: 2; stroke-dasharray: 3 2; }
  & .dnp-funds__lab { transition: transform .8s var(--dnp-funds-out); }
  & .dnp-funds__lbg { fill: color-mix(in oklch, var(--dnp-funds-card) 88%, transparent); stroke: var(--dnp-funds-hair); rx: 5px; }
  & .dnp-funds__node text { fill: var(--dnp-funds-ink); font: 600 11.5px var(--dnp-funds-sans); }
  & .dnp-funds__node text tspan + tspan { fill: var(--dnp-funds-faint); font: 500 10.5px var(--dnp-funds-sans); font-variant-numeric: tabular-nums; }
  & .dnp-funds__colh { fill: var(--dnp-funds-faint); font: 600 10px var(--dnp-funds-sans); letter-spacing: .08em; text-transform: uppercase; }
  & .dnp-funds__ribs.is-intro { animation: dnp-funds-reveal 1.3s var(--dnp-funds-out) both .15s; }
  & .dnp-funds__nodes.is-intro .dnp-funds__node { animation: dnp-funds-fade .5s var(--dnp-funds-out) both; animation-delay: calc(var(--i) * 40ms); }
}
@keyframes dnp-funds-reveal { from { clip-path: inset(0 100% 0 0); } to { clip-path: inset(0 0 0 0); } }
@keyframes dnp-funds-fade { from { opacity: 0; } }
.dnp-funds__brk {
  grid-area: brk; padding: 14px; gap: 12px; overflow: auto;
  & .dnp-funds__bk { font-size: 10.5px; font-weight: 650; letter-spacing: .07em; text-transform: uppercase; color: var(--dnp-funds-faint); }
  & h4 { font-size: 15px; font-weight: 680; letter-spacing: -.01em; display: flex; align-items: center; gap: 8px; }
  & h4 i { width: 10px; height: 10px; border-radius: 3px; background: var(--c, var(--dnp-funds-node)); }
  & .dnp-funds__big { font-size: 24px; font-weight: 700; letter-spacing: -.03em; font-variant-numeric: tabular-nums; }
  & .dnp-funds__big small { font-size: 12px; font-weight: 500; color: var(--dnp-funds-faint); letter-spacing: 0; margin-left: 6px; }
  & ol { display: grid; gap: 9px; }
  & li { display: grid; grid-template-columns: minmax(0, 1fr) auto; gap: 3px 8px; font-size: 12px; }
  & li span { white-space: nowrap; overflow: hidden; text-overflow: ellipsis; color: var(--dnp-funds-mute); }
  & li b { font-weight: 650; font-variant-numeric: tabular-nums; }
  & li i { grid-column: 1 / -1; height: 5px; border-radius: 3px; background: var(--dnp-funds-hair); overflow: hidden; }
  & li i::after { content: ""; display: block; height: 100%; width: calc(var(--w) * 100%); background: var(--c); border-radius: inherit; transition: width .6s var(--dnp-funds-out); }
  & .dnp-funds__bnote { font-size: 11.5px; color: var(--dnp-funds-faint); text-wrap: pretty; }
  & .dnp-funds__unpin { align-self: start; font-size: 11.5px; font-weight: 600; color: var(--dnp-funds-accent); }
}
/* funds table */
.dnp-funds__fdv { display: flex; flex-direction: column; }
.dnp-funds__ftp { flex: 1; }
.dnp-funds__tw { flex: 1; min-height: 0; margin: 0 6px 6px; }
.dnp-funds__table {
  font-size: 12.5px; font-variant-numeric: tabular-nums;
  & th { position: sticky; top: 0; z-index: 1; background: var(--dnp-funds-card); text-align: left; padding: 8px 10px; font-size: 11px; font-weight: 600; color: var(--dnp-funds-faint); box-shadow: inset 0 -1px 0 var(--dnp-funds-line); white-space: nowrap; }
  & th button { color: inherit; font-weight: inherit; display: inline-flex; align-items: center; gap: 5px; }
  & th button::after { content: ""; border: 4px solid transparent; border-top-color: currentColor; translate: 0 2px; opacity: .3; }
  & th[aria-sort="descending"] button, & th[aria-sort="ascending"] button { color: var(--dnp-funds-ink); }
  & th[aria-sort="descending"] button::after { opacity: 1; border-top-color: var(--dnp-funds-accent); }
  & th[aria-sort="ascending"] button::after { opacity: 1; border-top-color: transparent; border-bottom-color: var(--dnp-funds-accent); translate: 0 -2px; }
  & .dnp-funds__num { text-align: right; }
  & th.dnp-funds__num button { flex-direction: row-reverse; }
  & td { padding: 9px 10px; border-bottom: 1px solid var(--dnp-funds-hair); white-space: nowrap; vertical-align: middle; }
  & tbody tr { transition: background-color .15s; }
  & tbody tr:hover { background: var(--dnp-funds-hair); }
  & tbody tr.is-released { color: var(--dnp-funds-faint); }
  & tfoot td { font-weight: 700; border-bottom: 0; box-shadow: inset 0 1px 0 var(--dnp-funds-line); position: sticky; bottom: 0; background: var(--dnp-funds-card); }
  & .dnp-funds__fn b { display: block; font-weight: 620; }
  & .dnp-funds__fn small { color: var(--dnp-funds-faint); font-size: 11px; }
  & .dnp-funds__spent { display: grid; grid-template-columns: 90px auto; align-items: center; gap: 8px; color: var(--dnp-funds-mute); font-size: 11.5px; }
  & .dnp-funds__spent i { height: 6px; border-radius: 3px; background: var(--dnp-funds-hair); overflow: hidden; }
  & .dnp-funds__spent i::after { content: ""; display: block; height: 100%; width: calc(var(--w) * 100%); background: var(--c); border-radius: inherit; }
  & .dnp-funds__st { display: inline-block; font-size: 10.5px; font-weight: 650; padding: 1px 7px; border-radius: 99px; margin-top: 2px; background: var(--dnp-funds-hair); color: var(--dnp-funds-mute); }
  & .dnp-funds__st.is-ok { background: color-mix(in oklch, var(--dnp-funds-free) 20%, transparent); color: var(--dnp-funds-free); }
  & .dnp-funds__st.is-warn { background: color-mix(in oklch, var(--dnp-funds-cap) 22%, transparent); color: var(--dnp-funds-cap); }
  & .dnp-funds__ends { display: grid; line-height: 1.3; }
  & .dnp-funds__ends small { font-size: 11px; color: var(--dnp-funds-faint); }
}
.dnp-funds__rel {
  height: 28px; padding: 0 11px; border-radius: 7px; font-size: 11.5px; font-weight: 650; white-space: nowrap;
  background: color-mix(in oklch, var(--dnp-funds-free) 18%, transparent); color: var(--dnp-funds-free); box-shadow: inset 0 0 0 1px color-mix(in oklch, var(--dnp-funds-free) 40%, transparent);
  transition: background-color .15s;
  &:hover:not(:disabled) { background: color-mix(in oklch, var(--dnp-funds-free) 30%, transparent); }
  &:disabled { background: transparent; color: var(--dnp-funds-faint); box-shadow: inset 0 0 0 1px var(--dnp-funds-hair); }
}
/* reserves */
.dnp-funds__rsv { display: grid; gap: 12px; grid-template-columns: minmax(0, 1fr) 250px; }
.dnp-funds__rkey { display: flex; align-items: center; gap: 6px; font-size: 11px; color: var(--dnp-funds-faint); flex-wrap: wrap;
  & i { display: inline-block; width: 14px; height: 8px; border-radius: 2px; margin-left: 8px; }
  & i.l { height: 2.5px; background: var(--dnp-funds-free); }
  & i.b { background: color-mix(in oklch, var(--dnp-funds-accent) 22%, transparent); box-shadow: inset 0 0 0 1px color-mix(in oklch, var(--dnp-funds-accent) 50%, transparent); }
  & i.p { background: var(--dnp-funds-hair); }
}
.dnp-funds__rsvg {
  position: absolute; inset: 0; width: 100%; height: 100%; cursor: crosshair;
  & text { font: 10.5px var(--dnp-funds-sans); fill: var(--dnp-funds-faint); font-variant-numeric: tabular-nums; }
  & .dnp-funds__gl { stroke: var(--dnp-funds-hair); }
  & .dnp-funds__band { fill: color-mix(in oklch, var(--dnp-funds-accent) 13%, transparent); stroke: color-mix(in oklch, var(--dnp-funds-accent) 45%, transparent); stroke-dasharray: 3 3; }
  & .dnp-funds__bandtx { fill: var(--dnp-funds-accent); font-weight: 600; }
  & .dnp-funds__pshade { fill: var(--dnp-funds-hair); transition: x .6s var(--dnp-funds-out), width .6s var(--dnp-funds-out); }
  & .dnp-funds__rl { fill: none; stroke: var(--dnp-funds-free); stroke-width: 2.4; stroke-linejoin: round; }
  & .dnp-funds__ra { fill: color-mix(in oklch, var(--dnp-funds-free) 12%, transparent); }
  & .dnp-funds__xh { stroke: var(--dnp-funds-ink); stroke-opacity: .4; opacity: 0; }
  & .dnp-funds__xh.is-on, & .dnp-funds__dot.is-on { opacity: 1; }
  & .dnp-funds__dot { fill: var(--dnp-funds-bg); stroke: var(--dnp-funds-free); stroke-width: 2; opacity: 0; }
  & .dnp-funds__rel-pt { fill: var(--dnp-funds-free); }
  &.is-intro .dnp-funds__rl { stroke-dasharray: 1; animation: dnp-funds-draw 1.2s var(--dnp-funds-out) both; }
  &.is-intro .dnp-funds__ra { animation: dnp-funds-fade 1s .4s both; }
  &:focus-visible { outline-offset: -2px; border-radius: 8px; }
}
@keyframes dnp-funds-draw { from { stroke-dashoffset: 1; } to { stroke-dashoffset: 0; } }
.dnp-funds__cover { align-items: stretch; }
.dnp-funds__gauge {
  position: relative; margin: 6px 18px 0;
  & svg { width: 100%; height: auto; }
  & path { fill: none; stroke-width: 14; stroke-linecap: round; }
  & .t { stroke: var(--dnp-funds-hair); }
  & .band { stroke: color-mix(in oklch, var(--dnp-funds-accent) 35%, transparent); stroke-linecap: butt; stroke-dasharray: 25 100; stroke-dashoffset: -25; }
  & .v { stroke: var(--dnp-funds-free); stroke-width: 6; stroke-dasharray: calc(var(--dnp-funds-cov) / 12 * 100) 100; transition: --dnp-funds-cov 1.4s var(--dnp-funds-out); }
  & .ticks text { font: 9px var(--dnp-funds-sans); fill: var(--dnp-funds-faint); text-anchor: middle; }
}
.dnp-funds__gv { position: absolute; left: 0; right: 0; bottom: 4px; text-align: center; display: grid; line-height: 1.05;
  & b { font-size: 30px; font-weight: 700; letter-spacing: -.04em; font-variant-numeric: tabular-nums; }
