.dnp-volunteers {
  /* re-theme with these four */
  --dnp-volunteers-bg: oklch(0.988 0.004 150);
  --dnp-volunteers-ink: oklch(0.27 0.022 250);
  --dnp-volunteers-accent: oklch(0.69 0.17 48);
  --dnp-volunteers-heat: oklch(0.55 0.14 152);
  /* derived */
  --dnp-volunteers-empty: color-mix(in oklch, var(--dnp-volunteers-ink) 6%, var(--dnp-volunteers-bg));
  --dnp-volunteers-card: oklch(1 0 none);
  --dnp-volunteers-side: color-mix(in oklch, var(--dnp-volunteers-bg), var(--dnp-volunteers-heat) 5%);
  --dnp-volunteers-line: color-mix(in oklch, var(--dnp-volunteers-ink) 12%, transparent);
  --dnp-volunteers-hair: color-mix(in oklch, var(--dnp-volunteers-ink) 6.5%, transparent);
  --dnp-volunteers-mute: color-mix(in oklch, var(--dnp-volunteers-ink) 64%, var(--dnp-volunteers-bg));
  --dnp-volunteers-faint: color-mix(in oklch, var(--dnp-volunteers-ink) 44%, var(--dnp-volunteers-bg));
  --dnp-volunteers-r0: var(--dnp-volunteers-heat);
  --dnp-volunteers-r1: var(--dnp-volunteers-accent);
  --dnp-volunteers-r2: oklch(0.55 0.11 245);
  --dnp-volunteers-r3: oklch(0.6 0.06 300);
  --dnp-volunteers-r4: oklch(0.72 0.14 95);
  --dnp-volunteers-sans: system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  --dnp-volunteers-mono: ui-monospace, "SF Mono", Menlo, Consolas, monospace;
  --dnp-volunteers-out: cubic-bezier(.22, 1, .36, 1);
  --dnp-volunteers-pop: cubic-bezier(.34, 1.56, .64, 1);
  color-scheme: light;
  border-radius: 18px;
  box-shadow: inset 0 0 0 1px var(--dnp-volunteers-line);
}
.dnp-volunteers__app { height: 100%; display: grid; grid-template-columns: 200px minmax(0, 1fr); grid-template-rows: auto minmax(0, 1fr); grid-template-areas: "nav top" "nav main"; }
