.dnp-volunteers__dows { grid-column: 1; grid-row: 2; display: grid; grid-template-rows: repeat(7, var(--cell)); row-gap: 3px; font-size: 10px; color: var(--dnp-volunteers-faint); align-items: center; }
.dnp-volunteers__grid {
  grid-column: 2; grid-row: 2; display: grid; grid-auto-flow: column; grid-template-rows: repeat(7, var(--cell)); grid-auto-columns: var(--cell); gap: 3px;
  & i {
    --q: 0; border-radius: 3px; cursor: pointer;
