    box-shadow: inset 0 0 0 1px color-mix(in oklch, var(--dnp-volunteers-ink) 5%, transparent);
    transition: background-color .45s var(--dnp-volunteers-out), scale .2s var(--dnp-volunteers-pop), box-shadow .15s;
  }
  & i:hover { scale: 1.35; z-index: 1; box-shadow: 0 0 0 1.5px var(--dnp-volunteers-ink); }
