  tip('<span class="dnp-volunteers__tt">' + dlong(d) + '</span><span class="dnp-volunteers__trow"><span>Hours</span><b>' + hrs(sum(by)) + '</b></span><span class="dnp-volunteers__trow"><span>Volunteers</span><b>' + new Set(ss.map(s => s.v)).size + '</b></span>' + by.map((h, i) => h ? '<span class="dnp-volunteers__trow"><span><i style="--c:' + rc(i) + '"></i>' + ROLES[i].n + '</span><b>' + hrs(h) + ' h</b></span>' : '').join(''), e.clientX, e.clientY);
});
grid.addEventListener('pointerleave', untip);

/* ================================================================ day log */
const dayp = $('.dnp-volunteers__dayp');
const renderDay = () => {
  const ss = dayIdx[S.sel].filter(s => S.on.has(s.role)).slice().sort((a, b) => a.role - b.role || b.h - a.h);
  const H = sum(ss.map(s => s.h));
  dayp.innerHTML = '<p class="dnp-volunteers__dk">Day log</p><h4>' + dlong(S.sel) + '</h4><p class="dnp-volunteers__dsum">' + (ss.length ? hrs(H) + ' hours · ' + new Set(ss.map(s => s.v)).size + ' volunteers · worth £' + NF.format(Math.round(H * RATE)) : '') + '</p>' +
    (ss.length ? '<ul>' + ss.map(s => { const v = vols[s.v]; return '<li><span class="dnp-volunteers__av2" style="--c:' + rc(s.role) + '">' + v.ini + '</span><span>' + esc(v.name) + '<small>' + ROLES[s.role].n + '</small></span><b>' + hrs(s.h) + ' h</b></li>'; }).join('') + '</ul>' : '<p class="dnp-volunteers__none">No shifts logged for the selected roles.</p>');
};

/* ================================================================ monthly stacked bars */
const msvg = $('.dnp-volunteers__msvg'), mplot = $('.dnp-volunteers__monp .dnp-volunteers__plot');
$('.dnp-volunteers__rkey').innerHTML = ROLES.map((r, i) => '<li><i style="--c:' + rc(i) + '"></i>' + r.n + '</li>').join('');
let mState = null;
const renderMonths = intro => {
  const [W, H] = measure(mplot); if (!W || !H) return;
  msvg.setAttribute('viewBox', '0 0 ' + W + ' ' + H);
  const by = Array.from({ length: 12 }, () => ROLES.map(() => 0));
  live().forEach(s => { const x = dateOf(s.d), m = (x.getUTCFullYear() - 2025) * 12 + x.getUTCMonth() - 9; by[m][s.role] += s.h; });
  const ax = niceAxis(Math.max(...by.map(r => sum(r))), 3), m = { l: 36, r: 4, t: 8, b: 18 }, iw = W - m.l - m.r, ih = H - m.t - m.b, bw = iw / 12;
  const y = v => m.t + ih - v / ax.top * ih;
  let o = '';
  for (let v = 0; v <= ax.top + 1e-6; v += ax.step) o += '<line x1="' + m.l + '" x2="' + (W - m.r) + '" y1="' + y(v) + '" y2="' + y(v) + '"/><text x="' + (m.l - 6) + '" y="' + (y(v) + 3) + '" text-anchor="end">' + NF.format(v) + '</text>';
  by.forEach((r, k) => {
    let acc = 0; const x = m.l + k * bw;
    o += '<g data-m="' + k + '"><rect class="dnp-volunteers__mcol" x="' + x + '" y="' + m.t + '" width="' + bw + '" height="' + ih + '" rx="4"/>';
    r.forEach((h, ri) => { if (!h || !S.on.has(ri)) return; const y0 = y(acc), y1 = y(acc + h); acc += h; o += '<rect class="dnp-volunteers__seg2" style="--i:' + k + ';fill:' + rc(ri) + '" x="' + (x + bw * .2).toFixed(1) + '" y="' + y1.toFixed(1) + '" width="' + (bw * .6).toFixed(1) + '" height="' + Math.max(0, y0 - y1 - .6).toFixed(1) + '" rx="1.5"/>'; });
    const mo = (9 + k) % 12;
    o += '<text x="' + (x + bw / 2) + '" y="' + (H - 4) + '" text-anchor="middle">' + MON[mo].slice(0, 1) + (bw > 30 ? MON[mo].slice(1) : '') + '</text></g>';
  });
  msvg.innerHTML = o;
  msvg.classList.toggle('is-intro', !!intro);
  mState = { by };
};
msvg.addEventListener('pointermove', e => {
  const g = e.target.closest('g[data-m]'); $$('g.is-on', msvg).forEach(x => { if (x !== g) x.classList.remove('is-on'); });
  if (!g || !mState) { untip(); return; }
  g.classList.add('is-on');
  const k = +g.dataset.m, r = mState.by[k], mo = (9 + k) % 12;
  tip('<span class="dnp-volunteers__tt">' + MON[mo] + ' ' + (mo >= 9 ? 2025 : 2026) + '</span>' + r.map((h, i) => S.on.has(i) ? '<span class="dnp-volunteers__trow"><span><i style="--c:' + rc(i) + '"></i>' + ROLES[i].n + '</span><b>' + hrs(h) + ' h</b></span>' : '').join('') + '<span class="dnp-volunteers__trow" style="margin-top:3px"><span>Total</span><b>' + hrs(sum(r.filter((_, i) => S.on.has(i)))) + ' h</b></span>', e.clientX, e.clientY);
});
msvg.addEventListener('pointerleave', () => { untip(); $$('g.is-on', msvg).forEach(x => x.classList.remove('is-on')); });
onResize(mplot, () => renderMonths(false));

/* ================================================================ roster */
const tb = $('.dnp-volunteers__table tbody'), prof = $('.dnp-volunteers__prof');
const vstats = v => {
  const mine = shifts.filter(s => s.v === v.i && S.on.has(s.role));
  const last = mine.length ? mine[mine.length - 1].d : -1;
  return { hours: sum(mine.map(s => s.h)), shifts: mine.length, last, ago: last < 0 ? 999 : Math.round((TODAY - (D0 + last * DAY)) / DAY), mine };
};
const renderRoster = () => {
  const q = S.q.trim().toLowerCase();
  let list = vols.map(v => ({ v, s: vstats(v) })).filter(x => x.s.shifts && (!q || x.v.name.toLowerCase().includes(q)));
  const key = { name: x => x.v.name, hours: x => x.s.hours, shifts: x => x.s.shifts, last: x => -x.s.ago }[S.sort.k];
  list.sort((a, b) => { const x = key(a), y = key(b); return (x < y ? -1 : x > y ? 1 : a.v.i - b.v.i) * S.sort.dir; });
  if (S.vsel == null || !list.some(x => x.v.i === S.vsel)) S.vsel = list.length ? list[0].v.i : null;
  const mx = Math.max(1, ...list.map(x => x.s.hours));
  tb.innerHTML = list.map(({ v, s }) => '<tr data-v="' + v.i + '" tabindex="' + (v.i === S.vsel ? 0 : -1) + '" aria-selected="' + (v.i === S.vsel) + '"><td><span class="dnp-volunteers__who"><span class="dnp-volunteers__av2" style="--c:' + rc(v.role) + '">' + v.ini + '</span><b>' + esc(v.name) + '</b>' + (s.hours >= 250 ? '<span class="dnp-volunteers__badge">250+ h</span>' : s.hours >= 100 ? '<span class="dnp-volunteers__badge">100+ h</span>' : '') + '</span></td>' +
    '<td class="dnp-volunteers__hide-s"><span class="dnp-volunteers__role" style="--c:' + rc(v.role) + '"><i></i>' + ROLES[v.role].n + '</span></td><td class="dnp-volunteers__num"><span class="dnp-volunteers__hb" style="--w:' + (s.hours / mx).toFixed(3) + '"><i></i>' + hrs(s.hours) + '</span></td><td class="dnp-volunteers__num dnp-volunteers__hide-s">' + s.shifts + '</td><td class="dnp-volunteers__num"><span class="dnp-volunteers__ago' + (s.ago > 45 ? ' is-cold' : '') + '">' + (s.ago < 1 ? 'today' : s.ago === 1 ? 'yesterday' : s.ago + 'd ago') + '</span></td></tr>').join('') || '<tr><td colspan="5" style="text-align:center;padding:24px;color:var(--dnp-volunteers-faint)">Nobody matches “' + esc(S.q) + '”.</td></tr>';
  $$('.dnp-volunteers__table th[aria-sort]').forEach(th => th.setAttribute('aria-sort', th.querySelector('button').dataset.sort === S.sort.k ? (S.sort.dir > 0 ? 'ascending' : 'descending') : 'none'));
  renderProfile();
};
const renderProfile = () => {
  const v = vols[S.vsel];
  if (!v) { prof.innerHTML = '<p class="dnp-volunteers__lbl">No volunteer selected</p>'; return; }
  const s = vstats(v), months = Array.from({ length: 12 }, () => 0);
  s.mine.forEach(x => { const d = dateOf(x.d); months[(d.getUTCFullYear() - 2025) * 12 + d.getUTCMonth() - 9] += x.h; });
  const mx = Math.max(1, ...months), done = S.thanked.has(v.i);
  prof.innerHTML = '<div class="dnp-volunteers__ph2"><span class="dnp-volunteers__av3" style="--c:' + rc(v.role) + '">' + v.ini + '</span><div><h4>' + esc(v.name) + '</h4><small>' + ROLES[v.role].n + ' · usually ' + [...v.days].sort().map(d => DOW[d].slice(0, 3)).join(', ') + '</small></div></div>' +
    '<div class="dnp-volunteers__stats"><div><b>' + hrs(s.hours) + '</b><span>hours</span></div><div><b>' + s.shifts + '</b><span>shifts</span></div><div><b>£' + NF.format(Math.round(s.hours * RATE)) + '</b><span>value</span></div></div>' +
    '<p class="dnp-volunteers__lbl">Hours by month</p><div class="dnp-volunteers__bars">' + months.map((h, i) => '<i style="--h:' + (h / mx).toFixed(3) + ';--i:' + i + ';--c:' + rc(v.role) + '" title="' + MON[(9 + i) % 12] + ': ' + hrs(h) + ' h"></i>').join('') + '</div><div class="dnp-volunteers__bl">' + months.map((_, i) => '<span>' + MON[(9 + i) % 12][0] + '</span>').join('') + '</div>' +
    '<p class="dnp-volunteers__lbl">Usual days</p><div class="dnp-volunteers__days">' + DOW.map((d, i) => '<span class="' + (v.days.has(i) ? 'is-on' : '') + '">' + d.slice(0, 2) + '</span>').join('') + '</div>' +
    '<button type="button" class="dnp-volunteers__btn" data-act="thank"' + (done ? ' disabled title="A thank-you card is already on its way"' : '') + '>' + (done ? 'Thank-you card sent' : 'Send a thank-you card') + '</button>';
};
prof.addEventListener('click', e => {
  const b = e.target.closest('[data-act=thank]'); if (!b || b.disabled) return;
  const v = vols[S.vsel]; S.thanked.add(v.i); renderProfile();
  toast('Thank-you card for ' + v.name + ' added to Friday’s post');
});
const pickRow = (tr, focus) => { S.vsel = +tr.dataset.v; $$('tr[data-v]', tb).forEach(r => { const on = r === tr; r.setAttribute('aria-selected', String(on)); r.tabIndex = on ? 0 : -1; }); if (focus) tr.focus(); renderProfile(); };
tb.addEventListener('click', e => { const tr = e.target.closest('tr[data-v]'); if (tr && tr.getAttribute('aria-selected') !== 'true') pickRow(tr); });
tb.addEventListener('keydown', e => { const tr = e.target.closest('tr[data-v]'); if (!tr) return; const n = e.key === 'ArrowDown' ? tr.nextElementSibling : e.key === 'ArrowUp' ? tr.previousElementSibling : null; if (n) { e.preventDefault(); pickRow(n, true); } });
$('.dnp-volunteers__table thead').addEventListener('click', e => {
  const b = e.target.closest('[data-sort]'); if (!b) return;
  const k = b.dataset.sort; S.sort = S.sort.k === k ? { k, dir: -S.sort.dir } : { k, dir: k === 'name' ? 1 : -1 };
  const pos = new Map($$('tr[data-v]', tb).map(r => [r.dataset.v, r.getBoundingClientRect().top]));
  renderRoster();
  if (!RM) $$('tr[data-v]', tb).forEach(r => { const t0 = pos.get(r.dataset.v); if (t0 == null) return; const dy = t0 - r.getBoundingClientRect().top; if (Math.abs(dy) > 1) r.animate([{ transform: 'translateY(' + dy + 'px)' }, { transform: 'none' }], { duration: 460, easing: EASE }); });
});
$('.dnp-volunteers__search input').addEventListener('input', e => { S.q = e.target.value; renderRoster(); });

/* ================================================================ rota: next seven days from Fri 2 Oct */
const SLOTS = [
  { n: 'Growing', t: '9:30–12:30', role: 0, need: [3, 0, 0, 2, 3, 3, 2], days: [1, 0, 0, 1, 1, 1, 1] },
  { n: 'Pantry lunch', t: '11:00–15:00', role: 1, need: [4, 4, 0, 3, 4, 4, 4], days: [1, 1, 0, 1, 1, 1, 1] },
  { n: 'Delivery run', t: '13:00–16:00', role: 2, need: [2, 2, 0, 2, 2, 2, 2], days: [1, 1, 0, 1, 1, 1, 1] },
  { n: 'Front desk', t: '10:00–13:30', role: 3, need: [1, 1, 0, 1, 1, 1, 1], days: [1, 1, 0, 1, 1, 1, 1] },
  { n: 'Harvest supper', t: 'Sat 17:00–22:00', role: 4, need: [0, 6, 0, 0, 0, 0, 0], days: [0, 1, 0, 0, 0, 0, 0] }
];
const R2 = rng(42);
const rota = SLOTS.map(sl => sl.need.map((need, d) => {
  if (!sl.days[d]) return null;
  const cands = vols.filter(v => v.role === sl.role && v.end >= NDAYS).map(v => v.i);
  const have = Math.max(0, need - (R2() < .55 ? Math.ceil(R2() * 2) : 0));
  const people = []; while (people.length < Math.min(have, cands.length)) { const c = cands[Math.floor(R2() * cands.length)]; if (!people.includes(c)) people.push(c); }
  return { need, people, fresh: new Set() };
}));
const rotaEl = $('.dnp-volunteers__rota');
const dlabel = k => { const x = new Date(TODAY + k * DAY); return [DOW[(x.getUTCDay() + 6) % 7].slice(0, 3), x.getUTCDate() + ' ' + MON[x.getUTCMonth()]]; };
const gaps = () => sum(rota.map(r => sum(r.map(c => c ? Math.max(0, c.need - c.people.length) : 0))));
const renderRota = animateNew => {
  let o = '<div class="dnp-volunteers__rh" aria-hidden="true"></div>' + Array.from({ length: 7 }, (_, k) => { const [a, b] = dlabel(k); return '<div class="dnp-volunteers__rh' + (k === 0 ? ' is-today' : '') + '" role="columnheader">' + (k === 0 ? 'Today' : a) + '<small>' + b + '</small></div>'; }).join('');
  SLOTS.forEach((sl, si) => {
    o += '<div class="dnp-volunteers__rs" role="rowheader" style="--c:' + rc(sl.role) + '"><span><i></i>' + sl.n + '</span><small>' + sl.t + '</small></div>';
    rota[si].forEach((c, k) => {
      if (!c) { o += '<div class="dnp-volunteers__cell is-off" role="gridcell">Closed</div>'; return; }
      const open = c.need - c.people.length, [a, b] = dlabel(k);
      o += '<div class="dnp-volunteers__cell ' + (open > 0 ? 'is-gap' : 'is-full') + '" role="gridcell" aria-label="' + sl.n + ', ' + a + ' ' + b + ': ' + c.people.length + ' of ' + c.need + ' booked"><div class="dnp-volunteers__faces">' +
        c.people.map(p => '<span class="dnp-volunteers__face' + (c.fresh.has(p) && animateNew ? ' is-new' : '') + '" style="--c:' + rc(sl.role) + '" title="' + esc(vols[p].name) + '">' + vols[p].ini + '</span>').join('') +
        Array.from({ length: Math.max(0, open) }, () => '<span class="dnp-volunteers__slot" aria-hidden="true"></span>').join('') + '</div>' +
        '<div class="dnp-volunteers__cf"><span>' + c.people.length + '/' + c.need + '</span><button type="button" class="dnp-volunteers__fill" data-s="' + si + '" data-k="' + k + '"' + (open > 0 ? ' title="Ask a regular ' + ROLES[sl.role].n.toLowerCase() + ' volunteer to cover"' : ' disabled title="Shift is fully staffed"') + '>' + (open > 0 ? 'Fill' : 'Full') + '</button></div></div>';
    });
  });
  rotaEl.innerHTML = o;
  const g = gaps();
  $('.dnp-volunteers__gapsum').textContent = g ? g + ' open places to fill' : 'every shift is staffed';
  $('[data-n=gaps]').textContent = g || '';
  const af = $('[data-act=autofill]'); af.disabled = !g; af.title = g ? 'Ask regulars to cover all ' + g + ' open places' : 'Every shift is already staffed';
};
const fillOne = (si, k) => {
  const c = rota[si][k], sl = SLOTS[si]; if (!c || c.people.length >= c.need) return null;
  const busy = new Set(rota.flatMap(r => r[k] ? r[k].people : []));
  const dow = (new Date(TODAY + k * DAY).getUTCDay() + 6) % 7;
  const pool = vols.filter(v => v.end >= NDAYS && !busy.has(v.i));
  const pick = pool.find(v => v.role === sl.role && v.days.has(dow)) || pool.find(v => v.role === sl.role) || pool.find(v => v.days.has(dow)) || pool[0];
  if (!pick) return null;
  c.people.push(pick.i); c.fresh = new Set([pick.i]);
  return pick;
};
rotaEl.addEventListener('click', e => {
  const b = e.target.closest('.dnp-volunteers__fill'); if (!b || b.disabled) return;
  const si = +b.dataset.s, k = +b.dataset.k, p = fillOne(si, k);
  rota.forEach((r, i) => r.forEach((c, j) => { if (c && (i !== si || j !== k)) c.fresh = new Set(); }));
  renderRota(true);
  const nb = rotaEl.querySelector('.dnp-volunteers__fill[data-s="' + si + '"][data-k="' + k + '"]'); if (nb && !nb.disabled) nb.focus({ preventScroll: true });
  if (p) { const [a, d] = dlabel(k); toast('Asked ' + p.name + ' to cover ' + SLOTS[si].n.toLowerCase() + ' on ' + a + ' ' + d); }
});
$('[data-act=autofill]').addEventListener('click', e => {
  const btn = e.currentTarget; if (btn.disabled) return;
  const order = []; rota.forEach((r, si) => r.forEach((c, k) => { if (c) for (let n = c.people.length; n < c.need; n++) order.push([si, k]); }));
  btn.disabled = true; btn.textContent = 'Filling…';
  let i = 0;
  const step = () => {
    if (!root.isConnected) return;
    rota.forEach(r => r.forEach(c => { if (c) c.fresh = new Set(); }));
    const [si, k] = order[i++]; fillOne(si, k); renderRota(true);
    if (i < order.length) setTimeout(step, RM ? 0 : 70);
    else { btn.textContent = 'Fill every gap'; renderRota(false); toast(order.length + ' places filled · requests sent to ' + new Set(rota.flatMap(r => r.flatMap(c => c ? [...c.people] : []))).size + ' volunteers'); }
  };
  step();
});

/* ================================================================ refresh + mount */
root.addEventListener('keydown', e => { if (e.key === 'Escape') untip(); });
const refresh = () => {
  renderKpis(); renderHeat(false); renderDay();
  if (!$('[data-view=activity]').hidden) renderMonths(false);
  if (!$('[data-view=roster]').hidden) renderRoster();
};
renderKpis();
renderHeat(true);
renderDay();
renderRota(false);
requestAnimationFrame(() => { if (!root.isConnected) return; renderMonths(true); });

css:
.dnp-impact {
  width: 100%;
  height: var(--dnp-impact-h, 680px);
  container-type: inline-size;
  container-name: dnp-impact;
  position: relative;
  isolation: isolate;
  overflow: hidden;
  background: var(--dnp-impact-bg);
  color: var(--dnp-impact-ink);
  font: 13px/1.45 var(--dnp-impact-sans);
  accent-color: var(--dnp-impact-accent);
  -webkit-font-smoothing: antialiased;
  & *, & *::before, & *::after { box-sizing: border-box; }
  & :where(h1, h2, h3, h4, p, ol, ul, dl, dd, figure) { margin: 0; padding: 0; }
  & :where(ol, ul) { list-style: none; }
  & :where(h1, h2, h3, h4) { text-wrap: balance; font-weight: 650; }
  & :where(p) { text-wrap: pretty; }
  & :where(button, input, select) { font: inherit; color: inherit; letter-spacing: inherit; }
  & :where(button) { background: none; border: 0; padding: 0; cursor: pointer; -webkit-tap-highlight-color: transparent; }
  & :where(button:disabled, [aria-disabled="true"]) { cursor: not-allowed; }
  & :where(svg) { display: block; overflow: visible; }
  & :where(table) { border-collapse: collapse; width: 100%; }
  & :focus-visible { outline: 2px solid var(--dnp-impact-focus, var(--dnp-impact-accent)); outline-offset: 2px; }
  & [hidden] { display: none !important; }
  & .dnp-impact__i { width: 18px; height: 18px; flex: none; fill: none; stroke: currentColor; stroke-width: 1.75; stroke-linecap: round; stroke-linejoin: round; }
  & .dnp-impact__sr { position: absolute; width: 1px; height: 1px; overflow: hidden; clip-path: inset(50%); white-space: nowrap; }
}
.dnp-impact__scroll {
  overflow: auto;
  overscroll-behavior: contain;
  scrollbar-width: thin;
  scrollbar-color: color-mix(in oklch, var(--dnp-impact-ink) 22%, transparent) transparent;
  &::-webkit-scrollbar { width: 8px; height: 8px; }
  &::-webkit-scrollbar-thumb { background: color-mix(in oklch, var(--dnp-impact-ink) 20%, transparent); border-radius: 8px; border: 2px solid transparent; background-clip: padding-box; }
}
.dnp-impact__tip {
  position: absolute; left: 0; top: 0; z-index: 40;
  pointer-events: none;
  min-width: 128px; max-width: 260px;
  padding: 8px 10px;
  border-radius: 10px;
  background: var(--dnp-impact-tipbg, color-mix(in oklch, var(--dnp-impact-ink) 94%, var(--dnp-impact-bg)));
  color: var(--dnp-impact-tipink, var(--dnp-impact-bg));
  font-size: 12px; line-height: 1.4;
  font-variant-numeric: tabular-nums;
  box-shadow: 0 10px 28px -10px oklch(0 0 0 / .45);
  opacity: 0; scale: .96;
  transition: opacity .14s, scale .2s cubic-bezier(.22, 1, .36, 1);
  &.is-on { opacity: 1; scale: 1; }
  & b { font-weight: 650; }
  & .dnp-impact__tt { display: block; font-size: 11px; letter-spacing: .04em; text-transform: uppercase; opacity: .7; margin-bottom: 3px; }
  & .dnp-impact__trow { display: flex; justify-content: space-between; gap: 14px; align-items: baseline; }
  & .dnp-impact__trow i { display: inline-block; width: 8px; height: 8px; border-radius: 2px; margin-right: 6px; background: var(--c); }
}
.dnp-impact__toast {
  position: absolute; left: 50%; bottom: 18px; z-index: 50;
  max-width: min(440px, calc(100% - 32px));
  padding: 10px 16px;
  border-radius: 12px;
  background: var(--dnp-impact-tipbg, color-mix(in oklch, var(--dnp-impact-ink) 94%, var(--dnp-impact-bg)));
  color: var(--dnp-impact-tipink, var(--dnp-impact-bg));
  font-size: 12.5px; font-weight: 550;
  box-shadow: 0 16px 40px -14px oklch(0 0 0 / .5);
  pointer-events: none;
  translate: -50% 16px; opacity: 0;
  transition: translate .45s cubic-bezier(.22, 1, .36, 1), opacity .25s;
  &.is-on { translate: -50% 0; opacity: 1; }
