  const before = flipIt ? new Map($$('li', costs).map(li => [li.dataset.i, li.getBoundingClientRect().top])) : null;
  costs.innerHTML = rows.map((r, k) => '<li class="dnp-impact__cr" data-i="' + r.i + '" style="--i:' + k + '"><span class="dnp-impact__cn">' + r.n + '<small>' + r.ppl + ' referred · ' + gbp(r.cost) + ' budget</small></span><span class="dnp-impact__cb" style="--w:' + ((S.corder === 'cpo' ? r.cpo : r.out) / mx).toFixed(4) + '"><i></i></span><span class="dnp-impact__cv2">' + (S.corder === 'cpo' ? gbp(r.cpo) : r.out) + '<small>' + (S.corder === 'cpo' ? r.out + ' sustained outcomes' : gbp(r.cpo) + ' each') + '</small></span></li>').join('');
  if (before && !RM) $$('li', costs).forEach(li => { const t0 = before.get(li.dataset.i); if (t0 == null) return; const dy = t0 - li.getBoundingClientRect().top; if (Math.abs(dy) > 1) li.animate([{ transform: 'translateY(' + dy + 'px)' }, { transform: 'none' }], { duration: 560, easing: EASE }); });
  const all = sum(rows.map(r => r.cost)), outs = sum(rows.map(r => r.out));
  $('.dnp-impact__cnote').innerHTML = (S.q === 'all' ? 'Across all four pathways ' : 'For young people referred in ' + QN[+S.q] + ', a quarter of each budget, ') + '<b>' + gbp(all) + '</b> bought <b>' + outs + '</b> jobs or courses that lasted six months: <b>' + gbp(outs ? all / outs : 0) + '</b> each. Everyone referred is counted, including the ' + people.filter(p => p.s === 0 && inQ(p)).length + ' who never started.';
};
costs.addEventListener('pointermove', e => {
  const li = e.target.closest('li'); if (!li) { untip(); return; }
  const i = +li.dataset.i, ppl = people.filter(p => p.prog === i), by = STAGES.map((_, s) => ppl.filter(p => p.s === s).length);
  tip('<span class="dnp-impact__tt">' + PROGS[i] + '</span>' + by.map((n, s) => '<span class="dnp-impact__trow"><span><i style="--c:var(--dnp-impact-s' + s + ')"></i>' + STAGES[s] + '</span><b>' + n + '</b></span>').join(''), e.clientX, e.clientY);
});
costs.addEventListener('pointerleave', untip);

/* ================================================================ refresh + mount */
root.addEventListener('keydown', e => { if (e.key === 'Escape') untip(); });
const refresh = () => { renderLegend(); renderRates(); layout(true); if (!$('[data-view=ind]').hidden) renderQ(false); if (!$('[data-view=cost]').hidden) renderCost(true); };
renderLegend();
renderRates();
requestAnimationFrame(() => { if (!root.isConnected) return; sizeCanvas(!RM); if (!RM) enter(); });

css:
.dnp-match {
  width: 100%;
  height: var(--dnp-match-h, 680px);
  container-type: inline-size;
  container-name: dnp-match;
  position: relative;
  isolation: isolate;
  overflow: hidden;
  background: var(--dnp-match-bg);
  color: var(--dnp-match-ink);
  font: 13px/1.45 var(--dnp-match-sans);
  accent-color: var(--dnp-match-accent);
  -webkit-font-smoothing: antialiased;
  & *, & *::before, & *::after { box-sizing: border-box; }
  & :where(h1, h2, h3, h4, p, ol, ul, dl, dd, figure) { margin: 0; padding: 0; }
  & :where(ol, ul) { list-style: none; }
  & :where(h1, h2, h3, h4) { text-wrap: balance; font-weight: 650; }
  & :where(p) { text-wrap: pretty; }
  & :where(button, input, select) { font: inherit; color: inherit; letter-spacing: inherit; }
  & :where(button) { background: none; border: 0; padding: 0; cursor: pointer; -webkit-tap-highlight-color: transparent; }
  & :where(button:disabled, [aria-disabled="true"]) { cursor: not-allowed; }
  & :where(svg) { display: block; overflow: visible; }
  & :where(table) { border-collapse: collapse; width: 100%; }
  & :focus-visible { outline: 2px solid var(--dnp-match-focus, var(--dnp-match-accent)); outline-offset: 2px; }
  & [hidden] { display: none !important; }
  & .dnp-match__i { width: 18px; height: 18px; flex: none; fill: none; stroke: currentColor; stroke-width: 1.75; stroke-linecap: round; stroke-linejoin: round; }
  & .dnp-match__sr { position: absolute; width: 1px; height: 1px; overflow: hidden; clip-path: inset(50%); white-space: nowrap; }
}
.dnp-match__scroll {
  overflow: auto;
  overscroll-behavior: contain;
  scrollbar-width: thin;
  scrollbar-color: color-mix(in oklch, var(--dnp-match-ink) 22%, transparent) transparent;
  &::-webkit-scrollbar { width: 8px; height: 8px; }
  &::-webkit-scrollbar-thumb { background: color-mix(in oklch, var(--dnp-match-ink) 20%, transparent); border-radius: 8px; border: 2px solid transparent; background-clip: padding-box; }
}
.dnp-match__tip {
  position: absolute; left: 0; top: 0; z-index: 40;
  pointer-events: none;
  min-width: 128px; max-width: 260px;
  padding: 8px 10px;
  border-radius: 10px;
  background: var(--dnp-match-tipbg, color-mix(in oklch, var(--dnp-match-ink) 94%, var(--dnp-match-bg)));
  color: var(--dnp-match-tipink, var(--dnp-match-bg));
  font-size: 12px; line-height: 1.4;
  font-variant-numeric: tabular-nums;
  box-shadow: 0 10px 28px -10px oklch(0 0 0 / .45);
  opacity: 0; scale: .96;
  transition: opacity .14s, scale .2s cubic-bezier(.22, 1, .36, 1);
  &.is-on { opacity: 1; scale: 1; }
  & b { font-weight: 650; }
  & .dnp-match__tt { display: block; font-size: 11px; letter-spacing: .04em; text-transform: uppercase; opacity: .7; margin-bottom: 3px; }
  & .dnp-match__trow { display: flex; justify-content: space-between; gap: 14px; align-items: baseline; }
  & .dnp-match__trow i { display: inline-block; width: 8px; height: 8px; border-radius: 2px; margin-right: 6px; background: var(--c); }
}
.dnp-match__toast {
  position: absolute; left: 50%; bottom: 18px; z-index: 50;
  max-width: min(440px, calc(100% - 32px));
  padding: 10px 16px;
  border-radius: 12px;
  background: var(--dnp-match-tipbg, color-mix(in oklch, var(--dnp-match-ink) 94%, var(--dnp-match-bg)));
  color: var(--dnp-match-tipink, var(--dnp-match-bg));
  font-size: 12.5px; font-weight: 550;
  box-shadow: 0 16px 40px -14px oklch(0 0 0 / .5);
  pointer-events: none;
  translate: -50% 16px; opacity: 0;
  transition: translate .45s cubic-bezier(.22, 1, .36, 1), opacity .25s;
  &.is-on { translate: -50% 0; opacity: 1; }
}

@property --dnp-match-fill { syntax: "<number>"; inherits: true; initial-value: 0; }
.dnp-match {
  /* re-theme with these four */
  --dnp-match-bg: oklch(0.974 0.013 178);
  --dnp-match-ink: oklch(0.27 0.045 205);
  --dnp-match-accent: oklch(0.6 0.2 352);
  --dnp-match-match: oklch(0.63 0.11 196);
  /* derived */
  --dnp-match-card: oklch(0.998 0.004 178);
  --dnp-match-side: color-mix(in oklch, var(--dnp-match-bg), var(--dnp-match-match) 7%);
  --dnp-match-line: color-mix(in oklch, var(--dnp-match-ink) 13%, transparent);
  --dnp-match-hair: color-mix(in oklch, var(--dnp-match-ink) 7%, transparent);
  --dnp-match-mute: color-mix(in oklch, var(--dnp-match-ink) 65%, var(--dnp-match-bg));
  --dnp-match-faint: color-mix(in oklch, var(--dnp-match-ink) 45%, var(--dnp-match-bg));
  --dnp-match-ga1: var(--dnp-match-accent);
  --dnp-match-ga2: color-mix(in oklch, var(--dnp-match-accent) 62%, var(--dnp-match-card));
  --dnp-match-ga3: color-mix(in oklch, var(--dnp-match-accent) 30%, var(--dnp-match-card));
  --dnp-match-p0: var(--dnp-match-match);
  --dnp-match-p1: oklch(0.7 0.13 70);
  --dnp-match-p2: oklch(0.52 0.12 270);
  --dnp-match-good: oklch(0.56 0.12 160);
  --dnp-match-sans: system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  --dnp-match-mono: ui-monospace, "SF Mono", Menlo, Consolas, monospace;
  --dnp-match-out: cubic-bezier(.22, 1, .36, 1);
  color-scheme: light;
  border-radius: 16px;
  box-shadow: inset 0 0 0 1px var(--dnp-match-line);
}
.dnp-match__app { height: 100%; display: grid; grid-template-columns: 200px minmax(0, 1fr); grid-template-rows: auto minmax(0, 1fr); grid-template-areas: "nav top" "nav main"; }
.dnp-match__nav { grid-area: nav; min-height: 0; display: flex; flex-direction: column; gap: 18px; padding: 18px 12px; background: var(--dnp-match-ink); color: var(--dnp-match-card); border-radius: 16px 0 0 16px; }
.dnp-match__brand {
  display: flex; align-items: center; gap: 10px; padding: 0 4px;
  & .dnp-match__logo { width: 32px; height: 32px; border-radius: 10px; display: grid; place-items: center; background: var(--dnp-match-accent); color: var(--dnp-match-card); flex: none; }
  & .dnp-match__brandtx { display: grid; line-height: 1.15; }
  & b { font-size: 14px; font-weight: 720; }
  & small { font-size: 11px; color: color-mix(in oklch, var(--dnp-match-card) 60%, transparent); }
}
.dnp-match__navlist { display: grid; gap: 2px; }
.dnp-match__navbtn {
  position: relative; width: 100%; height: 36px; display: flex; align-items: center; gap: 10px; padding: 0 10px; border-radius: 9px; font-weight: 560;
  color: color-mix(in oklch, var(--dnp-match-card) 70%, transparent); transition: background-color .15s, color .15s;
  & span { flex: 1; text-align: left; white-space: nowrap; }
  & .dnp-match__navn { font: normal 700 10.5px var(--dnp-match-mono); padding: 1px 6px; border-radius: 99px; background: var(--dnp-match-accent); color: var(--dnp-match-card); }
  & .dnp-match__navn:empty { display: none; }
  &:hover { color: var(--dnp-match-card); background: color-mix(in oklch, var(--dnp-match-card) 9%, transparent); }
  &[aria-current="page"] { color: var(--dnp-match-ink); background: var(--dnp-match-card); }
  &:focus-visible { outline-color: var(--dnp-match-card); }
}
.dnp-match__navnote { margin-top: auto; padding: 0 4px; font-size: 11.5px; line-height: 1.5; color: color-mix(in oklch, var(--dnp-match-card) 58%, transparent); }
.dnp-match__top { grid-area: top; display: flex; align-items: end; justify-content: space-between; gap: 10px 20px; flex-wrap: wrap; padding: 18px 22px 12px; }
.dnp-match__title h2 { font-size: clamp(20px, 2.4cqi, 28px); font-weight: 780; letter-spacing: -.04em; line-height: 1.05; }
.dnp-match__sub { font-size: 12.5px; color: var(--dnp-match-faint); margin-top: 4px; }
.dnp-match__totals { display: grid; text-align: right; line-height: 1.1; & span { font-size: 11px; color: var(--dnp-match-faint); font-weight: 600; letter-spacing: .04em; text-transform: uppercase; } & b { font-size: clamp(20px, 2.4cqi, 28px); font-weight: 780; letter-spacing: -.04em; font-variant-numeric: tabular-nums; color: var(--dnp-match-accent); } }
.dnp-match__main { grid-area: main; min-height: 0; padding: 0 22px 18px; }
.dnp-match__view { height: 100%; transition: opacity .3s, translate .45s var(--dnp-match-out); @starting-style { opacity: 0; translate: 0 8px; } }
.dnp-match__panel { min-height: 0; min-width: 0; display: flex; flex-direction: column; border-radius: 14px; background: var(--dnp-match-card); box-shadow: 0 0 0 1px var(--dnp-match-line); }
.dnp-match__ph { display: flex; align-items: center; flex-wrap: wrap; gap: 6px 12px; padding: 12px 14px 6px; & h3 { font-size: 13px; font-weight: 720; margin-right: auto; } }
.dnp-match__phnote { font-size: 11px; color: var(--dnp-match-faint); }
/* uplift */
.dnp-match__uv { display: grid; gap: 12px; grid-template-columns: minmax(0, 1fr) 264px; grid-template-rows: auto minmax(0, 1fr); grid-template-areas: "kpis kpis" "wf miss"; }
.dnp-match__kpis { grid-area: kpis; display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); gap: 12px; }
.dnp-match__kpi { display: grid; gap: 1px; padding: 10px 14px; border-radius: 12px; background: var(--dnp-match-card); box-shadow: 0 0 0 1px var(--dnp-match-line); min-width: 0;
  & .dnp-match__kl { font-size: 11px; font-weight: 650; color: var(--dnp-match-faint); }
  & .dnp-match__kv { font-size: clamp(18px, 2.15cqi, 24px); font-weight: 760; letter-spacing: -.03em; line-height: 1.2; font-variant-numeric: tabular-nums; }
  & .dnp-match__ks { font-size: 11.5px; color: var(--dnp-match-mute); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; font-variant-numeric: tabular-nums; }
}
.dnp-match__kpi--hi { background: var(--dnp-match-accent); color: var(--dnp-match-card); box-shadow: none; & .dnp-match__kl, & .dnp-match__ks { color: color-mix(in oklch, var(--dnp-match-card) 82%, transparent); } }
.dnp-match__wfp { grid-area: wf; }
.dnp-match__plot { position: relative; flex: 1; min-height: 180px; margin: 0 8px 8px; }
.dnp-match__wf { position: absolute; inset: 0; width: 100%; height: 100%;
  & text { font: 10.5px var(--dnp-match-sans); fill: var(--dnp-match-faint); font-variant-numeric: tabular-nums; }
  & .dnp-match__gl { stroke: var(--dnp-match-hair); }
  & .dnp-match__lab { fill: var(--dnp-match-ink); font-weight: 650; font-size: 11.5px; }
  &.is-narrow .dnp-match__lab { font-size: 9.5px; }
  &.is-narrow .dnp-match__val { font-size: 10.5px; }
  & .dnp-match__val { fill: var(--dnp-match-ink); font-weight: 720; font-size: 12px; }
  & .dnp-match__con { stroke: var(--dnp-match-faint); stroke-dasharray: 2 3; }
  & .dnp-match__b { transition: opacity .15s; }
  & g:hover .dnp-match__b { opacity: .8; }
  & .dnp-match__brace { fill: none; stroke: var(--dnp-match-accent); stroke-width: 1.2; }
  & .dnp-match__bracetx { fill: var(--dnp-match-accent); font-weight: 700; font-size: 10.5px; paint-order: stroke; stroke: var(--dnp-match-card); stroke-width: 4px; }
  & .dnp-match__ghost { fill: none; stroke: var(--dnp-match-accent); stroke-width: 1.5; stroke-dasharray: 4 3; }
  & .dnp-match__ghosttx { fill: var(--dnp-match-accent); font-weight: 650; }
  &.is-intro .dnp-match__step { animation: dnp-match-drop .7s var(--dnp-match-out) both; animation-delay: calc(var(--i) * 120ms + 100ms); }
}
@keyframes dnp-match-drop { from { opacity: 0; translate: 0 -14px; } }
.dnp-match__miss { grid-area: miss; padding: 16px; gap: 12px;
  & .dnp-match__mk { font-size: 10.5px; font-weight: 700; letter-spacing: .07em; text-transform: uppercase; color: var(--dnp-match-accent); }
  & .dnp-match__mbig { font-size: 30px; font-weight: 780; letter-spacing: -.04em; font-variant-numeric: tabular-nums; line-height: 1; }
  & p { font-size: 12.5px; color: var(--dnp-match-mute); line-height: 1.55; }
  & p b { color: var(--dnp-match-ink); font-variant-numeric: tabular-nums; }
  & .dnp-match__split { display: flex; height: 10px; border-radius: 5px; overflow: hidden; gap: 2px; }
  & .dnp-match__split i { flex: var(--f); background: var(--c); }
  & .dnp-match__skey { display: grid; gap: 5px; font-size: 11.5px; color: var(--dnp-match-mute); }
  & .dnp-match__skey span { display: flex; align-items: center; gap: 6px; font-variant-numeric: tabular-nums; }
  & .dnp-match__skey i { width: 9px; height: 9px; border-radius: 2px; background: var(--c); }
  & .dnp-match__skey b { margin-left: auto; color: var(--dnp-match-ink); }
  & .dnp-match__btn { margin-top: auto; }
}
.dnp-match__btn {
  position: relative; overflow: hidden; height: 32px; padding: 0 14px; border-radius: 9px; font-size: 12.5px; font-weight: 680; background: var(--dnp-match-ink); color: var(--dnp-match-card);
  transition: background-color .15s, opacity .15s;
  & .dnp-match__bbar { position: absolute; inset: 0; background: var(--dnp-match-accent); transform-origin: left; scale: var(--dnp-match-fill) 1; }
  & .dnp-match__blab { position: relative; }
  &:hover:not(:disabled) { background: color-mix(in oklch, var(--dnp-match-ink), var(--dnp-match-accent) 30%); }
  &:disabled { opacity: .45; }
  &.is-busy { --dnp-match-fill: 1; transition: --dnp-match-fill 1.1s linear; }
}
.dnp-match__btn--soft { height: auto; min-height: 32px; padding-block: 7px; line-height: 1.3; text-wrap: balance; background: color-mix(in oklch, var(--dnp-match-accent) 12%, var(--dnp-match-card)); color: color-mix(in oklch, var(--dnp-match-accent), var(--dnp-match-ink) 25%); box-shadow: inset 0 0 0 1px color-mix(in oklch, var(--dnp-match-accent) 35%, transparent); &:hover:not(:disabled) { background: color-mix(in oklch, var(--dnp-match-accent) 20%, var(--dnp-match-card)); } }
/* gift aid */
.dnp-match__gv { display: grid; gap: 12px; grid-template-rows: auto minmax(0, 1fr); }
.dnp-match__pipe { display: grid; grid-template-columns: repeat(5, minmax(0, 1fr)); gap: 8px; }
.dnp-match__st {
  position: relative; display: grid; gap: 2px; text-align: left; padding: 10px 12px 11px; border-radius: 12px; background: var(--dnp-match-card); box-shadow: 0 0 0 1px var(--dnp-match-line);
  transition: box-shadow .2s, background-color .2s, translate .2s var(--dnp-match-out);
  & .dnp-match__sn { font-size: 11px; font-weight: 700; color: var(--dnp-match-faint); display: flex; align-items: center; gap: 6px; }
  & .dnp-match__sn i { width: 8px; height: 8px; border-radius: 50%; background: var(--c); }
  & .dnp-match__sv { font-size: 19px; font-weight: 760; letter-spacing: -.03em; font-variant-numeric: tabular-nums; }
  & .dnp-match__ss { font-size: 11px; color: var(--dnp-match-mute); font-variant-numeric: tabular-nums; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
  &:not(:last-child)::after { content: ""; position: absolute; right: -8px; top: 50%; width: 8px; height: 2px; background: var(--dnp-match-line); }
  &:hover { translate: 0 -1px; box-shadow: 0 0 0 1px color-mix(in oklch, var(--c) 50%, transparent), 0 6px 14px -10px var(--dnp-match-ink); }
  &[aria-checked="true"] { background: color-mix(in oklch, var(--c) 10%, var(--dnp-match-card)); box-shadow: 0 0 0 2px var(--c); }
  &.is-miss { --c: var(--dnp-match-faint); }
  &.is-miss::before { content: ""; position: absolute; inset: 0; border-radius: inherit; border: 1.5px dashed color-mix(in oklch, var(--dnp-match-ink) 25%, transparent); pointer-events: none; }
}
.dnp-match__gsum { font-size: 12px; color: var(--dnp-match-mute); font-variant-numeric: tabular-nums; margin-right: 6px; }
.dnp-match__gtp .dnp-match__ph h3 { margin-right: 0; }
.dnp-match__gsum { margin-right: auto; }
.dnp-match__tw { flex: 1; min-height: 0; margin: 0 6px 6px; }
.dnp-match__table { font-size: 12.5px; font-variant-numeric: tabular-nums;
  & th { position: sticky; top: 0; z-index: 1; background: var(--dnp-match-card); padding: 7px 10px; text-align: left; font-size: 11px; font-weight: 650; color: var(--dnp-match-faint); box-shadow: inset 0 -1px 0 var(--dnp-match-line); white-space: nowrap; }
  & th button { color: inherit; font-weight: inherit; display: inline-flex; gap: 5px; align-items: center; }
  & th button::after { content: "↕"; opacity: .35; font-size: 10px; }
  & th[aria-sort="ascending"] button, & th[aria-sort="descending"] button { color: var(--dnp-match-ink); }
  & th[aria-sort="ascending"] button::after { content: "↑"; opacity: 1; color: var(--dnp-match-accent); }
  & th[aria-sort="descending"] button::after { content: "↓"; opacity: 1; color: var(--dnp-match-accent); }
  & .dnp-match__num { text-align: right; }
  & th.dnp-match__num button { flex-direction: row-reverse; }
  & td { padding: 7px 10px; border-bottom: 1px solid var(--dnp-match-hair); white-space: nowrap; }
  & .dnp-match__ck { width: 34px; padding-right: 0; }
  & input[type="checkbox"] { width: 15px; height: 15px; margin: 0; cursor: pointer; }
  & tbody tr { transition: background-color .15s; }
  & tbody tr:hover { background: var(--dnp-match-hair); }
  & tbody tr:has(input:checked) { background: color-mix(in oklch, var(--dnp-match-accent) 8%, transparent); }
  & .dnp-match__sup b { font-weight: 620; display: block; }
  & .dnp-match__sup small { font-size: 11px; color: var(--dnp-match-faint); }
  & .dnp-match__chip { display: inline-block; font-size: 10.5px; font-weight: 650; padding: 1px 7px; border-radius: 99px; background: var(--dnp-match-hair); color: var(--dnp-match-mute); }
  & .dnp-match__chip.is-req { background: color-mix(in oklch, var(--dnp-match-match) 16%, transparent); color: var(--dnp-match-match); margin-left: 6px; }
  & .dnp-match__gav { color: var(--dnp-match-accent); font-weight: 650; }
  & .dnp-match__gav.is-pot { color: var(--dnp-match-faint); font-weight: 500; text-decoration: line-through; }
  & tbody tr.is-moving { animation: dnp-match-out .45s var(--dnp-match-out) both; }
}
@keyframes dnp-match-out { to { opacity: 0; translate: 24px 0; } }
.dnp-match__empty { padding: 30px 16px; text-align: center; color: var(--dnp-match-faint); }
/* pots */
.dnp-match__pv { display: grid; gap: 12px; grid-template-rows: auto minmax(0, 1fr); }
.dnp-match__pots { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 12px; }
.dnp-match__pot {
  position: relative; display: grid; gap: 6px; padding: 12px 14px; border-radius: 14px; background: var(--dnp-match-card); box-shadow: 0 0 0 1px var(--dnp-match-line);
  transition: box-shadow .2s, translate .2s var(--dnp-match-out);
  &:has(.dnp-match__pn:hover) { translate: 0 -1px; box-shadow: 0 0 0 1px color-mix(in oklch, var(--c) 50%, transparent), 0 8px 18px -12px var(--dnp-match-ink); }
  &:has(.dnp-match__pn[aria-pressed="true"]) { box-shadow: 0 0 0 2px var(--c); }
  & .dnp-match__pn { display: flex; align-items: center; gap: 8px; font-weight: 720; font-size: 13px; text-align: left; width: 100%; border-radius: 6px; }
  & .dnp-match__pn i { width: 10px; height: 10px; border-radius: 3px; background: var(--c); }
  & .dnp-match__pn em { margin-left: auto; font: normal 700 11px var(--dnp-match-mono); padding: 1px 7px; border-radius: 6px; background: color-mix(in oklch, var(--c) 14%, transparent); color: color-mix(in oklch, var(--c), var(--dnp-match-ink) 30%); }
  & .dnp-match__pr { font-size: 11.5px; color: var(--dnp-match-mute); }
  & .dnp-match__cap { position: relative; height: 12px; border-radius: 6px; background: var(--dnp-match-hair); overflow: hidden; }
  & .dnp-match__cap i { position: absolute; inset: 0; background: repeating-linear-gradient(-45deg, var(--c) 0 6px, color-mix(in oklch, var(--c), white 18%) 6px 12px); transform-origin: left; scale: var(--u) 1; transition: scale 1s var(--dnp-match-out); }
  & .dnp-match__nums { display: flex; justify-content: space-between; font-size: 11.5px; color: var(--dnp-match-mute); font-variant-numeric: tabular-nums; }
  & .dnp-match__nums b { color: var(--dnp-match-ink); }
  & .dnp-match__out { font-size: 11px; font-weight: 700; color: var(--dnp-match-accent); }
  & .dnp-match__top2 { justify-self: start; height: 26px; padding: 0 10px; border-radius: 8px; font-size: 11.5px; font-weight: 680; }
}
.dnp-match__pots.is-intro .dnp-match__cap i { animation: dnp-match-fillin 1.2s var(--dnp-match-out) both .2s; }
@keyframes dnp-match-fillin { from { scale: 0 1; } }
.dnp-match__mcp { min-height: 0; }
.dnp-match__mc { position: absolute; inset: 0; width: 100%; height: 100%; cursor: crosshair;
  & text { font: 10.5px var(--dnp-match-sans); fill: var(--dnp-match-faint); font-variant-numeric: tabular-nums; }
  & .dnp-match__gl { stroke: var(--dnp-match-hair); }
  & .dnp-match__area { opacity: .85; transition: opacity .25s; }
  &.has-focus .dnp-match__area:not(.is-focus) { opacity: .15; }
  & .dnp-match__evt { stroke: var(--dnp-match-accent); stroke-dasharray: 3 3; }
  & .dnp-match__evttx { fill: var(--dnp-match-accent); font-weight: 650; }
  & .dnp-match__xh { stroke: var(--dnp-match-ink); stroke-opacity: .45; opacity: 0; }
