}
@keyframes dnp-match-wipe { from { clip-path: inset(0 100% 0 0); } to { clip-path: inset(0 0 0 0); } }
/* responsive */
@supports (animation-timeline: scroll()) {
  .dnp-match__tw thead th { animation: dnp-match-shade linear both; animation-timeline: scroll(nearest block); animation-range: 0 40px; }
  @keyframes dnp-match-shade { to { box-shadow: inset 0 -1px 0 var(--dnp-match-line), 0 8px 14px -10px color-mix(in oklch, var(--dnp-match-ink) 45%, transparent); } }
}
@container dnp-match (max-width: 960px) {
  .dnp-match__app { grid-template-columns: 62px minmax(0, 1fr); }
