  .dnp-match__pipe { grid-template-columns: repeat(3, minmax(0, 1fr)); }
  .dnp-match__st:nth-child(3)::after { display: none; }
  .dnp-match__gtp { height: 460px; }
  .dnp-match__pots { grid-template-columns: minmax(0, 1fr); }
  .dnp-match__mcp { height: 340px; }
}
@container dnp-match (max-width: 760px) {
  .dnp-match__app { grid-template-columns: minmax(0, 1fr); grid-template-rows: auto auto minmax(0, 1fr); grid-template-areas: "nav" "top" "main"; }
  .dnp-match__nav { flex-direction: row; align-items: center; padding: 10px 14px; border-radius: 16px 16px 0 0; }
  .dnp-match__nav .dnp-match__brand .dnp-match__brandtx { display: grid; }
  .dnp-match__navlist { display: flex; margin-left: auto; gap: 4px; }
  .dnp-match__top { padding: 14px 14px 10px; }
  .dnp-match__totals { text-align: left; }
  .dnp-match__main { padding: 0 14px 14px; }
}
@container dnp-match (max-width: 480px) {
  .dnp-match__nav .dnp-match__brand .dnp-match__brandtx { display: none; }
  .dnp-match__pipe { grid-template-columns: repeat(2, minmax(0, 1fr)); }
  .dnp-match__st::after { display: none; }
  .dnp-match__hide-s { display: none; }
}

