  o += '<line class="dnp-match__con" x1="' + (m.l + (steps.length - 1) * bw + bw * .84) + '" x2="' + gx + '" y1="' + y(t.total) + '" y2="' + y(t.total) + '"/>';
  { const x1 = m.l + bw + bw * .16, x2 = m.l + 4 * bw - bw * .16, yb = H - 36; o += '<path class="dnp-match__brace" d="M' + x1 + ',' + (yb - 4) + 'v4H' + x2 + 'v-4"/><text class="dnp-match__bracetx" x="' + ((x1 + x2) / 2) + '" y="' + (yb + 1) + '" text-anchor="middle">Gift Aid ' + fv(t.gaT) + '</text>'; }
