    '<div class="dnp-match__split" aria-hidden="true"><i style="--f:' + elig + ';--c:var(--dnp-match-accent)"></i><i style="--f:' + ms + ';--c:var(--dnp-match-ga3)"></i><i style="--f:' + inel + ';--c:var(--dnp-match-hair)"></i></div>' +
