  $('.dnp-match__gsum').textContent = NF.format(list.length) + ' gifts · ' + gbp(sum(list.map(g => g.amt))) + ' given · ' + gbp2(sum(list.map(GA))) + (S.stage === 'missing' ? ' Gift Aid possible' : ' Gift Aid');
