    '<td class="dnp-match__sup"><b>' + esc(g.name) + (g.req ? '<span class="dnp-match__chip is-req">Asked to sign</span>' : '') + '</b><small>' + (g.match.some(Boolean) ? 'Matched by ' + POTS[g.match.findIndex(Boolean)].by : 'Not matched') + '</small></td><td class="dnp-match__hide-s"><span class="dnp-match__chip">' + CHANNELS[g.ch] + '</span></td>' +
    '<td class="dnp-match__num"><b>' + gbp2(g.amt) + '</b></td><td class="dnp-match__num"><span class="dnp-match__gav' + (S.stage === 'missing' ? ' is-pot' : '') + '">+' + gbp2(GA(g)) + '</span></td><td class="dnp-match__num">' + dl(g.d) + '</td></tr>').join('') : '<tr><td colspan="6" class="dnp-match__empty">' + (S.stage === 'batched' ? 'The batch is empty. Add gifts from “Ready to claim”.' : S.stage === 'ready' ? 'Every eligible gift is already in a claim.' : 'No gifts at this stage.') + '</td></tr>';
