css:
.dnp-event {
  width: 100%;
  height: var(--dnp-event-h, 680px);
  container-type: inline-size;
  container-name: dnp-event;
  position: relative;
  isolation: isolate;
  overflow: hidden;
  background: var(--dnp-event-bg);
  color: var(--dnp-event-ink);
  font: 13px/1.45 var(--dnp-event-sans);
  accent-color: var(--dnp-event-accent);
  -webkit-font-smoothing: antialiased;
  & *, & *::before, & *::after { box-sizing: border-box; }
  & :where(h1, h2, h3, h4, p, ol, ul, dl, dd, figure) { margin: 0; padding: 0; }
  & :where(ol, ul) { list-style: none; }
  & :where(h1, h2, h3, h4) { text-wrap: balance; font-weight: 650; }
  & :where(p) { text-wrap: pretty; }
  & :where(button, input, select) { font: inherit; color: inherit; letter-spacing: inherit; }
  & :where(button) { background: none; border: 0; padding: 0; cursor: pointer; -webkit-tap-highlight-color: transparent; }
  & :where(button:disabled, [aria-disabled="true"]) { cursor: not-allowed; }
  & :where(svg) { display: block; overflow: visible; }
  & :where(table) { border-collapse: collapse; width: 100%; }
  & :focus-visible { outline: 2px solid var(--dnp-event-focus, var(--dnp-event-accent)); outline-offset: 2px; }
  & [hidden] { display: none !important; }
  & .dnp-event__i { width: 18px; height: 18px; flex: none; fill: none; stroke: currentColor; stroke-width: 1.75; stroke-linecap: round; stroke-linejoin: round; }
  & .dnp-event__sr { position: absolute; width: 1px; height: 1px; overflow: hidden; clip-path: inset(50%); white-space: nowrap; }
}
.dnp-event__scroll {
  overflow: auto;
  overscroll-behavior: contain;
  scrollbar-width: thin;
  scrollbar-color: color-mix(in oklch, var(--dnp-event-ink) 22%, transparent) transparent;
