.dnp-event__gbar { height: 8px; border-radius: 4px; background: var(--dnp-event-hair); overflow: hidden; & i { display: block; height: 100%; width: calc(var(--dnp-event-goal) * 100%); border-radius: inherit; background: linear-gradient(to right, var(--dnp-event-hot), var(--dnp-event-accent)); transition: --dnp-event-goal 1.4s var(--dnp-event-out); } }
.dnp-event__main { grid-area: main; min-height: 0; padding: 0 22px 18px; }
