}
.dnp-event__btn { height: 32px; padding: 0 14px; border-radius: 9px; font-size: 12.5px; font-weight: 680; background: var(--dnp-event-accent); color: var(--dnp-event-bg); transition: filter .15s, opacity .15s; &:hover:not(:disabled) { filter: brightness(1.08); } &:disabled { opacity: .45; } }
