  & .dnp-event__ebar i::after { content: ""; display: block; height: 100%; width: calc(var(--w) * 100%); background: var(--c, var(--dnp-event-accent)); border-radius: inherit; transform-origin: left; animation: dnp-event-grow .8s var(--dnp-event-out) both; }
